#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SkirmishFaction {
    Alliance,
    Demon,
    Chaos,
}

impl SkirmishFaction {
    const ALL: [Self; 3] = [Self::Alliance, Self::Demon, Self::Chaos];

    fn registry_id(self) -> &'static str {
        match self {
            Self::Alliance => "alliance",
            Self::Demon => "demon",
            Self::Chaos => "chaos",
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Alliance => "人族",
            Self::Demon => "魔族",
            Self::Chaos => "混沌族",
        }
    }

    fn default_team(self) -> Team {
        match self {
            Self::Alliance => Team::Human,
            Self::Demon => Team::Demon,
            Self::Chaos => Team::Chaos,
        }
    }

    fn from_team(team: Team) -> Self {
        match team {
            Team::Human | Team::Neutral => Self::Alliance,
            Team::Demon => Self::Demon,
            Team::Chaos => Self::Chaos,
        }
    }

    fn next(self) -> Self {
        let index = Self::ALL
            .iter()
            .position(|faction| *faction == self)
            .unwrap_or(0);
        Self::ALL[(index + 1) % Self::ALL.len()]
    }
}

