#[derive(Resource, Clone, Copy, Debug, PartialEq, Eq)]
struct AiDifficultySettings {
    human: AiDifficulty,
    demon: AiDifficulty,
    chaos: AiDifficulty,
}

impl AiDifficultySettings {
    fn difficulty(&self, team: Team) -> AiDifficulty {
        match team {
            Team::Human => self.human,
            Team::Demon => self.demon,
            Team::Chaos => self.chaos,
            Team::Neutral => AiDifficulty::Normal,
        }
    }

    #[cfg(test)]
    fn all_ai(ai_difficulty: AiDifficulty) -> Self {
        let mut settings = Self::default();
        for team in Team::all() {
            settings.set_difficulty(team, ai_difficulty);
        }
        settings
    }

    fn set_difficulty(&mut self, team: Team, difficulty: AiDifficulty) {
        match team {
            Team::Human => self.human = difficulty,
            Team::Demon => self.demon = difficulty,
            Team::Chaos => self.chaos = difficulty,
            Team::Neutral => {}
        }
    }

    fn default_ai_difficulty(&self, player_team: Team) -> AiDifficulty {
        active_ai_teams(Some(player_team), None)
            .next()
            .map(|team| self.difficulty(team))
            .unwrap_or(AiDifficulty::Normal)
    }
}

impl Default for AiDifficultySettings {
    fn default() -> Self {
        let _available_difficulties = AiDifficulty::ALL;
        Self {
            human: AiDifficulty::Normal,
            demon: AiDifficulty::Normal,
            chaos: AiDifficulty::Normal,
        }
    }
}

