    #[test]
    fn skirmish_random_map_resolves_to_compatible_real_map_like_godot() {
        let selection = skirmish_menu_selection(
            random_map_index(),
            Team::Human,
            GODOT_STANDARD_STARTING_RESOURCE_INDEX,
            SkirmishMatchMode::ThreeFaction,
            AiDifficulty::Normal,
        );

        assert!(selection.map_choice_is_random());
        assert_eq!(selection.map_label(), RANDOM_MAP_LABEL);
        assert_eq!(selection.required_player_slots(), 3);

        for seed in 0..16 {
            let setup = selection.match_setup_with_map_seed(seed);
            let map = skirmish_map_by_path(setup.map_path)
                .expect("random map should resolve to a registered real map path");
            assert!(
                map.players >= selection.required_player_slots(),
                "random map should be compatible with the active skirmish teams"
            );
        }
    }

    #[test]
    fn skirmish_random_map_filters_by_required_slots_and_falls_back_like_godot() {
        let eight_slot_candidates = random_map_candidates_for_required_slots(8)
            .map(|map| map.id)
            .collect::<Vec<_>>();

        assert_eq!(eight_slot_candidates, vec!["big_arena"]);
        assert_eq!(
            random_map_for_required_slots(8, 97).godot_path,
            "res://source/match/maps/BigArena.tscn"
        );
        assert_eq!(
            random_map_for_required_slots(99, 0).godot_path,
            largest_skirmish_map().godot_path,
            "Godot falls back to the largest map when no compatible random-map candidate exists"
        );
    }

    #[test]
    fn skirmish_random_map_uses_roulette_buckets_without_changing_seed_order() {
        let candidates = random_map_candidates_for_required_slots(2).collect::<Vec<_>>();
        assert!(
            candidates.len() > 1,
            "test should cover multiple random-map buckets"
        );

        for seed in 0..candidates.len() * 2 {
            let expected = candidates[seed % candidates.len()];
            assert_eq!(
                random_map_for_required_slots(2, seed as u32).id,
                expected.id
            );
        }
    }

    #[test]
    fn skirmish_start_status_rejects_maps_without_required_spawn_slots_like_godot() {
        assert_eq!(skirmish_start_status(2, 2), SkirmishStartStatus::Ready);
        assert_eq!(skirmish_start_status(3, 4), SkirmishStartStatus::Ready);
        assert_eq!(
            skirmish_start_status(3, 2),
            SkirmishStartStatus::MapTooSmall {
                required_slots: 3,
                available_slots: 2
            }
        );
        assert!(!skirmish_start_status(3, 2).can_start());
        assert_eq!(
            skirmish_start_status(3, 2).summary_label(),
            "状态: 地图出生点不足(2/3)"
        );
    }

    #[test]
    fn skirmish_start_status_rejects_setups_with_too_few_players_like_godot() {
        let relations = TeamRelations::default();

        assert_eq!(
            skirmish_start_status_for_setup(2, 2, [true, false, false], &relations),
            SkirmishStartStatus::NotEnoughPlayers {
                active_players: 1,
                required_players: 2
            }
        );
        assert_eq!(
            skirmish_start_status_for_setup(2, 2, [false, false, false], &relations)
                .summary_label(),
            "状态: 需要至少2名玩家(0/2)"
        );
        assert!(
            !skirmish_start_status_for_setup(2, 2, [true, false, false], &relations).can_start()
        );
    }

