    #[test]
    fn skirmish_player_faction_options_write_match_setup_like_godot() {
        let mut selection = SkirmishMenuSelection::default();
        selection.cycle_player_faction(Team::Human);
        selection.cycle_player_faction(Team::Chaos);

        assert_eq!(
            selection.player_faction(Team::Human),
            Some(SkirmishFaction::Demon)
        );
        assert_eq!(
            selection.player_faction(Team::Demon),
            Some(SkirmishFaction::Demon)
        );
        assert_eq!(
            selection.player_faction(Team::Chaos),
            Some(SkirmishFaction::Alliance)
        );

        let settings = selection.match_setup();
        assert_eq!(
            settings.player_factions,
            [
                SkirmishFaction::Demon,
                SkirmishFaction::Demon,
                SkirmishFaction::Alliance
            ]
        );
        assert_eq!(
            SkirmishMenuSelection::from_match_setup(settings).player_factions,
            settings.player_factions,
            "returning from a match should preserve Godot-style per-player faction choices"
        );
        assert!(main_menu_summary_text(selection).contains("种族: 人族=魔族/魔族=魔族"));
        assert!(
            main_menu_faction_info_text(selection).contains("魔族: 火力突击"),
            "the selected slot's faction info should follow player_factions instead of the slot id"
        );
    }

    #[test]
    fn skirmish_player_controller_options_drive_active_teams_like_godot() {
        let mut selection = SkirmishMenuSelection::default();

        selection.set_player_controller(Team::Demon, SkirmishPlayerController::None);
        assert_eq!(selection.active_teams(), [true, false, false]);
        assert_eq!(
            selection.start_status(),
            SkirmishStartStatus::NotEnoughPlayers {
                active_players: 1,
                required_players: 2
            }
        );
        assert!(!selection.can_start());

        selection.set_player_controller(
            Team::Chaos,
            SkirmishPlayerController::Ai(AiDifficulty::Hard),
        );
        assert_eq!(selection.active_teams(), [true, false, true]);
        assert!(selection.can_start());

        let settings = selection.match_setup();
        assert_eq!(settings.active_teams, [true, false, true]);
        assert_eq!(
            settings.ai_difficulties.difficulty(Team::Chaos),
            AiDifficulty::Hard
        );
        assert_eq!(
            SkirmishMenuSelection::from_match_setup(settings).player_controllers,
            selection.player_controllers
        );
    }

    #[test]
    fn skirmish_player_controller_options_enforce_single_human_like_godot() {
        let mut selection = SkirmishMenuSelection::default();

        selection.set_player_controller(Team::Demon, SkirmishPlayerController::Human);

        assert_eq!(selection.faction, Team::Demon);
        assert_eq!(
            selection.player_controller(Team::Demon),
            Some(SkirmishPlayerController::Human)
        );
        assert_eq!(
            selection.player_controller(Team::Human),
            Some(SkirmishPlayerController::Ai(AiDifficulty::Easy)),
            "turning one slot human should demote the previous human slot to AI like Godot"
        );
        assert_eq!(selection.human_team(), Some(Team::Demon));
    }

