    #[test]
    fn faction_battle_traits_are_distinct_and_composable() {
        assert_close(
            faction_support_rate_multiplier(Team::Human),
            HUMAN_SUPPORT_RATE_MULTIPLIER,
        );
        assert_close(faction_support_rate_multiplier(Team::Demon), 1.0);
        assert_close(
            faction_weapon_damage_multiplier(Team::Demon, Team::Human, true),
            DEMON_STRUCTURE_WEAPON_DAMAGE_MULTIPLIER,
        );
        assert_close(
            faction_weapon_damage_multiplier(Team::Demon, Team::Human, false),
            1.0,
        );
        assert_close(
            faction_incoming_weapon_damage_scale(Team::Chaos),
            CHAOS_INCOMING_WEAPON_DAMAGE_SCALE,
        );
        assert_close(faction_incoming_weapon_damage_scale(Team::Human), 1.0);

        let active_shield = SupportShield {
            remaining: 1.0,
            damage_scale: 0.5,
        };
        let passive_shield = PassiveSupportShield { damage_scale: 0.7 };
        assert_close(
            applied_weapon_damage(10.0, Team::Demon, Team::Human, true, None, None),
            10.0 * DEMON_STRUCTURE_WEAPON_DAMAGE_MULTIPLIER,
        );
        assert_close(
            applied_weapon_damage(
                10.0,
                Team::Human,
                Team::Chaos,
                false,
                Some(&active_shield),
                Some(&passive_shield),
            ),
            10.0 * CHAOS_INCOMING_WEAPON_DAMAGE_SCALE * active_shield.damage_scale,
        );
    }

