    #[test]
    fn rts_camera_defaults_to_base_scale_zoom_limits() {
        let focus = Vec3::new(-12.0, 0.0, -9.0);
        let camera = RtsCamera::focused_on(focus);

        assert_eq!(camera.focus, focus);
        assert_eq!(camera.distance, CAMERA_DEFAULT_DISTANCE);
        assert!(camera.distance <= 8.0);
        assert!(CAMERA_MAX_DISTANCE <= 10.5);
        let Projection::Orthographic(projection) = camera_projection_from_state(&camera) else {
            panic!("RTS camera should use Godot-style orthographic projection");
        };
        let ScalingMode::FixedVertical { viewport_height } = projection.scaling_mode else {
            panic!("RTS camera zoom should control fixed vertical world height");
        };
        assert_eq!(viewport_height, CAMERA_DEFAULT_DISTANCE);
        assert_eq!(projection.near, CAMERA_NEAR_PLANE);
        assert_eq!(projection.far, CAMERA_FAR_PLANE);
    }

    #[test]
    fn rts_camera_scroll_zoom_is_clamped_for_playable_base_view() {
        assert_eq!(
            camera_zoom_distance_after_scroll(CAMERA_DEFAULT_DISTANCE, 100.0),
            CAMERA_MIN_DISTANCE
        );
        assert_eq!(
            camera_zoom_distance_after_scroll(CAMERA_DEFAULT_DISTANCE, -100.0),
            CAMERA_MAX_DISTANCE
        );
    }

    #[test]
    fn rts_camera_safe_view_clamps_focus_and_zoom_like_godot() {
        let bounds = MapBounds::from_size((20.0, 14.0));
        let mut camera = RtsCamera {
            focus: Vec3::new(48.0, 0.0, -48.0),
            distance: 48.0,
            yaw: CAMERA_DEFAULT_YAW,
            pitch: CAMERA_DEFAULT_PITCH,
            edge_pan_active: false,
        };

        clamp_camera_view_safely(&mut camera, bounds);

        assert_eq!(
            camera.focus,
            safe_camera_focus(Vec3::new(48.0, 0.0, -48.0), bounds)
        );
        assert_eq!(camera.distance, CAMERA_MAX_DISTANCE);
    }

    #[test]
    fn rts_camera_scroll_zoom_uses_godot_fixed_size_steps() {
        assert_eq!(
            camera_zoom_distance_after_scroll(CAMERA_DEFAULT_DISTANCE, 1.0),
            CAMERA_DEFAULT_DISTANCE - 1.0,
            "Godot wheel-up zooms in by reducing orthographic size by one step"
        );
        assert_eq!(
            camera_zoom_distance_after_scroll(CAMERA_DEFAULT_DISTANCE, -1.0),
            CAMERA_DEFAULT_DISTANCE + 1.0,
            "Godot wheel-down zooms out by increasing orthographic size by one step"
        );
    }

