    #[test]
    fn camera_middle_drag_rotation_uses_horizontal_mouse_delta_like_godot() {
        let mut camera = RtsCamera {
            yaw: 0.75,
            ..RtsCamera::default()
        };
        let mut rotation = CameraMouseRotation::default();

        begin_camera_mouse_rotation(&mut rotation, camera.yaw, 3.0);
        apply_camera_mouse_rotation(&mut camera, &mut rotation, 20.0);
        assert!((camera.yaw - 0.85).abs() < 0.001);

        apply_camera_mouse_rotation(&mut camera, &mut rotation, -5.0);
        assert!((camera.yaw - 0.825).abs() < 0.001);
        assert_eq!(rotation.last_middle_press_time, Some(3.0));
    }

    #[test]
    fn camera_middle_double_click_resets_rotation_without_moving_focus() {
        let focus = Vec3::new(12.0, 0.0, -6.0);
        let mut camera = RtsCamera {
            focus,
            yaw: 1.2,
            ..RtsCamera::default()
        };
        let mut rotation = CameraMouseRotation {
            active: true,
            accumulated_x: 42.0,
            ..CameraMouseRotation::default()
        };

        reset_camera_rotation(&mut camera, &mut rotation);

        assert_eq!(camera.focus, focus);
        assert_eq!(camera.yaw, CAMERA_DEFAULT_YAW);
        assert!(!rotation.active);
        assert_eq!(rotation.accumulated_x, 0.0);
    }

