    #[test]
    fn spectator_perspective_cycle_skips_inactive_teams_and_preserves_visibility() {
        let active_default_skirmish = ActiveTeams([true, true, false]);
        let mut visible_player = VisiblePlayer::all_players(Team::Demon);

        assert!(cycle_spectator_visible_player(
            &mut visible_player,
            &active_default_skirmish,
            1
        ));
        assert_eq!(visible_player, VisiblePlayer::all_players(Team::Human));

        assert!(cycle_spectator_visible_player(
            &mut visible_player,
            &active_default_skirmish,
            -1
        ));
        assert_eq!(visible_player, VisiblePlayer::all_players(Team::Demon));

        let mut player_controlled = VisiblePlayer::per_player(Team::Human);
        assert!(!cycle_spectator_visible_player(
            &mut player_controlled,
            &active_default_skirmish,
            1
        ));
        assert_eq!(player_controlled, VisiblePlayer::per_player(Team::Human));

        let mut fogged_spectator = VisiblePlayer::spectator_per_player(Team::Human);
        assert!(cycle_spectator_visible_player(
            &mut fogged_spectator,
            &active_default_skirmish,
            1
        ));
        assert_eq!(
            fogged_spectator,
            VisiblePlayer::spectator_per_player(Team::Demon)
        );

        let mut three_way_spectator = VisiblePlayer::all_players(Team::Human);
        assert!(cycle_spectator_visible_player(
            &mut three_way_spectator,
            &ActiveTeams([true, true, true]),
            1
        ));
        assert_eq!(three_way_spectator.team, Team::Demon);
        assert!(cycle_spectator_visible_player(
            &mut three_way_spectator,
            &ActiveTeams([true, true, true]),
            1
        ));
        assert_eq!(three_way_spectator.team, Team::Chaos);
    }

