    fn spawn_test_unit(app: &mut App, id: &'static str, team: Team, position: Vec3) -> Entity {
        let def = registry::entity(id).expect("registry should include test unit");
        let entity = app
            .world_mut()
            .spawn((
                team,
                test_unit(id),
                MovementDomain::from_registry(def.domain),
                Transform::from_translation(position),
                Selectable { radius: def.radius },
                Health::new(def.health),
                VisionRadius(def.sight_range),
                Veterancy {
                    rank: 0,
                    experience_points: 0,
                    base_health: def.health,
                    base_damage: def.weapon.map_or(0.0, |weapon| weapon.damage),
                    base_range: def.weapon.map_or(0.0, |weapon| weapon.range),
                    base_vision: def.sight_range,
                },
            ))
            .id();
        if let Some(weapon) = def.weapon {
            app.world_mut().entity_mut(entity).insert(Weapon::new(
                weapon.range,
                weapon.damage,
                weapon.cooldown,
                weapon.splash_radius,
                weapon.splash_damage_multiplier,
                weapon.structure_damage_multiplier,
                weapon.can_attack_air,
                weapon.can_attack_ground,
            ));
        }
        entity
    }

    fn insert_test_deployed_siege_mode(
        app: &mut App,
        entity: Entity,
        previous_hold_position: bool,
    ) {
        let def = registry::entity("SiegeDrillTank").expect("registry should include siege drill");
        let base_weapon = def.weapon.expect("siege drill should have weapon");
        app.world_mut().entity_mut(entity).insert((
            HoldPosition { enabled: true },
            DeployedSiegeMode {
                previous_hold_position,
                base_speed: def.speed,
                base_attack_range: base_weapon.range,
                base_attack_interval: base_weapon.cooldown,
                base_structure_damage_multiplier: base_weapon.structure_damage_multiplier,
                base_sight_range: def.sight_range,
            },
        ));
        {
            let mut entity_mut = app.world_mut().entity_mut(entity);
            entity_mut
                .get_mut::<Unit>()
                .expect("drill should be a unit")
                .speed = 0.0;
        }
        {
            let mut entity_mut = app.world_mut().entity_mut(entity);
            let mut weapon = entity_mut
                .get_mut::<Weapon>()
                .expect("drill should have weapon");
            weapon.range = SIEGE_DRILL_DEPLOYED_ATTACK_RANGE;
            weapon.cooldown = SIEGE_DRILL_DEPLOYED_ATTACK_INTERVAL;
            weapon.structure_damage_multiplier = SIEGE_DRILL_DEPLOYED_STRUCTURE_DAMAGE_MULTIPLIER;
        }
        {
            let mut entity_mut = app.world_mut().entity_mut(entity);
            entity_mut
                .get_mut::<VisionRadius>()
                .expect("drill should have vision")
                .0 = SIEGE_DRILL_DEPLOYED_SIGHT_RANGE;
        }
    }

    #[derive(Resource)]
    struct IssueOrQueueOrderProbe {
        entity: Entity,
        order: UnitQueuedOrder,
        queue_mode: bool,
        allow_queue: bool,
        has_active: bool,
        attempted: bool,
    }

    fn issue_or_queue_order_test_app() -> App {
        let mut app = App::new();
        app.add_plugins(MinimalPlugins)
            .add_systems(Update, run_issue_or_queue_order_probe);
        app
    }

    fn run_issue_or_queue_order_probe(
        mut commands: Commands,
        mut probe: ResMut<IssueOrQueueOrderProbe>,
        queues: Query<&OrderQueue>,
    ) {
        if probe.attempted {
            return;
        }
        probe.attempted = true;
        let queue = queues.get(probe.entity).ok();
        issue_or_queue_unit_order(
            &mut commands,
            probe.entity,
            probe.order.clone(),
            probe.queue_mode,
            probe.allow_queue,
            probe.has_active,
            queue,
        );
    }

    fn crush_test_app() -> App {
        let mut app = App::new();
        app.add_plugins((
            MinimalPlugins,
            AssetPlugin {
                meta_check: AssetMetaCheck::Never,
                ..default()
            },
            bevy::world_serialization::WorldSerializationPlugin,
        ))
        .insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(
            Duration::from_secs_f32(1.0),
        ))
        .init_resource::<TeamRelations>()
        .init_resource::<KillCredits>()
        .init_resource::<MatchState>()
        .init_resource::<LatestBattleEvent>()
        .init_resource::<BattleLog>()
        .init_resource::<AudioFeedback>()
        .add_systems(Update, (move_units, apply_kill_credits).chain());
        app
    }

    fn run_crush_frames(app: &mut App) {
        for _ in 0..24 {
            app.update();
        }
    }

    #[test]
    fn movement_direction_steers_around_static_obstacles() {
        let desired = Vec3::X;
        let obstacle = MovementObstacleSnapshot {
            position: Vec3::new(2.0, 0.0, 0.0),
            radius: 0.9,
        };

        let clear_direction = movement_direction_around_static_obstacles(
            Vec3::ZERO,
            Vec3::new(8.0, 0.0, 0.0),
            desired,
            0.4,
            &[],
        );
        assert_eq!(clear_direction, desired);

        let steered_direction = movement_direction_around_static_obstacles(
            Vec3::ZERO,
            Vec3::new(8.0, 0.0, 0.0),
            desired,
            0.4,
            &[obstacle],
        );
        assert!(
            steered_direction.x > 0.2,
            "steering should continue toward the order target"
        );
        assert!(
            steered_direction.z < -0.2,
            "head-on obstacles should produce a stable side-step"
        );
        assert!(
            distance_point_to_xz_segment(
                obstacle.position,
                Vec3::ZERO,
                steered_direction * MOVEMENT_OBSTACLE_LOOKAHEAD_M,
            ) > 0.9,
            "steered lookahead should move away from the obstacle center"
        );
    }

    #[test]
    fn movement_direction_keeps_contact_target_obstacle_reachable() {
        let source = Vec3::ZERO;
        let source_radius = 0.4;
        let obstacle = MovementObstacleSnapshot {
            position: Vec3::new(2.0, 0.0, 0.0),
            radius: 0.9,
        };
        let contact_target = unit_contact_move_target_position(
            source,
            source_radius,
            obstacle.position,
            obstacle.radius,
        );
        let desired = (contact_target - source).normalize();

        let direction = movement_direction_around_static_obstacles(
            source,
            contact_target,
            desired,
            source_radius,
            &[obstacle],
        );

        assert_eq!(
            direction, desired,
            "the target resource/building sits behind its contact point and should not repel the mover"
        );
    }

    #[test]
    fn terrain_units_steer_around_static_buildings() {
        let mut app = crush_test_app();
        let worker = spawn_test_unit(&mut app, "Worker", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(worker).insert(MoveOrder {
            target: Vec3::new(8.0, 0.0, 0.0),
        });
        spawn_test_structure(
            &mut app,
            "CommandCenter",
            Team::Human,
            Vec3::new(2.0, 0.0, 0.0),
        );

        app.update();
        app.update();
        app.update();

        let position = app
            .world()
            .entity(worker)
            .get::<Transform>()
            .unwrap()
            .translation;
        assert!(
            position.x > 0.1,
            "worker should keep advancing toward the move order"
        );
        assert!(
            position.z < -0.1,
            "worker should steer sideways instead of moving straight through the building"
        );
    }

    #[test]
    fn immobile_units_clear_raw_move_orders_like_godot_moving_applicability() {
        let mut app = crush_test_app();
        let unit = spawn_test_unit(&mut app, "SiegeDrillTank", Team::Human, Vec3::ZERO);
        {
            let mut unit_entity = app.world_mut().entity_mut(unit);
            unit_entity
                .get_mut::<Unit>()
                .expect("test unit should have Unit")
                .speed = 0.0;
            unit_entity.insert(MoveOrder {
                target: Vec3::new(8.0, 0.0, 0.0),
            });
        }

        app.update();

        let unit_ref = app.world().entity(unit);
        assert!(
            unit_ref.get::<MoveOrder>().is_none(),
            "Godot Moving.is_applicable rejects sources that cannot receive movement"
        );
        assert_eq!(
            unit_ref
                .get::<Transform>()
                .expect("test unit should have Transform")
                .translation,
            Vec3::ZERO
        );
    }

