    #[derive(Resource)]
    struct CommandActionsProbe {
        team: Team,
        faction: SkirmishFaction,
        actions: Vec<BuildAction>,
        enabled_actions: Vec<(BuildAction, bool)>,
    }

    impl Default for CommandActionsProbe {
        fn default() -> Self {
            Self {
                team: Team::Human,
                faction: SkirmishFaction::Alliance,
                actions: Vec::new(),
                enabled_actions: Vec::new(),
            }
        }
    }

    fn run_command_actions_probe(
        selected_units: Query<CommandPanelUnitItem<'_>, With<Selected>>,
        selected_structures: Query<SelectedRepairStructureItem<'_>, With<Selected>>,
        producer_structures: Query<StructureEntityItem<'_>>,
        structures: Query<StructurePrereqItem<'_>>,
        build_queue: Res<BuildQueue>,
        mut probe: ResMut<CommandActionsProbe>,
    ) {
        let actions = current_command_actions_for_faction(
            probe.team,
            probe.faction,
            &selected_units,
            &selected_structures,
            &structures,
        );
        probe.enabled_actions = actions
            .iter()
            .map(|action| {
                (
                    *action,
                    command_action_enabled_for_panel(
                        probe.team,
                        probe.faction,
                        *action,
                        &selected_units,
                        &selected_structures,
                        &producer_structures,
                        &structures,
                        &build_queue,
                    ),
                )
            })
            .collect();
        probe.actions = actions;
    }

