    fn insert_registry_income_source(app: &mut App, entity: Entity, id: &'static str) {
        let def = registry::entity(id).expect("registry should include income source");
        if def.income_interval > 0.0
            && (def.resource_income_ore > 0 || def.resource_income_crystal > 0)
        {
            app.world_mut().entity_mut(entity).insert(IncomeSource {
                ore: def.resource_income_ore,
                crystal: def.resource_income_crystal,
                interval: def.income_interval,
                remaining: def.income_interval,
            });
        }
    }

    fn insert_registry_structure_combat_traits(app: &mut App, entity: Entity, id: &'static str) {
        let def = registry::entity(id).expect("registry should include test structure");
        if let Some(weapon) = def.weapon {
            app.world_mut().entity_mut(entity).insert(Weapon::new(
                weapon.range,
                weapon.damage,
                weapon.cooldown,
                weapon.splash_radius,
                weapon.splash_damage_multiplier,
                weapon.structure_damage_multiplier,
                weapon.can_attack_air,
                weapon.can_attack_ground,
            ));
        }
        if def.garrison_capacity > 0 && def.garrison_attack_damage_per_unit > 0.0 {
            app.world_mut().entity_mut(entity).insert(Garrison {
                capacity: def.garrison_capacity,
                damage_per_unit: def.garrison_attack_damage_per_unit,
                count: 0,
            });
        }
    }

