    fn activate_test_support_power(
        mut commands: Commands,
        mut activation: ResMut<TestSupportActivation>,
        economies: Res<Economies>,
        relations: Res<TeamRelations>,
        mut support_cooldowns: ResMut<SupportCooldowns>,
        mut battle_log: ResMut<BattleLog>,
        structures: Query<StructurePrereqItem<'_>>,
        units: Query<(Entity, &Team, &Transform, &Selectable, &Health, &Unit), With<Unit>>,
        structure_targets: Query<CaptureStructureTargetItem<'_>, With<Structure>>,
    ) {
        if activation.result.is_some() {
            return;
        }
        let power = activation.power;
        let team = activation.team;
        let target = activation.target;
        let support_targets = ai_support_power_targets(&units, &structure_targets);
        activation.result = Some(activate_support_power(
            &mut commands,
            target,
            power,
            team,
            Team::Human,
            &economies,
            &mut support_cooldowns,
            &mut battle_log,
            &relations,
            &structures,
            &support_targets,
        ));
    }

