    fn anchor_targets_by_team(app: &mut App, team: Team) -> Vec<(Entity, Vec3)> {
        let mut targets = Vec::new();
        {
            let world = app.world_mut();
            let mut structures = world
                .query_filtered::<(Entity, &Structure, &Team, &Transform, &Health), With<Structure>>();
            targets.extend(structures.iter(world).filter_map(
                |(entity, structure, structure_team, transform, health)| {
                    (*structure_team == team
                        && health.current > 0.0
                        && is_structure_elimination_anchor(structure))
                    .then_some((entity, transform.translation))
                },
            ));
        }
        {
            let world = app.world_mut();
            let mut units = world.query::<(Entity, &Unit, &Team, &Transform, &Health)>();
            targets.extend(units.iter(world).filter_map(
                |(entity, unit, unit_team, transform, health)| {
                    (*unit_team == team
                        && health.current > 0.0
                        && is_worker_elimination_anchor(unit))
                    .then_some((entity, transform.translation))
                },
            ));
        }
        targets
    }

    fn construct_target_at(app: &mut App, team: Team, point: Vec3) -> Option<Entity> {
        let world = app.world_mut();
        let mut selectable_q = world.query::<SelectableOrderTargetItem<'_>>();
        let mut best = None;
        let mut best_distance = f32::MAX;
        for (
            entity,
            transform,
            selectable,
            target_team,
            visibility,
            resource_node,
            supply_crate,
            health,
            _unit,
            structure,
            under_construction,
        ) in selectable_q.iter(world)
        {
            if !visibility.visible
                || *target_team != team
                || resource_node.is_some()
                || supply_crate.is_some()
                || health.is_none_or(|health| health.current <= 0.0)
                || structure.is_none()
                || under_construction.is_none()
            {
                continue;
            }
            let distance = xz_distance(transform.translation, point);
            if distance <= selectable.radius + 0.45 && distance < best_distance {
                best = Some(entity);
                best_distance = distance;
            }
        }
        best
    }

    fn select_only_entities(app: &mut App, entities: &[Entity]) {
        let selected = {
            let world = app.world_mut();
            let mut selected_q = world.query_filtered::<Entity, With<Selected>>();
            selected_q.iter(world).collect::<Vec<_>>()
        };
        for entity in selected {
            if let Ok(mut entity_mut) = app.world_mut().get_entity_mut(entity) {
                entity_mut.remove::<Selected>();
            }
        }
        for entity in entities {
            if let Ok(mut entity_mut) = app.world_mut().get_entity_mut(*entity) {
                entity_mut.insert(Selected);
            }
        }
    }

