    fn one_hit_damage_with_shields(passive_scale: Option<f32>, active_scale: Option<f32>) -> f32 {
        let mut app = combat_test_app();
        let target = spawn_test_unit(&mut app, "ShieldTrooper", Team::Human, Vec3::ZERO);
        if let Some(damage_scale) = passive_scale {
            app.world_mut()
                .entity_mut(target)
                .insert(PassiveSupportShield { damage_scale });
        }
        if let Some(damage_scale) = active_scale {
            app.world_mut().entity_mut(target).insert(SupportShield {
                remaining: 0.7,
                damage_scale,
            });
        }
        let before = current_health(&app, target);
        app.world_mut().spawn((
            Team::Demon,
            Transform::from_translation(Vec3::new(2.0, 0.0, 0.0)),
            Selectable { radius: 0.4 },
            MovementDomain::Terrain,
            Health::new(10.0),
            test_unit("Tank"),
            VisionRadius(8.0),
            Weapon::new(5.0, 4.0, 1.0, 0.0, 0.5, 1.0, false, true),
            AttackOrder { target },
        ));
        app.update();
        app.update();
        app.update();
        before - current_health(&app, target)
    }

