    fn assert_skirmish_preview_matches_map(app: &mut App, map: &SkirmishMapDef) {
        assert_eq!(
            count_skirmish_preview_markers(app, SkirmishMapPreviewMarkerKind::Spawn),
            map.spawn_points.len(),
            "preview should show every spawn point for {}",
            map.name
        );
        assert_eq!(
            count_skirmish_preview_markers(app, SkirmishMapPreviewMarkerKind::Ore),
            map.resources
                .iter()
                .filter(|resource| resource.kind == ResourceKind::Ore)
                .count(),
            "preview should show ore markers for {}",
            map.name
        );
        assert_eq!(
            count_skirmish_preview_markers(app, SkirmishMapPreviewMarkerKind::Crystal),
            map.resources
                .iter()
                .filter(|resource| resource.kind == ResourceKind::Crystal)
                .count(),
            "preview should show crystal markers for {}",
            map.name
        );
        assert_eq!(
            count_skirmish_preview_markers(app, SkirmishMapPreviewMarkerKind::NeutralTech),
            map.neutral_tech.len(),
            "preview should show neutral tech markers for {}",
            map.name
        );
        assert_eq!(
            count_skirmish_preview_markers(app, SkirmishMapPreviewMarkerKind::SupplyCrate),
            map.supply_crates.len(),
            "preview should show supply crate markers for {}",
            map.name
        );
    }

    fn assert_all_entities_with_marker<T: Component>(app: &mut App, label: &str) {
        let world = app.world_mut();
        let mut query = world.query_filtered::<(Entity, Option<&MatchScopedEntity>), With<T>>();
        let mut total = 0usize;
        let mut missing = Vec::new();
        for (entity, marker) in query.iter(world) {
            total += 1;
            if marker.is_none() {
                missing.push(entity);
            }
        }
        assert!(total > 0, "{label} should exist in runtime setup");
        assert!(
            missing.is_empty(),
            "{label} should all be match-scoped, missing marker on {missing:?}"
        );
    }

    fn match_scoped_debug(app: &mut App) -> Vec<String> {
        let world = app.world_mut();
        let mut query = world.query_filtered::<(
            Entity,
            Option<&Name>,
            Option<&MainCamera>,
            Option<&Unit>,
            Option<&Structure>,
            Option<&ResourceNode>,
            Option<&SupplyCrate>,
            Option<&StatsText>,
            Option<&MinimapRoot>,
            Option<&WorldAssetRoot>,
        ), With<MatchScopedEntity>>();
        query
            .iter(world)
            .map(
                |(
                    entity,
                    name,
                    camera,
                    unit,
                    structure,
                    resource,
                    supply,
                    stats,
                    minimap,
                    world_asset,
                )| {
                    let mut parts = Vec::new();
                    parts.push(format!("{entity:?}"));
                    if let Some(name) = name {
                        parts.push(format!("name={}", name.as_str()));
                    }
                    if camera.is_some() {
                        parts.push("MainCamera".to_string());
                    }
                    if let Some(unit) = unit {
                        parts.push(format!("Unit({})", unit.id));
                    }
                    if let Some(structure) = structure {
                        parts.push(format!("Structure({})", structure.id));
                    }
                    if resource.is_some() {
                        parts.push("ResourceNode".to_string());
                    }
                    if supply.is_some() {
                        parts.push("SupplyCrate".to_string());
                    }
                    if stats.is_some() {
                        parts.push("StatsText".to_string());
                    }
                    if minimap.is_some() {
                        parts.push("MinimapRoot".to_string());
                    }
                    if world_asset.is_some() {
                        parts.push("WorldAssetRoot".to_string());
                    }
                    parts.join(" ")
                },
            )
            .collect()
    }

