    fn ground_position_for_selection_cursor(app: &mut App) -> Vec3 {
        let cursor = {
            let world = app.world_mut();
            let mut window_q = world.query_filtered::<&Window, With<PrimaryWindow>>();
            window_q
                .single(world)
                .expect("selection click test should have one primary window")
                .cursor_position()
                .expect("selection click test cursor should be positioned")
        };
        let world = app.world_mut();
        let mut camera_q = world.query_filtered::<(&Camera, &GlobalTransform), With<MainCamera>>();
        let (camera, camera_transform) = camera_q
            .single(world)
            .expect("selection click test should have one main camera");
        let ray = camera
            .viewport_to_world(camera_transform, cursor)
            .expect("selection click cursor should project to a world ray");
        ray.plane_intersection_point(Vec3::ZERO, InfinitePlane3d::new(Vec3::Y))
            .expect("selection click ray should hit the ground plane")
    }

    fn click_selection_at_world(app: &mut App, position: Vec3, shift: bool) {
        let cursor = screen_position_for_world(app, position);
        set_selection_cursor(app, cursor);
        {
            let world = app.world_mut();
            let mut window_q = world.query_filtered::<&Window, With<PrimaryWindow>>();
            let window = window_q
                .single(world)
                .expect("selection click test should have one primary window");
            assert!(
                !cursor_is_over_hud(window),
                "selection click test cursor {cursor:?} should be outside HUD"
            );
        }
        let ground_position = ground_position_for_selection_cursor(app);
        assert!(
            xz_distance(ground_position, position) < 0.05,
            "selection click test cursor projected to {ground_position:?}, expected {position:?}"
        );
        {
            let mut keyboard = app.world_mut().resource_mut::<ButtonInput<KeyCode>>();
            if shift {
                keyboard.press(KeyCode::ShiftLeft);
            } else {
                keyboard.release(KeyCode::ShiftLeft);
            }
            keyboard.clear();
        }
        {
            let mut mouse = app.world_mut().resource_mut::<ButtonInput<MouseButton>>();
            mouse.press(MouseButton::Left);
        }
        app.update();
        {
            let mut mouse = app.world_mut().resource_mut::<ButtonInput<MouseButton>>();
            mouse.clear();
            mouse.release(MouseButton::Left);
        }
        app.update();
        {
            let mut mouse = app.world_mut().resource_mut::<ButtonInput<MouseButton>>();
            mouse.clear();
        }
        let mut keyboard = app.world_mut().resource_mut::<ButtonInput<KeyCode>>();
        keyboard.release(KeyCode::ShiftLeft);
        keyboard.clear();
    }

