    fn neutral_tech_counts(map: &SkirmishMapDef) -> BTreeMap<&'static str, usize> {
        let mut counts = BTreeMap::new();
        for tech in map.neutral_tech {
            *counts.entry(tech.id).or_insert(0) += 1;
        }
        counts
    }

