    fn assert_point_inside_map(map: &SkirmishMapDef, point: (f32, f32)) {
        assert!(
            point.0 >= 0.0 && point.1 >= 0.0 && point.0 <= map.size.0 && point.1 <= map.size.1,
            "{} point {:?} should be inside {:?}",
            map.id,
            point,
            map.size
        );
    }

