    fn runtime_structure_visibility(
        app: &mut App,
        team: Team,
        structure_id: &'static str,
    ) -> Option<(bool, Visibility)> {
        let world = app.world_mut();
        let mut query = world.query::<(&Structure, &Team, &VisibilityState, &Visibility)>();
        query.iter(world).find_map(
            |(structure, structure_team, visibility_state, visibility)| {
                (*structure_team == team && structure.id == structure_id)
                    .then_some((visibility_state.visible, *visibility))
            },
        )
    }

    fn runtime_neutral_tech_counts(app: &mut App) -> BTreeMap<&'static str, usize> {
        let world = app.world_mut();
        let mut query = world.query::<(&Structure, &Team)>();
        let mut counts = BTreeMap::new();
        for (structure, team) in query.iter(world) {
            if *team == Team::Neutral {
                *counts.entry(structure.id).or_insert(0) += 1;
            }
        }
        counts
    }

