        app.world_mut()
            .resource_mut::<Messages<MouseWheel>>()
            .write(MouseWheel {
                unit: MouseScrollUnit::Line,
                x: 0.0,
                y: -2.0,
                window,
                phase: bevy::input::touch::TouchPhase::Moved,
            });
        app.update();

        let world = app.world_mut();
        let mut scroll_q = world.query_filtered::<&ScrollPosition, With<MainMenuScrollArea>>();
        let scroll = scroll_q
            .single(world)
            .expect("skirmish setup should keep one scroll area");
