    #[test]
    fn skirmish_setup_keyboard_team_options_require_opposing_teams_like_godot() {
        let mut app = stateful_match_flow_test_app(MatchSetupSettings::default());
        app.update();

        press_key(&mut app, KeyCode::Digit9, 1);
        press_key(&mut app, KeyCode::KeyK, 0);
        press_key(&mut app, KeyCode::KeyK, 1);
        {
            let selection = *app.world().resource::<SkirmishMenuSelection>();
            assert_eq!(
                selection.team_id(Team::Demon),
                selection.team_id(Team::Human),
                "K should cycle the Demon slot onto the Human team id"
            );
            assert_eq!(
                selection.start_status(),
                SkirmishStartStatus::NoOpposingTeams
            );
            assert!(!selection.can_start());
        }

        press_key(&mut app, KeyCode::Enter, 1);
        assert_eq!(
            app_screen(&app),
            AppScreen::MainMenu,
            "same-team setup should not start"
        );

        press_key(&mut app, KeyCode::KeyK, 1);
        {
            let selection = *app.world().resource::<SkirmishMenuSelection>();
            assert!(selection.can_start());
            assert_eq!(selection.start_status(), SkirmishStartStatus::Ready);
        }

        press_key(&mut app, KeyCode::Enter, 2);
        assert_eq!(app_screen(&app), AppScreen::InMatch);
        let relations = app.world().resource::<TeamRelations>();
        assert!(relations.are_enemies(Team::Human, Team::Demon));
    }

