    #[test]
    fn cleanup_match_scoped_entities_removes_match_world_and_children() {
        let mut app = runtime_setup_test_app_with_map("res://source/match/maps/FourCorners.tscn");
        app.update();

        let scoped_before = count_entities_with::<MatchScopedEntity>(&mut app);
        let world_assets_before = count_entities_with::<WorldAssetRoot>(&mut app);
        assert!(scoped_before > 0, "match setup should create scoped roots");
        assert!(
            world_assets_before > 0,
            "match setup should create glTF child scene roots"
        );

        app.add_systems(Update, cleanup_match_scoped_entities);
        app.update();

        assert_eq!(count_entities_with::<MatchScopedEntity>(&mut app), 0);
        assert_eq!(count_entities_with::<MainCamera>(&mut app), 0);
        assert_eq!(count_entities_with::<Unit>(&mut app), 0);
        assert_eq!(count_entities_with::<Structure>(&mut app), 0);
        assert_eq!(count_entities_with::<ResourceNode>(&mut app), 0);
        assert_eq!(count_entities_with::<SupplyCrate>(&mut app), 0);
        assert_eq!(count_entities_with::<StatsText>(&mut app), 0);
        assert_eq!(count_entities_with::<ObjectiveTrackerText>(&mut app), 0);
        assert_eq!(count_entities_with::<MatchBriefingPanel>(&mut app), 0);
        assert_eq!(
            count_entities_with::<MatchBriefingReopenButton>(&mut app),
            0
        );
        assert_eq!(count_entities_with::<MinimapRoot>(&mut app), 0);
        assert_eq!(
            count_entities_with::<WorldAssetRoot>(&mut app),
            0,
            "cleanup should despawn child model scene roots too"
        );
    }

    #[test]
    fn match_briefing_opens_auto_hides_reopens_and_dismisses_like_godot() {
        fn single_visibility<T: Component>(app: &mut App) -> Visibility {
            let world = app.world_mut();
            let mut query = world.query_filtered::<&Visibility, With<T>>();
            *query
                .single(world)
                .expect("single visible entity should exist")
        }

        fn current_briefing_text(app: &mut App) -> String {
            let mut query = app
                .world_mut()
                .query_filtered::<&Text, With<MatchBriefingText>>();
            query
                .single(app.world())
                .expect("briefing text should exist")
                .0
                .clone()
        }

        let settings = MatchSetupSettings::default()
            .with_starting_resources(StartingResources::new(16, 8))
            .with_visible_player(VisiblePlayer::per_player(Team::Human));
        let mut app = stateful_match_flow_test_app(settings);

        set_app_screen(&mut app, AppScreen::InMatch);
        app.update();

        assert_eq!(
            app.world()
                .resource::<MatchBriefingState>()
                .auto_hide_seconds,
            MATCH_BRIEFING_AUTO_HIDE_SECONDS
        );
        assert!(app.world().resource::<MatchBriefingState>().visible);
        assert_eq!(
            single_visibility::<MatchBriefingPanel>(&mut app),
            Visibility::Visible
        );
        assert_eq!(
            single_visibility::<MatchBriefingReopenButton>(&mut app),
            Visibility::Hidden
        );

        let text = current_briefing_text(&mut app);
        assert!(
            text.contains("目标：摧毁所有敌方指挥中心")
                && text.contains("敌人: 1")
                && text.contains("盟友: 0")
                && text.contains("Ore: 16 / Crystal: 8")
                && text.contains("推荐开局")
                && text.contains("派工人采集附近水晶")
                && text.contains("占领中立建筑"),
            "briefing should mirror Godot match start details: {text}"
        );

        {
            let mut briefing = app.world_mut().resource_mut::<MatchBriefingState>();
            briefing.auto_hide_seconds = 0.1;
        }
        app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(
            Duration::from_secs_f32(0.2),
        ));
        app.update();

        assert!(!app.world().resource::<MatchBriefingState>().visible);
        assert_eq!(
            single_visibility::<MatchBriefingPanel>(&mut app),
            Visibility::Hidden
        );
        assert_eq!(
            single_visibility::<MatchBriefingReopenButton>(&mut app),
            Visibility::Visible
        );

        app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(
            Duration::ZERO,
        ));
        {
            let mut briefing = app.world_mut().resource_mut::<MatchBriefingState>();
            briefing.auto_hide_seconds = MATCH_BRIEFING_AUTO_HIDE_SECONDS;
        }
        press_match_briefing_button(&mut app, MatchBriefingAction::Show, 1);

        assert!(app.world().resource::<MatchBriefingState>().visible);
        assert_eq!(
            single_visibility::<MatchBriefingPanel>(&mut app),
            Visibility::Visible
        );
        assert_eq!(
            single_visibility::<MatchBriefingReopenButton>(&mut app),
            Visibility::Hidden
        );

        press_match_briefing_button(&mut app, MatchBriefingAction::Dismiss, 1);

        assert!(!app.world().resource::<MatchBriefingState>().visible);
        assert_eq!(
            single_visibility::<MatchBriefingPanel>(&mut app),
            Visibility::Hidden
        );
        assert_eq!(
            single_visibility::<MatchBriefingReopenButton>(&mut app),
            Visibility::Visible
        );
    }

