    #[test]
    fn match_menu_speed_buttons_scale_virtual_time_and_reset_like_godot() {
        let settings = MatchSetupSettings::default()
            .with_map("res://source/match/maps/TechDivide.tscn")
            .with_visible_player(VisiblePlayer::per_player(Team::Human));
        let mut app = stateful_match_flow_test_app(settings);

        set_app_screen(&mut app, AppScreen::InMatch);
        open_match_menu(&mut app);
        for preset in MatchSpeedPreset::ALL {
            assert!(
                match_menu_button_exists(&mut app, MatchMenuAction::SetSpeed(preset)),
                "match menu should expose the Godot speed preset {}",
                preset.label()
            );
        }
        press_match_menu_button(
            &mut app,
            MatchMenuAction::SetSpeed(MatchSpeedPreset::Max),
            1,
        );

        assert_eq!(
            app.world().resource::<MatchSpeed>().preset,
            MatchSpeedPreset::Max
        );
        assert_eq!(
            app.world().resource::<Time<Virtual>>().relative_speed(),
            MatchSpeedPreset::Max.scale()
        );
        assert!(
            app.world().resource::<MatchMenuState>().visible,
            "changing game speed should keep the pause menu open like Godot's option selector"
        );
        let status_text = {
            let world = app.world_mut();
            let mut status_q = world.query_filtered::<&Text, With<MatchMenuStatusText>>();
            status_q
                .single(world)
                .expect("match menu should have one status text")
                .to_string()
        };
        assert!(
            status_text.contains("速度: 2x"),
            "match menu status should show the selected Godot speed label: {status_text}"
        );

        press_match_menu_button(&mut app, MatchMenuAction::Resume, 1);
        assert!(
            !app.world().resource::<MatchMenuState>().visible,
            "resuming should close the match menu before scaled simulation advances"
        );
        app.world_mut().resource_mut::<MatchState>().start_time_sec = 0.0;
        app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(
            Duration::from_secs_f32(0.1),
        ));
        app.update();
        assert!(
            (app.world().resource::<MatchState>().start_time_sec - 0.2).abs() < 0.01,
            "Bevy virtual time speed should scale match simulation time like Godot Engine.time_scale"
        );

        open_match_menu(&mut app);
        press_match_menu_button(&mut app, MatchMenuAction::ReturnToSetup, 2);
        assert_eq!(app_screen(&app), AppScreen::MainMenu);
        assert_eq!(
            app.world().resource::<MatchSpeed>().preset,
            MatchSpeedPreset::Normal
        );
        assert_eq!(
            app.world().resource::<Time<Virtual>>().relative_speed(),
            MatchSpeedPreset::Normal.scale(),
            "returning to setup should reset match speed like Godot MatchFlow"
        );
    }

    #[test]
    fn match_menu_restart_button_restarts_current_match_after_cleanup_with_same_setup() {
        let settings = MatchSetupSettings::default()
            .with_map("res://source/match/maps/FourCorners.tscn")
            .with_starting_resources(StartingResources::new(16, 8))
            .with_visible_player(VisiblePlayer::per_player(Team::Demon));
        let mut app = stateful_match_flow_test_app(settings);

        set_app_screen(&mut app, AppScreen::InMatch);
        assert_eq!(app_screen(&app), AppScreen::InMatch);
        let unit_count_before = count_entities_with::<Unit>(&mut app);
        let structure_count_before = count_entities_with::<Structure>(&mut app);
        let first_next_spawn_id = app.world().resource::<NextSpawnId>().0;
        assert!(unit_count_before > 0);
        assert!(structure_count_before > 0);

        open_match_menu(&mut app);
        press_match_menu_button(&mut app, MatchMenuAction::Restart, 4);

        assert_eq!(app_screen(&app), AppScreen::InMatch);
        assert!(
            !app.world().resource::<MatchMenuState>().visible,
            "restart should close the match menu"
        );
        assert_eq!(count_entities_with::<Unit>(&mut app), unit_count_before);
        assert_eq!(
            count_entities_with::<Structure>(&mut app),
            structure_count_before
        );
        assert!(count_entities_with::<MatchScopedEntity>(&mut app) > 0);
        assert!(count_entities_with::<WorldAssetRoot>(&mut app) > 0);
        assert!(
            app.world().resource::<NextSpawnId>().0 > first_next_spawn_id,
            "restart should tear down the old world and spawn a fresh match"
        );
        assert_eq!(
            app.world().resource::<SelectedSkirmishMap>().godot_path,
            settings.map_path
        );
        assert_eq!(
            *app.world().resource::<VisiblePlayer>(),
            settings.visible_player
        );
        let visible_economy = app
            .world()
            .resource::<Economies>()
            .get(settings.visible_player.team);
        assert_eq!(visible_economy.ore, settings.starting_resources.ore);
        assert_eq!(visible_economy.crystal, settings.starting_resources.crystal);
    }

