        assert!(count_entities_with::<MatchEndButton>(&mut app) >= 3);
        assert!(count_entities_with::<MatchScopedEntity>(&mut app) > 0);

        finish_match_for_flow_tests(&mut app, MatchPhase::HumanVictory);
