    #[test]
    fn runtime_setup_starts_human_units_idle_and_unselected_like_godot() {
        let settings = SkirmishMenuSelection::default()
            .match_setup()
            .with_startup_loadout(StartupLoadoutMode::GodotSkirmish);
        let mut app = runtime_setup_test_app_with_settings(settings);

        app.update();

        let world = app.world_mut();
        let mut units = world.query::<(
            Entity,
            &Unit,
            &Team,
            Option<&Selected>,
            Option<&MoveOrder>,
            Option<&FollowOrder>,
            Option<&AttackMoveOrder>,
            Option<&PatrolOrder>,
            Option<&OrderQueue>,
        )>();
        let mut human_unit_count = 0usize;
        for (
            entity,
            unit,
            team,
            selected,
            move_order,
            follow_order,
            attack_move_order,
            patrol_order,
            order_queue,
        ) in units.iter(world)
        {
            if *team != Team::Human {
                continue;
            }
            human_unit_count += 1;
            assert!(
                selected.is_none(),
                "Godot match start should not auto-select controlled unit {entity:?} ({})",
                unit.id
            );
            assert!(
                move_order.is_none()
                    && follow_order.is_none()
                    && attack_move_order.is_none()
                    && patrol_order.is_none()
                    && order_queue.is_none(),
                "Godot match start should not auto-issue manual movement orders to {entity:?} ({})",
                unit.id
            );
        }

        assert!(
            human_unit_count > 0,
            "Godot match start should spawn human starting units"
        );
    }

    #[test]
    fn runtime_setup_spawns_godot_style_orthographic_main_camera() {
        let mut app = runtime_setup_test_app();
        app.insert_resource(MatchFlow { active: false });

        app.update();

        let world = app.world_mut();
        let mut camera_q = world.query_filtered::<&Projection, With<MainCamera>>();
        let projection = camera_q
            .single(world)
            .expect("runtime setup should spawn one main camera projection");
        let Projection::Orthographic(projection) = projection else {
            panic!("main match camera should be orthographic like Godot");
        };
        let ScalingMode::FixedVertical { viewport_height } = projection.scaling_mode else {
            panic!("main match camera should use fixed vertical world-height zoom");
        };
        assert_eq!(viewport_height, CAMERA_DEFAULT_DISTANCE);
    }

