    #[test]
    fn runtime_setup_uses_selected_player_faction_for_identity_markers() {
        let mut settings = MatchSetupSettings::default()
            .with_visible_player(VisiblePlayer::per_player(Team::Human));
        settings.active_teams = [true, false, false];
        settings.player_factions = [
            SkirmishFaction::Chaos,
            SkirmishFaction::Demon,
            SkirmishFaction::Alliance,
        ];
        let mut app = runtime_setup_test_app_with_settings(settings);

        app.update();
        app.update();

        let visual_count = {
            let world = app.world_mut();
            let mut visual_q =
                world.query::<(&Team, &VisualFaction, Option<&Unit>, Option<&Structure>)>();
            let mut visual_count = 0usize;
            for (team, visual_faction, unit, structure) in visual_q.iter(world) {
                if *team != Team::Human || (unit.is_none() && structure.is_none()) {
                    continue;
                }
                visual_count += 1;
                assert_eq!(
                    visual_faction.0,
                    SkirmishFaction::Chaos,
                    "Human player slot entities should carry the selected Chaos visual faction"
                );
            }
            visual_count
        };
        assert!(
            visual_count > 0,
            "selected Human slot should spawn playable entities with a visual faction"
        );
        assert!(runtime_name_count_containing(&mut app, "Chaos Faction") > 0);
        assert_eq!(runtime_name_count_containing(&mut app, "Human Faction"), 0);
        assert_eq!(runtime_name_count_containing(&mut app, "Demon Faction"), 0);
    }

