    #[test]
    fn runtime_setup_can_use_godot_skirmish_starting_loadout() {
        let map = skirmish_map_by_path("res://source/match/maps/PlainAndSimple.tscn")
            .expect("Plain & Simple should be registered");
        let mut settings =
            MatchSetupSettings::default().with_startup_loadout(StartupLoadoutMode::GodotSkirmish);
        settings.active_teams = [true; 3];
        let mut app = runtime_setup_test_app_with_settings(settings);

        app.update();

        for team in Team::all() {
            assert_eq!(
                runtime_structure_counts_by_team(&mut app, team),
                BTreeMap::from([("CommandCenter", 1)]),
                "{team:?} should use the Godot match CommandCenter-only structure loadout"
            );
            assert_eq!(
                runtime_unit_counts_by_team(&mut app, team),
                BTreeMap::from([("Drone", 1), ("Worker", 2)]),
                "{team:?} should use the Godot match Drone + two Worker unit loadout"
            );
        }

        let human_base = map_local_to_world(map, map.spawn_points[0]);
        let drone_positions = runtime_unit_positions(&mut app, Team::Human, "Drone");
        assert_eq!(drone_positions.len(), 1);
        assert!(
            xz_distance(drone_positions[0], human_base + Vec3::new(-2.0, 0.0, -2.0)) < 0.01,
            "Godot spawns the Drone at (-2, -2) from the spawn transform"
        );
        let worker_positions = runtime_unit_positions(&mut app, Team::Human, "Worker");
        assert_eq!(worker_positions.len(), 2);
        for expected in [
            human_base + Vec3::new(-3.0, 0.0, 3.0),
            human_base + Vec3::new(3.0, 0.0, 3.0),
        ] {
            assert!(
                worker_positions
                    .iter()
                    .any(|position| xz_distance(*position, expected) < 0.01),
                "Godot worker offset {expected:?} should be present"
            );
        }
    }

