    #[test]
    fn runtime_visible_player_switch_updates_visibility_like_godot() {
        let mut app = visible_player_visibility_test_app(VisiblePlayer::per_player(Team::Demon));
        let human = spawn_visibility_probe(&mut app, Team::Human, Vec3::new(-12.0, 0.0, 0.0), true);
        let demon = spawn_visibility_probe(&mut app, Team::Demon, Vec3::ZERO, false);
        let nearby_enemy =
            spawn_visibility_probe(&mut app, Team::Chaos, Vec3::new(3.0, 0.0, 0.0), false);
        let far_enemy =
            spawn_visibility_probe(&mut app, Team::Chaos, Vec3::new(12.0, 0.0, 0.0), false);
        app.world_mut().entity_mut(human).insert(Selected);

        app.update();
        app.update();

        assert_eq!(entity_visibility(&app, human), (false, Visibility::Hidden));
        assert!(
            app.world().entity(human).get::<Selected>().is_none(),
            "units from the previous visible player should be deselected when hidden"
        );
        assert_eq!(entity_visibility(&app, demon), (true, Visibility::Visible));
        assert_eq!(
            entity_visibility(&app, nearby_enemy),
            (true, Visibility::Visible),
            "current visible player's revealers should expose nearby enemies"
        );
        assert_eq!(
            entity_visibility(&app, far_enemy),
            (false, Visibility::Hidden)
        );
    }

    #[test]
    fn seen_enemy_structures_leave_noninteractive_fog_memory_like_godot() {
        let mut app = visible_player_visibility_test_app(VisiblePlayer::per_player(Team::Demon));
        let _revealer = spawn_visibility_probe(&mut app, Team::Demon, Vec3::ZERO, true);
        let enemy_structure = spawn_visibility_structure_probe(
            &mut app,
            Team::Chaos,
            Vec3::new(6.5, 0.0, 0.0),
            false,
        );
        let enemy_mobile =
            spawn_visibility_probe(&mut app, Team::Chaos, Vec3::new(6.5, 0.0, 1.0), false);

        app.update();

        assert_eq!(
            entity_visibility(&app, enemy_structure),
            (true, Visibility::Visible),
            "enemy structure should become normally visible inside sight plus Godot fog compensation"
        );
        assert_eq!(
            entity_visibility(&app, enemy_mobile),
            (true, Visibility::Visible)
        );
        app.world_mut().entity_mut(enemy_structure).insert(Selected);
        app.world_mut()
            .entity_mut(enemy_structure)
            .get_mut::<Transform>()
            .expect("structure probe should have a transform")
            .translation = Vec3::new(8.0, 0.0, 0.0);
        app.world_mut()
            .entity_mut(enemy_mobile)
            .get_mut::<Transform>()
            .expect("mobile probe should have a transform")
            .translation = Vec3::new(8.0, 0.0, 1.0);

        app.update();

        assert_eq!(
            entity_visibility(&app, enemy_structure),
            (false, Visibility::Visible),
            "Godot leaves seen enemy structures rendered as fog memory after they leave sight"
        );
        assert!(
            app.world()
                .entity(enemy_structure)
                .get::<FogMemoryVisible>()
                .is_some(),
            "structure should be marked as a remembered fog object"
        );
        assert!(
            app.world()
                .entity(enemy_structure)
                .get::<Selected>()
                .is_none(),
            "remembered fog structures should not remain interactively selected"
        );
        assert_eq!(
            entity_visibility(&app, enemy_mobile),
            (false, Visibility::Hidden),
            "Godot only leaves structure dummies; mobile units disappear from fog"
        );

        app.world_mut()
            .entity_mut(enemy_structure)
            .get_mut::<Transform>()
            .expect("structure probe should have a transform")
            .translation = Vec3::new(6.0, 0.0, 0.0);
        app.update();

        assert_eq!(
            entity_visibility(&app, enemy_structure),
            (true, Visibility::Visible),
            "remembered structure should become a normal visible structure when scouted again"
        );
        assert!(
            app.world()
                .entity(enemy_structure)
                .get::<FogMemoryVisible>()
                .is_none(),
            "fog memory marker should clear once the real structure is visible again"
        );
    }

