    #[test]
    fn visible_player_hud_uses_current_team_resources_and_cooldowns_like_godot() {
        let mut app = visible_player_hud_test_app(VisiblePlayer::per_player(Team::Demon));
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            economies.human.ore = 3;
            economies.human.crystal = 2;
            economies.human.power_used = 10;
            economies.human.power_capacity = 0;
            economies.demon.ore = 44;
            economies.demon.crystal = 11;
            economies.demon.power_used = 2;
            economies.demon.power_capacity = 8;
            economies.chaos.power_used = 9;
            economies.chaos.power_capacity = 0;
        }
        {
            let mut support_cooldowns = app.world_mut().resource_mut::<SupportCooldowns>();
            support_cooldowns.set(Team::Human, SupportPowerKind::RadarSweep, 3.0);
            support_cooldowns.set(Team::Demon, SupportPowerKind::RadarSweep, 12.0);
        }
        app.world_mut().spawn((Text::new(""), StatsText));
        app.world_mut().spawn((Text::new(""), SelectionText));
        app.world_mut().spawn((Text::new(""), ProductionQueueText));

        app.update();

        let mut query = app.world_mut().query_filtered::<&Text, With<StatsText>>();
        let text = query
            .single(app.world())
            .expect("stats text should be rendered")
            .0
            .clone();
        assert!(
            text.contains("魔族  Ore 44  Crystal 11"),
            "stats bar should follow the runtime visible player: {text}"
        );
        assert!(
            text.contains("雷达扫描 12"),
            "support cooldowns should use the visible player's cooldowns: {text}"
        );
        assert!(
            text.contains("AI 人:Normal AI 混:Normal AI") && !text.contains("AI 魔:"),
            "AI labels should exclude the selected player faction: {text}"
        );
        assert!(
            text.contains("人 LOW") && text.contains("混 LOW") && !text.contains("魔 LOW"),
            "AI low-power labels should exclude the selected player faction: {text}"
        );
        assert!(
            !text.contains("Ore 3  Crystal 2") && !text.contains("雷达扫描 3"),
            "stats bar should not keep showing the previous human perspective: {text}"
        );
    }

