    #[test]
    fn objective_tracker_hud_counts_enemy_anchors_and_progress_like_godot() {
        fn current_objective_text(app: &mut App) -> String {
            let mut query = app
                .world_mut()
                .query_filtered::<&Text, With<ObjectiveTrackerText>>();
            query
                .single(app.world())
                .expect("objective tracker text should be rendered")
                .0
                .clone()
        }

        let mut app = visible_player_hud_test_app(VisiblePlayer::per_player(Team::Human));
        app.world_mut().spawn((Text::new(""), StatsText));
        app.world_mut().spawn((Text::new(""), SelectionText));
        app.world_mut().spawn((Text::new(""), ObjectiveTrackerText));
        app.world_mut().spawn((Text::new(""), ProductionQueueText));

        spawn_test_structure(&mut app, "CommandCenter", Team::Human, Vec3::ZERO);
        let enemy_structure = spawn_test_structure(
            &mut app,
            "CommandCenter",
            Team::Demon,
            Vec3::new(4.0, 0.0, 0.0),
        );
        let enemy_worker =
            spawn_test_unit(&mut app, "Worker", Team::Demon, Vec3::new(5.0, 0.0, 0.0));

        app.update();

        let text = current_objective_text(&mut app);
        assert!(
            text.contains("目标: 消灭敌方锚点")
                && text.contains("敌方队伍: 1")
                && text.contains("锚点: 2/2")
                && text.contains("结构: 1")
                && text.contains("工人: 1")
                && text.contains("进度: 0%"),
            "objective tracker should summarize active enemy anchors: {text}"
        );

        set_health_ratio(&mut app, enemy_worker, 0.0);
        app.update();

        let text = current_objective_text(&mut app);
        assert!(
            text.contains("锚点: 1/2") && text.contains("结构: 1") && text.contains("工人: 0"),
            "objective tracker should keep the maximum anchors seen as total: {text}"
        );
        assert!(
            text.contains("进度: 50%"),
            "objective tracker should show half progress after one of two anchors is gone: {text}"
        );

        set_health_ratio(&mut app, enemy_structure, 0.0);
        app.update();

        let text = current_objective_text(&mut app);
        assert!(
            text.contains("目标完成") && text.contains("锚点: 0/2") && text.contains("进度: 100%"),
            "objective tracker should complete when all enemy anchors are gone: {text}"
        );
    }

