    #[test]
    fn unit_group_hotkeys_select_then_focus_and_clear_like_godot() {
        let mut app = selection_hotkey_test_app(VisiblePlayer::per_player(Team::Demon));
        let tank = spawn_group_hotkey_unit(
            &mut app,
            "Tank",
            Team::Demon,
            Vec3::new(2.0, 0.0, -1.0),
            true,
        );
        let worker = spawn_group_hotkey_unit(
            &mut app,
            "Worker",
            Team::Demon,
            Vec3::new(4.0, 0.0, 1.0),
            true,
        );
        let human = spawn_group_hotkey_unit(&mut app, "Tank", Team::Human, Vec3::ZERO, true);

        press_selection_keys(&mut app, &[KeyCode::ControlLeft, KeyCode::Digit1]);

        {
            let groups = app.world().resource::<UnitGroups>();
            assert_eq!(groups.slots[0], vec![tank, worker]);
            assert_eq!(groups.last_accessed, None);
        }
        {
            let battle_log = app.world().resource::<BattleLog>();
            assert_eq!(battle_log.entries.len(), 1);
            assert_eq!(battle_log.entries[0].message, "编组 1 已设置: 2 个单位");
        }
        for entity in [tank, worker, human] {
            app.world_mut().entity_mut(entity).remove::<Selected>();
        }
        app.world_mut().resource_mut::<RtsCamera>().focus = Vec3::new(6.0, 0.0, 6.0);
        let away_focus = app.world().resource::<RtsCamera>().focus;
        let group_focus = Vec3::new(3.0, 0.0, 0.0);

        press_selection_keys(&mut app, &[KeyCode::Digit1]);

        assert!(app.world().entity(tank).get::<Selected>().is_some());
        assert!(app.world().entity(worker).get::<Selected>().is_some());
        assert!(app.world().entity(human).get::<Selected>().is_none());
        assert!(
            xz_distance(app.world().resource::<RtsCamera>().focus, away_focus) < 0.01,
            "first Godot group access selects without moving the camera"
        );

        press_selection_keys(&mut app, &[KeyCode::Digit1]);

        assert!(
            xz_distance(app.world().resource::<RtsCamera>().focus, group_focus) < 0.01,
            "second Godot group access focuses the selected group's pivot"
        );

        app.world_mut().entity_mut(tank).remove::<Selected>();
        app.world_mut().entity_mut(worker).remove::<Selected>();
        press_selection_keys(&mut app, &[KeyCode::ControlLeft, KeyCode::Digit1]);

        assert!(app.world().resource::<UnitGroups>().slots[0].is_empty());
        assert!(app.world().entity(tank).get::<Selected>().is_none());
        assert!(app.world().entity(worker).get::<Selected>().is_none());
        let messages = app
            .world()
            .resource::<BattleLog>()
            .entries
            .iter()
            .map(|entry| entry.message.as_str())
            .collect::<Vec<_>>();
        assert_eq!(messages, vec!["编组 1 已设置: 2 个单位", "编组 1 已清空"]);
    }

