    #[test]
    fn camera_bookmark_hotkeys_restore_view_without_accessing_unit_groups_like_godot() {
        let mut app = selection_hotkey_test_app(VisiblePlayer::per_player(Team::Human));
        let tank = spawn_group_hotkey_unit(&mut app, "Tank", Team::Human, Vec3::ZERO, true);

        {
            let mut camera = app.world_mut().resource_mut::<RtsCamera>();
            camera.focus = Vec3::new(12.0, 0.0, 12.0);
            camera.distance = 17.5;
            camera.yaw = -0.4;
            camera.pitch = -0.9;
        }
        press_selection_keys(
            &mut app,
            &[KeyCode::ControlLeft, KeyCode::AltLeft, KeyCode::Digit1],
        );

        assert!(app.world().resource::<CameraBookmarks>().slots[0].is_some());
        assert!(
            app.world().resource::<UnitGroups>().slots[0].is_empty(),
            "Ctrl+Alt+1 should store a camera bookmark, not a control group"
        );

        {
            let mut camera = app.world_mut().resource_mut::<RtsCamera>();
            camera.focus = Vec3::new(42.0, 0.0, 42.0);
            camera.distance = 24.0;
            camera.yaw = 0.8;
            camera.pitch = -0.5;
        }
        app.world_mut().entity_mut(tank).remove::<Selected>();
        app.world_mut().resource_mut::<UnitGroups>().slots[0] = vec![tank];

        press_selection_keys(&mut app, &[KeyCode::AltLeft, KeyCode::Digit1]);

        let camera = app.world().resource::<RtsCamera>();
        assert!(
            xz_distance(camera.focus, Vec3::new(12.0, 0.0, 12.0)) < 0.01,
            "Alt+1 should restore the stored camera focus"
        );
        assert!(
            (camera.distance - CAMERA_MAX_DISTANCE).abs() < 0.001,
            "Alt+1 should restore through Godot-style safe zoom limits"
        );
        assert!((camera.yaw - -0.4).abs() < 0.001);
        assert!((camera.pitch - -0.9).abs() < 0.001);
        assert!(
            app.world().entity(tank).get::<Selected>().is_none(),
            "Alt+1 should not access control group 1"
        );

        {
            let mut camera = app.world_mut().resource_mut::<RtsCamera>();
            camera.focus = Vec3::new(-8.0, 0.0, -8.0);
            camera.distance = 18.0;
        }
        press_selection_keys(&mut app, &[KeyCode::AltLeft, KeyCode::Digit2]);
        let camera = app.world().resource::<RtsCamera>();
        assert!(
            xz_distance(camera.focus, Vec3::new(-8.0, 0.0, -8.0)) < 0.01,
            "Alt+2 with an empty bookmark should leave the camera in place"
        );
        assert!((camera.distance - 18.0).abs() < 0.001);

        press_selection_keys(&mut app, &[KeyCode::Digit1]);

        assert!(
            app.world().entity(tank).get::<Selected>().is_some(),
            "plain 1 should still access control group 1"
        );
    }

    #[test]
    fn production_structure_hotkeys_cycle_select_all_and_focus_visible_like_godot() {
        let mut app = selection_hotkey_test_app(VisiblePlayer::per_player(Team::Human));
        let first_position = Vec3::new(-8.0, 0.0, 4.0);
        let hidden_position = Vec3::new(-2.0, 0.0, 0.0);
        let second_position = Vec3::new(12.0, 0.0, -6.0);
        let first = spawn_group_hotkey_structure(
            &mut app,
            "Barracks",
            Team::Human,
            first_position,
            true,
            false,
        );
        let hidden = spawn_group_hotkey_structure(
            &mut app,
            "Barracks",
            Team::Human,
            hidden_position,
            false,
            false,
        );
        let second = spawn_group_hotkey_structure(
            &mut app,
            "Barracks",
            Team::Human,
            second_position,
            true,
            false,
        );
        let enemy = spawn_group_hotkey_structure(
            &mut app,
            "Barracks",
            Team::Demon,
            Vec3::new(2.0, 0.0, 2.0),
            true,
            false,
        );

        app.world_mut().resource_mut::<RtsCamera>().focus = Vec3::new(30.0, 0.0, 30.0);

        press_selection_keys(&mut app, &[KeyCode::AltLeft, KeyCode::KeyB]);

        assert!(app.world().entity(first).get::<Selected>().is_some());
        assert!(app.world().entity(hidden).get::<Selected>().is_none());
        assert!(app.world().entity(second).get::<Selected>().is_none());
        assert!(app.world().entity(enemy).get::<Selected>().is_none());
        assert!(
            xz_distance(app.world().resource::<RtsCamera>().focus, first_position) < 0.01,
            "first press should focus the first visible constructed Barracks"
        );

        press_selection_keys(&mut app, &[KeyCode::AltLeft, KeyCode::KeyB]);

        assert!(app.world().entity(first).get::<Selected>().is_none());
        assert!(app.world().entity(second).get::<Selected>().is_some());
        assert!(app.world().entity(hidden).get::<Selected>().is_none());
        assert!(
            xz_distance(app.world().resource::<RtsCamera>().focus, second_position) < 0.01,
            "second press should cycle to the next visible Barracks"
        );

        press_selection_keys(
            &mut app,
            &[KeyCode::ShiftLeft, KeyCode::AltLeft, KeyCode::KeyB],
        );

        assert!(app.world().entity(first).get::<Selected>().is_some());
        assert!(app.world().entity(second).get::<Selected>().is_some());
        assert!(app.world().entity(hidden).get::<Selected>().is_none());
        assert!(app.world().entity(enemy).get::<Selected>().is_none());
        assert!(
            xz_distance(app.world().resource::<RtsCamera>().focus, first_position) < 0.01,
            "Godot focuses the first visible structure when Shift selects all producers"
        );
    }

