    #[test]
    fn drone_mine_layer_deploys_source_tracked_land_mine_like_godot() {
        let mut app = mine_test_app();
        let layer = spawn_test_unit(&mut app, "DroneMineLayer", Team::Human, Vec3::ZERO);
        insert_registry_mine_layer(&mut app, layer);

        run_mine_frames(&mut app, 1);

        let mines = mine_snapshots(&mut app);
        assert_eq!(mines.len(), 1, "mine layer should deploy one active mine");
        let (_mine_entity, mine_team, mine, mine_position) = mines[0];
        let layer_def = registry::entity("DroneMineLayer").expect("mine layer definition");
        let mine_def = registry::entity("LandMine").expect("land mine definition");
        assert_eq!(mine_team, Team::Human);
        assert_eq!(mine.source, Some(layer));
        assert_eq!(mine.damage, layer_def.mine_damage);
        assert_eq!(mine.trigger_radius, mine_def.mine_trigger_radius);
        assert_eq!(mine.blast_radius, mine_def.mine_blast_radius);
        assert!(
            (xz_distance(mine_position, Vec3::ZERO) - layer_def.mine_deploy_radius).abs() < 0.05,
            "mine should be deployed on the layer radius"
        );
    }

    #[test]
    fn drone_mine_layer_respects_active_mine_limit_and_replaces_spent_mines_like_godot() {
        let mut app = mine_test_app();
        let layer = spawn_test_unit(&mut app, "DroneMineLayer", Team::Human, Vec3::ZERO);
        insert_registry_mine_layer(&mut app, layer);
        let layer_def = registry::entity("DroneMineLayer").expect("mine layer definition");

        for _ in 0..120 {
            if mine_snapshots(&mut app).len() == layer_def.mine_limit {
                break;
            }
            run_mine_frames(&mut app, 1);
        }

        let mines_at_limit = mine_snapshots(&mut app);
        assert_eq!(
            mines_at_limit.len(),
            layer_def.mine_limit,
            "Godot DroneMineLayer should stop once its active source mines reach mine_limit"
        );
        assert!(
            mines_at_limit
                .iter()
                .all(|(_, team, mine, _)| *team == Team::Human && mine.source == Some(layer)),
            "active mine limit should count mines owned by this source layer"
        );

        run_mine_frames(&mut app, 30);
        assert_eq!(
            mine_snapshots(&mut app).len(),
            layer_def.mine_limit,
            "mine layer should not deploy beyond the active mine limit"
        );

        let spent_mine = mines_at_limit[0].0;
        app.world_mut().entity_mut(spent_mine).despawn();
        for _ in 0..120 {
            if mine_snapshots(&mut app).len() == layer_def.mine_limit {
                break;
            }
            run_mine_frames(&mut app, 1);
        }

        let replenished_mines = mine_snapshots(&mut app);
        assert_eq!(
            replenished_mines.len(),
            layer_def.mine_limit,
            "Godot DroneMineLayer should resume deployment after one source mine is spent"
        );
        assert!(
            replenished_mines
                .iter()
                .all(|(_, team, mine, _)| *team == Team::Human && mine.source == Some(layer)),
            "replacement mine should keep the same source tracking as Godot"
        );
    }

    #[test]
    fn land_mines_ignore_air_and_damage_enemy_ground_like_godot() {
        let mut app = mine_test_app();
        let layer = spawn_test_unit(&mut app, "DroneMineLayer", Team::Human, Vec3::ZERO);
        insert_registry_mine_layer(&mut app, layer);
        run_mine_frames(&mut app, 2);

        let mines = mine_snapshots(&mut app);
        assert_eq!(mines.len(), 1);
        let (mine_entity, _mine_team, mine, mine_position) = mines[0];
        assert!(
            mine.arming_remaining <= 0.0,
            "test mine should be armed before targets arrive"
        );

        let air_target = spawn_test_unit(&mut app, "Drone", Team::Demon, mine_position);
        let air_health = current_health(&app, air_target);
        run_mine_frames(&mut app, 1);
        assert_eq!(
            current_health(&app, air_target),
            air_health,
            "air units should not trigger or take land mine damage"
        );
        assert!(
            app.world().get_entity(mine_entity).is_ok(),
            "mine should remain after an air unit crosses it"
        );

        let ground_target = spawn_test_unit(&mut app, "Tank", Team::Demon, mine_position);
        let ground_health = current_health(&app, ground_target);
        run_mine_frames(&mut app, 1);

        let mine_damage = registry::entity("LandMine")
            .expect("land mine definition")
            .mine_damage;
        assert_eq!(
            current_health(&app, ground_target),
            ground_health - mine_damage,
            "enemy ground unit should take land mine blast damage"
        );
        assert!(
            app.world().get_entity(mine_entity).is_err(),
            "mine should be consumed after detonating"
        );
    }

