    #[test]
    fn mobile_shield_projector_refreshes_nearby_friendly_units_like_godot() {
        let mut app = support_effect_test_app();
        app.world_mut()
            .resource_mut::<TeamRelations>()
            .set_allied(Team::Human, Team::Demon, true);
        let projector = spawn_test_unit(&mut app, "MobileShieldProjector", Team::Human, Vec3::ZERO);
        insert_registry_mobile_shield_projector(&mut app, projector);
        let friendly_inside =
            spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::new(3.6, 0.0, 0.0));
        let allied_inside =
            spawn_test_unit(&mut app, "Tank", Team::Demon, Vec3::new(2.8, 0.0, 0.0));
        let allied_structure_inside = spawn_test_structure(
            &mut app,
            "CommandCenter",
            Team::Demon,
            Vec3::new(1.8, 0.0, 0.0),
        );
        let friendly_outside =
            spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::new(6.0, 0.0, 0.0));
        let enemy_inside = spawn_test_unit(&mut app, "Tank", Team::Chaos, Vec3::new(2.0, 0.0, 0.0));
        let enemy_structure_inside = spawn_test_structure(
            &mut app,
            "CommandCenter",
            Team::Chaos,
            Vec3::new(1.4, 0.0, 0.0),
        );

        app.update();

        let (duration, scale) =
            support_shield_values(&app, friendly_inside).expect("nearby ally should be shielded");
        assert!((duration - 0.7).abs() < 0.001);
        assert!((scale - 0.55).abs() < 0.001);
        assert!(
            support_shield_values(&app, allied_inside).is_some(),
            "different-team allies should be shielded like Godot team_id allies"
        );
        assert!(
            support_shield_values(&app, allied_structure_inside).is_some(),
            "Godot MobileShieldProjector should shield allied structures because Structure extends Unit"
        );
        assert!(
            support_shield_values(&app, projector).is_some(),
            "Godot shields the projector itself because it is an allied unit in range"
        );
        assert!(
            support_shield_values(&app, friendly_outside).is_none(),
            "allied units outside radius should not be shielded"
        );
        assert!(
            support_shield_values(&app, enemy_inside).is_none(),
            "enemy units inside radius should not be shielded"
        );
        assert!(
            support_shield_values(&app, enemy_structure_inside).is_none(),
            "enemy structures inside radius should not be shielded"
        );
    }

