    #[test]
    fn pending_orbital_strike_delays_then_damages_enemy_units_like_godot() {
        let mut app = support_effect_test_app();
        app.update();

        let enemy_inside = spawn_test_unit(&mut app, "Tank", Team::Demon, Vec3::new(2.0, 0.0, 0.0));
        let enemy_outside =
            spawn_test_unit(&mut app, "Tank", Team::Demon, Vec3::new(5.0, 0.0, 0.0));
        let friendly_inside =
            spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::new(1.0, 0.0, 0.0));
        let shielded_enemy_inside =
            spawn_test_unit(&mut app, "Tank", Team::Demon, Vec3::new(2.5, 0.0, 0.0));
        app.world_mut()
            .entity_mut(shielded_enemy_inside)
            .insert(SupportShield {
                remaining: 2.0,
                damage_scale: 0.25,
            });
        let strike = app
            .world_mut()
            .spawn((
                Transform::from_translation(Vec3::ZERO),
                PendingOrbitalStrike {
                    remaining: 1.5,
                    radius: 3.4,
                    damage: 3.0,
                    impact_scale: 2.0,
                    team: Team::Human,
                },
            ))
            .id();
        let enemy_inside_before = current_health(&app, enemy_inside);
        let enemy_outside_before = current_health(&app, enemy_outside);
        let friendly_inside_before = current_health(&app, friendly_inside);
        let shielded_enemy_before = current_health(&app, shielded_enemy_inside);

        app.update();

        assert_eq!(
            current_health(&app, enemy_inside),
            enemy_inside_before,
            "strike should wait for its Godot impact delay before damaging"
        );
        assert!(
            app.world().get_entity(strike).is_ok(),
            "pending strike should remain before impact"
        );

        app.update();

        assert_eq!(
            current_health(&app, enemy_inside),
            enemy_inside_before - 3.0,
            "Godot support impact_scale is visual-only; enemy units should take raw damage"
        );
        assert_eq!(
            current_health(&app, shielded_enemy_inside),
            shielded_enemy_before - 0.75,
            "support shields should scale raw Godot support damage after impact_scale is ignored"
        );
        assert_eq!(
            current_health(&app, enemy_outside),
            enemy_outside_before,
            "enemy units outside radius should not take support damage"
        );
        assert_eq!(
            current_health(&app, friendly_inside),
            friendly_inside_before,
            "friendly units should not take support damage"
        );
        assert!(
            app.world().get_entity(strike).is_err(),
            "pending strike should despawn after impact"
        );
    }

