    #[test]
    fn radar_sweep_activation_spawns_temporary_revealer_like_godot() {
        let mut app = support_activation_test_app(SupportPowerKind::RadarSweep);
        let target = Vec3::new(4.0, 0.0, -3.0);
        app.world_mut()
            .resource_mut::<TestSupportActivation>()
            .target = target;
        spawn_test_structure(&mut app, "RadarUplink", Team::Human, Vec3::ZERO);

        app.update();

        assert_eq!(support_activation_result(&app), Some(true));
        let def = SupportPowerKind::RadarSweep.definition();
        let reveal = {
            let world = app.world_mut();
            let mut query = world.query::<(
                &Team,
                &Transform,
                &TemporarySupportReveal,
                &VisionRadius,
                &VisibilityState,
            )>();
            query
                .iter(world)
                .map(|(team, transform, reveal, vision, visibility)| {
                    (
                        *team,
                        transform.translation,
                        reveal.remaining,
                        reveal.radius,
                        vision.0,
                        visibility.visible,
                    )
                })
                .collect::<Vec<_>>()
        };
        assert_eq!(reveal.len(), 1);
        let (team, position, remaining, radius, vision_radius, visible) = reveal[0];
        assert_eq!(team, Team::Human);
        assert!(xz_distance(position, target) < 0.001);
        assert!((position.y - 0.01).abs() < 0.001);
        assert!((remaining - def.duration).abs() < 0.001);
        assert!((radius - def.radius).abs() < 0.001);
        assert!((vision_radius - def.radius).abs() < 0.001);
        assert!(visible);
        assert!(
            (app.world().resource::<SupportCooldowns>().remaining[Team::Human.index()]
                [SupportPowerKind::RadarSweep.idx()]
                - def.cooldown)
                .abs()
                < 0.001,
            "radar sweep should enter its Godot cooldown after activation"
        );
    }

