    #[test]
    fn emp_disabled_units_reject_new_orders_while_disabled_like_godot() {
        let mut app = App::new();
        app.add_plugins(MinimalPlugins)
            .add_systems(Update, clear_emp_disabled_orders);
        let target = test_entity(401);
        let disabled = app
            .world_mut()
            .spawn((
                EmpDisabled { remaining: 3.0 },
                MoveOrder {
                    target: Vec3::new(1.0, 0.0, 0.0),
                },
                FollowOrder {
                    target,
                    allow_enemy: true,
                    offset: Vec3::ZERO,
                },
                AttackOrder { target },
                CaptureOrder {
                    target,
                    elapsed: 0.25,
                },
                GarrisonOrder { target },
                HarvestOrder {
                    resource: Some(target),
                    state: HarvestState::MovingToResource,
                    collect_remaining: 0.4,
                },
                RepairOrder { target },
                ConstructOrder { target },
                AttackMoveOrder {
                    destination: Vec3::new(2.0, 0.0, 0.0),
                },
                PatrolOrder {
                    origin: Vec3::ZERO,
                    destination: Vec3::new(3.0, 0.0, 0.0),
                    moving_to_destination: true,
                },
                OrderQueue {
                    orders: VecDeque::from([UnitQueuedOrder::Move(Vec3::new(4.0, 0.0, 0.0))]),
                },
            ))
            .id();
        let active = app
            .world_mut()
            .spawn((
                MoveOrder {
                    target: Vec3::new(5.0, 0.0, 0.0),
                },
                OrderQueue {
                    orders: VecDeque::from([UnitQueuedOrder::Move(Vec3::new(6.0, 0.0, 0.0))]),
                },
            ))
            .id();

        app.update();

        let disabled_ref = app.world().entity(disabled);
        assert!(disabled_ref.get::<EmpDisabled>().is_some());
        assert!(disabled_ref.get::<MoveOrder>().is_none());
        assert!(disabled_ref.get::<FollowOrder>().is_none());
        assert!(disabled_ref.get::<AttackOrder>().is_none());
        assert!(disabled_ref.get::<CaptureOrder>().is_none());
        assert!(disabled_ref.get::<GarrisonOrder>().is_none());
        assert!(disabled_ref.get::<HarvestOrder>().is_none());
        assert!(disabled_ref.get::<RepairOrder>().is_none());
        assert!(disabled_ref.get::<ConstructOrder>().is_none());
        assert!(disabled_ref.get::<AttackMoveOrder>().is_none());
        assert!(disabled_ref.get::<PatrolOrder>().is_none());
        assert!(disabled_ref.get::<OrderQueue>().is_none());
        let active_ref = app.world().entity(active);
        assert!(active_ref.get::<MoveOrder>().is_some());
        assert!(active_ref.get::<OrderQueue>().is_some());
    }

