    #[test]
    fn nanite_repair_swarm_heals_allies_and_skips_enemies_like_godot() {
        let mut app = support_activation_test_app(SupportPowerKind::NaniteRepairSwarm);
        app.world_mut()
            .resource_mut::<TeamRelations>()
            .set_allied(Team::Human, Team::Demon, true);
        spawn_test_structure(&mut app, "RoboticsBay", Team::Human, Vec3::ZERO);
        let allied = spawn_test_unit(&mut app, "Tank", Team::Demon, Vec3::ZERO);
        let enemy = spawn_test_unit(&mut app, "Tank", Team::Chaos, Vec3::ZERO);
        {
            let mut allied_entity = app.world_mut().entity_mut(allied);
            let mut health = allied_entity
                .get_mut::<Health>()
                .expect("allied tank health");
            health.current = health.max - 6.0;
        }
        {
            let mut enemy_entity = app.world_mut().entity_mut(enemy);
            let mut health = enemy_entity.get_mut::<Health>().expect("enemy tank health");
            health.current = health.max - 6.0;
        }
        let allied_before = current_health(&app, allied);
        let enemy_before = current_health(&app, enemy);

        app.update();

        assert_eq!(support_activation_result(&app), Some(true));
        assert!(
            current_health(&app, allied) > allied_before,
            "Godot Nanite Repair Swarm should heal allied units"
        );
        assert_eq!(
            current_health(&app, enemy),
            enemy_before,
            "Godot Nanite Repair Swarm should skip enemies"
        );
    }

