    #[test]
    fn paradrop_spawns_godot_infantry_mix_after_delay() {
        let mut app = support_effect_test_app();
        app.update();

        let def = SupportPowerKind::Paradrop.definition();
        let drop = app
            .world_mut()
            .spawn(PendingParadrop {
                remaining: 1.5,
                team: Team::Human,
                target: Vec3::new(4.0, 0.0, 4.0),
                unit_paths: def.unit_paths,
            })
            .id();

        app.update();

        assert_eq!(
            unit_count_by_id(&mut app, Team::Human, "LightRifleInfantry"),
            0
        );
        assert_eq!(unit_count_by_id(&mut app, Team::Human, "RocketInfantry"), 0);
        assert!(
            app.world().get_entity(drop).is_ok(),
            "pending paradrop should remain before its delay elapses"
        );

        app.update();

        assert_eq!(
            unit_count_by_id(&mut app, Team::Human, "LightRifleInfantry"),
            2,
            "Godot paradrop contains two rifle infantry"
        );
        assert_eq!(
            unit_count_by_id(&mut app, Team::Human, "RocketInfantry"),
            1,
            "Godot paradrop contains one rocket infantry"
        );
        assert!(
            app.world().get_entity(drop).is_err(),
            "pending paradrop should despawn after spawning units"
        );
    }

