    #[test]
    fn saboteur_capture_steals_resources_like_godot_infiltration() {
        let mut app = capture_test_app();
        let refinery = spawn_test_structure(&mut app, "Refinery", Team::Demon, Vec3::ZERO);
        let saboteur = spawn_ready_saboteur_capture(&mut app, refinery);
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            let human = economies.get_mut(Team::Human);
            human.ore = 10;
            human.crystal = 2;
            let demon = economies.get_mut(Team::Demon);
            demon.ore = 20;
            demon.crystal = 7;
        }

        let saboteur_def =
            registry::entity("SaboteurInfiltrator").expect("saboteur definition should exist");
        let refinery_def = registry::entity("Refinery").expect("refinery definition should exist");
        let stolen_ore = infiltration_steal_amount(
            20,
            saboteur_def.infiltration_resource_steal_ratio,
            saboteur_def.infiltration_resource_steal_cap,
        );
        let stolen_crystal = infiltration_steal_amount(
            7,
            saboteur_def.infiltration_resource_steal_ratio,
            saboteur_def.infiltration_resource_steal_cap,
        );

        app.update();

        let economies = app.world().resource::<Economies>();
        assert_eq!(
            economies.get(Team::Human).ore,
            10 + stolen_ore + refinery_def.capture_bonus_ore
        );
        assert_eq!(
            economies.get(Team::Human).crystal,
            2 + stolen_crystal + refinery_def.capture_bonus_crystal
        );
        assert_eq!(economies.get(Team::Demon).ore, 20 - stolen_ore);
        assert_eq!(economies.get(Team::Demon).crystal, 7 - stolen_crystal);
        assert_eq!(structure_team(&app, refinery), Team::Human);
        assert!(
            app.world().get_entity(saboteur).is_err(),
            "saboteur should be consumed after successful infiltration capture"
        );
    }

