    #[test]
    fn ai_supply_crate_collection_prefers_crates_near_units_like_godot() {
        let mut app = ai_supply_crate_collection_test_app();
        let home_crate_position = DEMON_BASE + Vec3::new(0.4, 0.0, 0.0);
        let front_crate_position = Vec3::new(-11.0, 0.0, -15.0);
        let home_crate =
            spawn_test_supply_crate(&mut app, SupplyCrateEffect::Resources, home_crate_position);
        let front_crate =
            spawn_test_supply_crate(&mut app, SupplyCrateEffect::Resources, front_crate_position);
        let collector =
            spawn_test_unit(&mut app, "Tank", Team::Demon, Vec3::new(-15.0, 0.0, -15.0));
        app.world_mut()
            .entity_mut(collector)
            .insert(HoldPosition { enabled: false });
        let (ore_before, crystal_before) = {
            let economy = app.world().resource::<Economies>().get(Team::Demon);
            (economy.ore, economy.crystal)
        };

        app.update();

        let move_target = app
            .world()
            .entity(collector)
            .get::<MoveOrder>()
            .expect("AI collector should be assigned to an available supply crate")
            .target;
        assert!(
            xz_distance(move_target, front_crate_position) < 0.001,
            "AI should prefer the supply crate nearest its active units, not the one nearest base"
        );
        assert!(
            app.world().get_entity(front_crate).is_ok(),
            "front crate should not be consumed before the collector reaches it"
        );

        app.world_mut()
            .entity_mut(collector)
            .get_mut::<Transform>()
            .expect("test collector should have a transform")
            .translation = front_crate_position;
        app.update();

        let economy = app.world().resource::<Economies>().get(Team::Demon);
        assert_eq!(economy.ore, ore_before + SUPPLY_CRATE_RESOURCE_ORE);
        assert_eq!(
            economy.crystal,
            crystal_before + SUPPLY_CRATE_RESOURCE_CRYSTAL
        );
        assert!(
            app.world().resource::<BattleLog>().entries.is_empty(),
            "enemy supply crate pickups should not create human player notifications"
        );
        assert!(
            app.world().get_entity(front_crate).is_err(),
            "assigned crate should be consumed once the AI collector reaches it"
        );
        assert!(
            app.world().get_entity(home_crate).is_ok(),
            "unassigned base-side crate should remain for a later collector"
        );
    }

