    #[test]
    fn kill_credit_promotions_spawn_visible_effect_and_apply_stats_like_godot() {
        let mut app = veterancy_promotion_test_app();
        let tank = spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::ZERO);
        let (base_health, base_damage, base_range, base_vision) = {
            let tank_ref = app.world().entity(tank);
            (
                tank_ref
                    .get::<Health>()
                    .expect("tank should have health")
                    .max,
                tank_ref
                    .get::<Weapon>()
                    .expect("tank should have weapon")
                    .damage,
                tank_ref
                    .get::<Weapon>()
                    .expect("tank should have weapon")
                    .range,
                tank_ref
                    .get::<VisionRadius>()
                    .expect("tank should have vision")
                    .0,
            )
        };
        app.world_mut()
            .resource_mut::<KillCredits>()
            .0
            .extend([tank, tank]);

        app.update();

        {
            let tank_ref = app.world().entity(tank);
            let veteran = tank_ref
                .get::<Veterancy>()
                .expect("tank should track veterancy");
            assert_eq!(veteran.experience_points, 2);
            assert_eq!(veteran.rank, 1);
            let health = tank_ref.get::<Health>().expect("tank should have health");
            assert_eq!(
                health.max,
                (base_health * VETERANCY_HP_MULTIPLIER_BY_RANK[1]).ceil()
            );
            assert_eq!(
                health.current, health.max,
                "Godot keeps full-health promoted units full after the max HP increase"
            );
            let weapon = tank_ref.get::<Weapon>().expect("tank should have weapon");
            assert!(
                (weapon.damage - base_damage * VETERANCY_DAMAGE_MULTIPLIER_BY_RANK[1]).abs()
                    < f32::EPSILON
            );
            assert!(
                (weapon.range - (base_range + VETERANCY_RANGE_BONUS_BY_RANK[1])).abs()
                    < f32::EPSILON
            );
            assert!(
                (tank_ref
                    .get::<VisionRadius>()
                    .expect("tank should have vision")
                    .0
                    - (base_vision + VETERANCY_SIGHT_BONUS_BY_RANK[1]))
                    .abs()
                    < f32::EPSILON
            );
        }

        let effects = promotion_effects(&mut app);
        assert_eq!(effects.len(), 1);
        assert_eq!(effects[0].rank, 1);
        assert_eq!(effects[0].team, Team::Human);
        assert_eq!(
            app.world().resource::<AudioFeedback>().pending_sound,
            Some(SoundEffectKind::UnitPromoted)
        );
        assert_eq!(
            app.world().resource::<BattleLog>().entries.len(),
            1,
            "player-visible Godot promotions notify the HUD"
        );
    }

