    #[test]
    fn factions_have_distinct_startup_rosters() {
        let human_startup = team_startup(Team::Human);
        let demon_startup = team_startup(Team::Demon);
        let chaos_startup = team_startup(Team::Chaos);

        assert_ne!(
            human_startup.structures.len(),
            demon_startup.structures.len(),
            "startup structure counts should differ"
        );
        assert_ne!(
            demon_startup.structures.len(),
            chaos_startup.structures.len(),
            "startup structure counts should differ"
        );
        assert!(
            human_startup.units.len() > 0
                && demon_startup.units.len() > 0
                && chaos_startup.units.len() > 0,
            "all factions must have startup units"
        );
    }

    #[test]
    fn factions_have_distinct_production_rosters_for_three_playstyles() {
        let alliance = faction_def(SkirmishFaction::Alliance).expect("人族 faction should exist");
        let demon = faction_def(SkirmishFaction::Demon).expect("魔族 faction should exist");
        let chaos = faction_def(SkirmishFaction::Chaos).expect("混沌族 faction should exist");
        let products = |faction: &registry::FactionDef, producer| {
            faction
                .production_for(producer)
                .expect("faction producer should exist")
        };

        assert_eq!(alliance.label, SkirmishFaction::Alliance.label());
        assert_eq!(demon.label, SkirmishFaction::Demon.label());
        assert_eq!(chaos.label, SkirmishFaction::Chaos.label());

        for producer in ["Barracks", "VehicleFactory", "AircraftFactory"] {
            let alliance_products = products(alliance, producer);
            let demon_products = products(demon, producer);
            let chaos_products = products(chaos, producer);

            assert_ne!(
                alliance_products, demon_products,
                "{producer} should not share one roster between 人族 and 魔族"
            );
            assert_ne!(
                alliance_products, chaos_products,
                "{producer} should not share one roster between 人族 and 混沌族"
            );
            assert_ne!(
                demon_products, chaos_products,
                "{producer} should not share one roster between 魔族 and 混沌族"
            );
        }

        assert_eq!(
            products(alliance, "Barracks").len(),
            17,
            "人族 keeps the broad full-tech infantry roster"
        );
        assert_eq!(
            products(demon, "Barracks").len(),
            8,
            "魔族 keeps a tighter assault infantry roster"
        );
        assert_eq!(
            products(chaos, "Barracks").len(),
            9,
            "混沌族 keeps support/control infantry instead of assault infantry"
        );
        assert!(products(demon, "VehicleFactory").contains(&"HammerSiegeTank"));
        assert!(!products(chaos, "VehicleFactory").contains(&"HammerSiegeTank"));
        assert!(products(chaos, "VehicleFactory").contains(&"JammerVehicle"));
        assert!(!products(demon, "VehicleFactory").contains(&"JammerVehicle"));
        assert!(products(alliance, "AircraftFactory").contains(&"InterceptorVTOL"));
        assert!(products(alliance, "AircraftFactory").contains(&"BomberVTOL"));
    }

    #[test]
    fn factions_have_distinct_battlefield_identity_markers() {
        assert_eq!(
            FactionIdentityMarker::for_faction(SkirmishFaction::Alliance),
            FactionIdentityMarker::Human
        );
        assert_eq!(
            FactionIdentityMarker::for_faction(SkirmishFaction::Demon),
            FactionIdentityMarker::Demon
        );
        assert_eq!(
            FactionIdentityMarker::for_faction(SkirmishFaction::Chaos),
            FactionIdentityMarker::Chaos
        );
        assert_eq!(
            FactionIdentityMarker::for_team(Team::Human),
            Some(FactionIdentityMarker::Human)
        );
        assert_eq!(
            FactionIdentityMarker::for_team(Team::Demon),
            Some(FactionIdentityMarker::Demon)
        );
        assert_eq!(
            FactionIdentityMarker::for_team(Team::Chaos),
            Some(FactionIdentityMarker::Chaos)
        );
        assert_eq!(FactionIdentityMarker::for_team(Team::Neutral), None);

        assert_eq!(FactionIdentityMarker::Human.part_count(), 2);
        assert_eq!(FactionIdentityMarker::Demon.part_count(), 3);
        assert_eq!(FactionIdentityMarker::Chaos.part_count(), 2);
    }

    #[test]
    fn ai_mixed_offense_rosters_are_valid_and_exclude_infiltration_controller_units() {
        for team in Team::all() {
            let faction = registry::faction(team.faction_id()).expect("team should have faction");
            let profile = team_ai_profile(team);
            assert!(
                profile.production_priority.len() >= 20,
                "{} AI should have a mixed offense roster",
                team.label()
            );
            for id in profile.production_priority {
                let def = registry::entity(id).expect("AI production id should exist");
                assert_eq!(
                    def.role,
                    registry::EntityRole::Unit,
                    "{id} should be a unit production candidate"
                );
                assert!(
                    faction
                        .production
                        .iter()
                        .any(|entry| entry.products.contains(id)),
                    "{id} should be producible by {}",
                    team.label()
                );
                assert_ne!(
                    *id, AI_SABOTEUR_ID,
                    "saboteurs should stay in the infiltration controller"
                );
            }
        }
    }

