    #[test]
    fn ai_reopens_offense_training_after_battlegroup_losses_like_godot() {
        let mut app = ai_director_attack_test_app();
        let profile = team_ai_profile_for_difficulty(Team::Demon, AiDifficulty::Normal);
        let target_battle_units = ai_battlegroup_target_units(&profile);
        spawn_test_ai_full_tech(&mut app, Team::Demon);
        for index in 0..profile.expected_workers {
            spawn_test_unit(
                &mut app,
                "Worker",
                Team::Demon,
                Vec3::new(index as f32, 0.0, 8.0),
            );
        }
        for index in 0..profile.expected_ore_harvesters {
            spawn_test_unit(
                &mut app,
                "OreHarvester",
                Team::Demon,
                Vec3::new(index as f32, 0.0, 10.0),
            );
        }
        let mut battlegroup_units = Vec::new();
        for index in 0..target_battle_units {
            battlegroup_units.push(spawn_test_unit(
                &mut app,
                "Tank",
                Team::Demon,
                Vec3::new(12.0 + index as f32, 0.0, 12.0),
            ));
        }
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            let demon = economies.get_mut(Team::Demon);
            demon.ore = 10_000;
            demon.crystal = 10_000;
        }
        set_ai_director_production_refresh_only(&mut app, Team::Demon);

        app.update();

        assert_eq!(
            battle_unit_count(&mut app, Team::Demon),
            target_battle_units,
            "full Godot battlegroups should suppress extra offense production"
        );
        let lost_unit = battlegroup_units[0];
        app.world_mut().entity_mut(lost_unit).despawn();
        assert_eq!(
            battle_unit_count(&mut app, Team::Demon),
            target_battle_units - 1
        );

        set_ai_director_production_refresh_only(&mut app, Team::Demon);
        app.update();

        assert_eq!(
            battle_unit_count(&mut app, Team::Demon),
            target_battle_units,
            "after a full battlegroup loses a unit, Godot AI should reopen production demand"
        );
        assert_eq!(
            unit_count_by_id(&mut app, Team::Demon, "Tank"),
            target_battle_units,
            "Demon normal AI should replace the lost opening battle unit from its mixed roster"
        );
    }

