    #[test]
    fn vehicle_factory_roster_order_matches_godot_menu_layout() {
        let faction = registry::faction("alliance").expect("alliance faction should exist");
        let products = faction
            .production_for("VehicleFactory")
            .expect("vehicle factory should produce units");

        assert_eq!(
            products,
            &[
                "Tank",
                "ScoutRover",
                "OreHarvester",
                "MobileConstructionVehicle",
                "MirageScoutTank",
                "FlameAssaultBuggy",
                "DroneMineLayer",
                "TeslaCrawlerMk2",
                "RocketTrooperRobot",
                "ModularMissileCarrier",
                "LongbowMissileCrawler",
                "JammerVehicle",
                "AntiAirWalker",
                "FlakHoverTank",
                "MobileRepairCrawler",
                "MobileShieldProjector",
                "SiegeArtilleryVehicle",
                "SiegeDrillTank",
                "LanceBeamTank",
                "RailgunTank",
                "HammerSiegeTank",
                "HeavySiegeWalker",
                "RailArtilleryWalker",
            ],
            "Bevy command slots should follow Godot VehicleFactoryMenu button order"
        );

        let chaos = registry::faction("chaos").expect("chaos faction should exist");
        let chaos_products = chaos
            .production_for("VehicleFactory")
            .expect("chaos vehicle factory should produce units");
        let longbow_index = chaos_products
            .iter()
            .position(|id| *id == "LongbowMissileCrawler")
            .expect("chaos should include LongbowMissileCrawler");
        let jammer_index = chaos_products
            .iter()
            .position(|id| *id == "JammerVehicle")
            .expect("chaos should include JammerVehicle");
        assert!(
            longbow_index < jammer_index,
            "faction-filtered vehicle rosters should preserve Godot menu order"
        );
    }

