    #[test]
    fn ai_prioritizes_economy_build_over_low_offense_training_when_resource_limited_like_godot() {
        let mut app = ai_director_attack_test_app();
        spawn_test_structure(&mut app, "CommandCenter", Team::Demon, Vec3::ZERO);
        spawn_test_structure(
            &mut app,
            "VehicleFactory",
            Team::Demon,
            Vec3::new(3.0, 0.0, 0.0),
        );
        spawn_test_unit(&mut app, "Worker", Team::Demon, Vec3::new(1.0, 0.0, 0.0));
        spawn_test_unit(&mut app, "Worker", Team::Demon, Vec3::new(1.8, 0.0, 0.0));
        spawn_test_unit(&mut app, "Worker", Team::Demon, Vec3::new(2.6, 0.0, 0.0));
        {
            let refinery_cost = registry::entity("Refinery")
                .expect("registry should include Refinery")
                .cost;
            let tank_cost = registry::entity("Tank")
                .expect("registry should include Tank")
                .cost;
            assert!(
                tank_cost.ore <= refinery_cost.ore && tank_cost.crystal <= refinery_cost.crystal,
                "fixture requires Tank to be individually affordable from the Refinery budget"
            );

            let mut economies = app.world_mut().resource_mut::<Economies>();
            let demon = economies.get_mut(Team::Demon);
            demon.ore = refinery_cost.ore;
            demon.crystal = refinery_cost.crystal;
        }
        set_ai_director_production_and_build_refresh_only(&mut app, Team::Demon);

        app.update();

        assert_eq!(
            unit_count_by_id(&mut app, Team::Demon, "Tank"),
            0,
            "Godot AI should not spend scarce high-priority economy resources on low-priority offense first"
        );
        assert!(
            structure_snapshots_by_id(&mut app, "Refinery")
                .iter()
                .any(|(_, team, _, constructed)| *team == Team::Demon && !constructed),
            "Godot priority order should spend the shared budget on the pending Refinery"
        );
        {
            let economies = app.world().resource::<Economies>();
            let demon = economies.get(Team::Demon);
            assert_eq!(
                (demon.ore, demon.crystal),
                (0, 0),
                "Refinery should consume the exact scarce budget"
            );
        }
    }

