    #[test]
    fn ai_engineer_capture_prioritizes_neutral_tech_then_enemy_utility_like_godot() {
        let mut app = ai_director_attack_test_app();
        let engineer = spawn_test_unit(&mut app, "EngineerDrone", Team::Demon, Vec3::ZERO);
        let neutral_oil = spawn_test_structure(
            &mut app,
            "TechOilDerrick",
            Team::Neutral,
            Vec3::new(3.0, 0.0, 0.0),
        );
        let enemy_reactor = spawn_test_structure(
            &mut app,
            "PowerReactor",
            Team::Human,
            Vec3::new(4.0, 0.0, 0.0),
        );

        set_ai_director_capture_refresh_only(&mut app, Team::Demon);
        app.update();

        assert!(
            matches!(
                app.world().entity(engineer).get::<CaptureOrder>(),
                Some(CaptureOrder { target, .. }) if *target == neutral_oil
            ),
            "AI engineer should prioritize neutral tech assets before enemy utility structures"
        );

        {
            let mut engineer_entity = app.world_mut().entity_mut(engineer);
            engineer_entity.remove::<CaptureOrder>();
            engineer_entity.remove::<MoveOrder>();
        }
        *app.world_mut()
            .entity_mut(neutral_oil)
            .get_mut::<Team>()
            .expect("test structure should have a team") = Team::Demon;

        set_ai_director_capture_refresh_only(&mut app, Team::Demon);
        app.update();

        assert!(
            matches!(
                app.world().entity(engineer).get::<CaptureOrder>(),
                Some(CaptureOrder { target, .. }) if *target == enemy_reactor
            ),
            "AI engineer raid should continue onto enemy utility structures after taking neutral tech"
        );
    }

    #[test]
    fn ai_director_places_defenses_on_enemy_facing_side_like_godot() {
        let mut app = ai_director_attack_test_app();
        let command_position = Vec3::new(10.0, 0.0, 10.0);
        let enemy_position = Vec3::new(34.0, 0.0, 10.0);
        spawn_test_structure(&mut app, "CommandCenter", Team::Demon, command_position);
        spawn_test_structure(&mut app, "CommandCenter", Team::Human, enemy_position);
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            let demon = economies.get_mut(Team::Demon);
            demon.ore = 10_000;
            demon.crystal = 10_000;
        }
        {
            let mut director = app.world_mut().resource_mut::<AiDirector>();
            for idx in 0..3 {
                director.production_timer[idx] = 999.0;
                director.build_timer[idx] = 999.0;
                director.capture_timer[idx] = 999.0;
                director.saboteur_timer[idx] = 999.0;
                director.support_timer[idx] = 999.0;
                director.attack_timer[idx] = 999.0;
            }
            director.build_timer[Team::Demon.index()] = 0.0;
        }

        app.update();

        let defenses = structure_snapshots_by_id(&mut app, "AntiAirTurret");
        let (_, team, position, constructed) = defenses
            .iter()
            .find(|(_, team, _, _)| *team == Team::Demon)
            .copied()
            .expect("Demon AI should build its first available defense");
        assert_eq!(team, Team::Demon);
        assert!(
            !constructed,
            "AI-built defense should begin under construction"
        );
        assert!(
            position.x > command_position.x,
            "defense should be placed on the enemy-facing side"
        );
        assert!(
            xz_distance(position, enemy_position) < xz_distance(command_position, enemy_position),
            "defense should be closer to the enemy approach than the command center"
        );
    }

    #[test]
    fn ai_offense_builds_production_on_enemy_facing_frontline_like_godot() {
        let mut app = ai_director_attack_test_app();
        app.insert_resource(MapBounds {
            half_width: 80.0,
            half_depth: 80.0,
        });
        let rear_command = Vec3::new(8.0, 0.0, 10.0);
        let front_command = Vec3::new(22.0, 0.0, 10.0);
        let enemy_position = Vec3::new(44.0, 0.0, 10.0);
        spawn_test_structure(&mut app, "CommandCenter", Team::Demon, rear_command);
        spawn_test_structure(&mut app, "CommandCenter", Team::Demon, front_command);
        spawn_test_structure(&mut app, "CommandCenter", Team::Human, enemy_position);
        for (idx, id) in [
            "AntiAirTurret",
            "AntiAirTurret",
            "AntiGroundTurret",
            "AntiGroundTurret",
        ]
        .into_iter()
        .enumerate()
        {
            spawn_test_structure(
                &mut app,
                id,
                Team::Demon,
                Vec3::new(4.0 + idx as f32 * 1.5, 0.0, 4.0),
            );
        }
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            let demon = economies.get_mut(Team::Demon);
            demon.ore = 10_000;
            demon.crystal = 10_000;
        }

        set_ai_director_build_refresh_only(&mut app, Team::Demon);
        app.update();

        let factories = structure_snapshots_by_id(&mut app, "VehicleFactory");
        let (_, team, position, constructed) = factories
            .iter()
            .find(|(_, team, _, _)| *team == Team::Demon)
            .copied()
            .expect("AI offense should fill missing production after economy and defense");
        assert_eq!(team, Team::Demon);
        assert!(
            !constructed,
            "AI-built production structure should begin under construction"
        );
        assert!(
            position.x > front_command.x,
            "offense production should be placed on the enemy-facing side: position={position:?}, front={front_command:?}"
        );
        assert!(
            xz_distance(position, enemy_position) < xz_distance(front_command, enemy_position),
            "offense production should be closer to the enemy approach than the frontline command center: position={position:?}, front={front_command:?}, enemy={enemy_position:?}"
        );
        assert!(
            xz_distance(position, front_command) < xz_distance(position, rear_command),
            "offense production should anchor to the frontline command center: position={position:?}, front={front_command:?}, rear={rear_command:?}"
        );
    }

    #[test]
    fn ai_repair_starts_lowest_health_structures_and_caps_two_like_godot() {
        let mut app = ai_director_attack_test_app();
        let command_center =
            spawn_test_structure(&mut app, "CommandCenter", Team::Demon, Vec3::ZERO);
        let factory = spawn_test_structure(
            &mut app,
            "VehicleFactory",
            Team::Demon,
            Vec3::new(3.0, 0.0, 0.0),
        );
        let barracks =
            spawn_test_structure(&mut app, "Barracks", Team::Demon, Vec3::new(6.0, 0.0, 0.0));
        let light_damage = spawn_test_structure(
            &mut app,
            "PowerReactor",
            Team::Demon,
            Vec3::new(9.0, 0.0, 0.0),
        );
        set_health_current(&mut app, command_center, 8.0);
        set_health_current(&mut app, factory, 8.0);
        set_health_current(&mut app, barracks, 7.0);
        set_health_current(&mut app, light_damage, 10.0);

        let command_cost = structure_repair_cost(
            registry::entity("CommandCenter").expect("registry should include CommandCenter"),
            app.world()
                .entity(command_center)
                .get::<Health>()
                .expect("test structure should have health"),
        );
        let factory_cost = structure_repair_cost(
            registry::entity("VehicleFactory").expect("registry should include VehicleFactory"),
            app.world()
                .entity(factory)
                .get::<Health>()
                .expect("test structure should have health"),
        );
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            let demon = economies.get_mut(Team::Demon);
            demon.ore = 100;
            demon.crystal = 100;
        }
        set_ai_director_repair_refresh_only(&mut app, Team::Demon);

        app.update();

        assert!(has_manual_structure_repair(&app, command_center));
        assert!(has_manual_structure_repair(&app, factory));
        assert!(
            !has_manual_structure_repair(&app, barracks),
            "third eligible structure should wait for the next repair refresh"
        );
        assert!(
            !has_manual_structure_repair(&app, light_damage),
            "structures missing less than 25% health should not auto-repair"
        );
        assert!(current_health(&app, command_center) > 8.0);
        assert!(current_health(&app, factory) > 8.0);
        assert_eq!(current_health(&app, barracks), 7.0);
        assert_eq!(current_health(&app, light_damage), 10.0);
        let demon = app.world().resource::<Economies>().get(Team::Demon);
        assert_eq!(demon.ore, 100 - command_cost.ore - factory_cost.ore);
        assert_eq!(
            demon.crystal,
            100 - command_cost.crystal - factory_cost.crystal
        );
    }

