    #[test]
    fn ai_attack_wave_moves_support_battle_units_with_combat_units_like_godot() {
        let mut app = ai_director_attack_test_app();
        let target = spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::new(0.0, 0.0, 0.0));
        let attacker = spawn_test_unit(&mut app, "Tank", Team::Demon, Vec3::new(8.0, 0.0, 8.0));
        let support = spawn_test_unit(
            &mut app,
            "MobileRepairCrawler",
            Team::Demon,
            Vec3::new(8.8, 0.0, 8.4),
        );
        let harvester = spawn_test_unit(
            &mut app,
            "OreHarvester",
            Team::Demon,
            Vec3::new(9.4, 0.0, 8.4),
        );
        set_ai_director_attack_refresh_only(&mut app, Team::Demon);

        app.update();

        assert_eq!(
            app.world()
                .entity(attacker)
                .get::<AttackOrder>()
                .expect("armed AI battle unit should attack")
                .target,
            target
        );
        let follow = app
            .world()
            .entity(support)
            .get::<FollowOrder>()
            .expect("support battle unit should move with attack wave");
        assert_eq!(follow.target, target);
        assert!(follow.allow_enemy);
        assert!(app.world().entity(support).get::<AttackOrder>().is_none());
        assert!(app.world().entity(harvester).get::<AttackOrder>().is_none());
        assert!(app.world().entity(harvester).get::<FollowOrder>().is_none());
    }

