    #[test]
    fn ai_siege_drill_packs_and_chases_structure_target_that_leaves_deployed_range_like_godot() {
        let mut app = siege_drill_deploy_chase_test_app();
        let drill_position = Vec3::ZERO;
        let target = spawn_test_structure(
            &mut app,
            "CommandCenter",
            Team::Human,
            drill_position + Vec3::new(5.2, 0.0, 0.0),
        );
        let drill = spawn_test_unit(&mut app, "SiegeDrillTank", Team::Demon, drill_position);
        app.world_mut().entity_mut(drill).insert((
            HoldPosition { enabled: false },
            AttackOrder { target },
            MoveOrder {
                target: drill_position,
            },
        ));

        app.update();

        {
            let drill_ref = app.world().entity(drill);
            assert!(
                drill_ref.get::<DeployedSiegeMode>().is_some(),
                "AI siege drill should deploy against a structure inside deployed range"
            );
            assert_eq!(
                drill_ref.get::<AttackOrder>().map(|order| order.target),
                Some(target),
                "deploying should keep the active structure attack"
            );
            assert!(
                drill_ref.get::<MoveOrder>().is_none(),
                "deployed drill should stop moving while anchored"
            );
        }

        app.world_mut()
            .entity_mut(target)
            .get_mut::<Transform>()
            .expect("target structure should have transform")
            .translation = drill_position + Vec3::new(18.0, 0.0, 0.0);

        app.update();

        let drill_ref = app.world().entity(drill);
        assert!(
            drill_ref.get::<DeployedSiegeMode>().is_none(),
            "AI siege drill should pack up when the structure leaves deployed range"
        );
        assert_eq!(
            drill_ref.get::<AttackOrder>().map(|order| order.target),
            Some(target),
            "packing up should keep chasing the same structure target"
        );
        assert_eq!(
            drill_ref.get::<MoveOrder>().map(|order| order.target),
            Some(drill_position + Vec3::new(18.0, 0.0, 0.0)),
            "packed drill should resume movement toward the out-of-range structure"
        );
    }

