        let normal = team_ai_profile_for_difficulty(Team::Chaos, AiDifficulty::Normal);
        let hard = team_ai_profile_for_difficulty(Team::Chaos, AiDifficulty::Hard);

        assert!(hard.active_offense_enabled);
