    #[test]
    fn refinery_completion_spawns_owner_harvester_like_godot() {
        let mut app = construction_completion_test_app();
        let refinery_position = Vec3::new(10.5, 0.0, 14.5);
        let build_origin = Vec3::new(6.0, 0.0, 13.0);
        let refinery = spawn_test_structure(&mut app, "Refinery", Team::Human, refinery_position);
        app.world_mut()
            .entity_mut(refinery)
            .insert(UnderConstruction {
                remaining: 0.4,
                total: 1.0,
                cost: registry::entity("Refinery")
                    .expect("registry should include Refinery")
                    .cost,
                free_harvester_origin: Some(build_origin),
            });

        app.update();

        assert_eq!(
            unit_count_by_id(&mut app, Team::Human, "OreHarvester"),
            0,
            "unfinished Godot refineries should not spawn their free harvester"
        );
        assert!(
            app.world()
                .entity(refinery)
                .get::<UnderConstruction>()
                .is_some(),
            "unfinished refinery should stay under construction"
        );

        app.world_mut()
            .entity_mut(refinery)
            .get_mut::<UnderConstruction>()
            .expect("refinery should still be under construction")
            .remaining = 0.0;

        app.update();

        assert!(
            app.world()
                .entity(refinery)
                .get::<UnderConstruction>()
                .is_none(),
            "completed refinery should become an active dropoff"
        );
        assert_eq!(
            unit_count_by_id(&mut app, Team::Human, "OreHarvester"),
            1,
            "completed Godot refineries spawn one free owner harvester"
        );
        let harvester_position = runtime_unit_positions(&mut app, Team::Human, "OreHarvester")
            .pop()
            .expect("free harvester should exist");
        let refinery_radius = registry::entity("Refinery")
            .expect("registry should include Refinery")
            .radius;
        assert!(
            xz_distance(harvester_position, refinery_position) > refinery_radius,
            "free harvester should spawn outside the refinery footprint"
        );
        assert!(
            !can_unit_construct_structures(&test_unit("OreHarvester")),
            "Godot free ore harvesters should not inherit worker construction ability"
        );
    }

