    #[test]
    fn manual_structure_placement_rejects_invalid_positions_like_godot() {
        let mut app = structure_placement_test_app();
        let command_def =
            registry::entity("CommandCenter").expect("registry should include CommandCenter");
        let barracks_def = registry::entity("Barracks").expect("registry should include Barracks");
        spawn_test_structure(&mut app, "CommandCenter", Team::Human, Vec3::ZERO);
        let valid_point = Vec3::new(command_def.radius + barracks_def.radius + 1.0, 0.0, 0.0);
        app.insert_resource(StructurePlacementValidityProbe {
            id: "Barracks",
            point: valid_point,
            result: None,
        })
        .add_systems(Update, run_structure_placement_validity_probe);
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            economies.human.ore = 500;
            economies.human.crystal = 300;
        }

        app.update();
        assert_eq!(
            app.world()
                .resource::<StructurePlacementValidityProbe>()
                .result,
            Some(StructurePlacementValidity::Valid)
        );

        app.world_mut()
            .resource_mut::<StructurePlacementValidityProbe>()
            .point = Vec3::ZERO;
        app.update();
        assert_eq!(
            app.world()
                .resource::<StructurePlacementValidityProbe>()
                .result,
            Some(StructurePlacementValidity::CollidesWithObject)
        );

        app.world_mut()
            .resource_mut::<StructurePlacementValidityProbe>()
            .point = Vec3::new(MAP_HALF_EXTENT - 1.0, 0.0, 0.0);
        app.update();
        assert_eq!(
            app.world()
                .resource::<StructurePlacementValidityProbe>()
                .result,
            Some(StructurePlacementValidity::OutOfBaseRadius)
        );

        app.world_mut()
            .resource_mut::<StructurePlacementValidityProbe>()
            .point = Vec3::new(MAP_HALF_EXTENT + 1.0, 0.0, 0.0);
        app.update();
        assert_eq!(
            app.world()
                .resource::<StructurePlacementValidityProbe>()
                .result,
            Some(StructurePlacementValidity::OutOfMap)
        );

        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            economies.human.ore = 0;
            economies.human.crystal = 0;
        }
        app.world_mut()
            .resource_mut::<StructurePlacementValidityProbe>()
            .point = valid_point;
        app.update();
        assert_eq!(
            app.world()
                .resource::<StructurePlacementValidityProbe>()
                .result,
            Some(StructurePlacementValidity::NotEnoughResources)
        );
    }

    #[test]
    fn selling_structure_refunds_scaled_health_and_queued_units_like_godot() {
        let mut app = sell_structure_test_app();
        let factory = spawn_test_structure(
            &mut app,
            "VehicleFactory",
            Team::Human,
            Vec3::new(2.0, 0.0, 0.0),
        );
        app.world_mut().entity_mut(factory).insert(Selected);
        let tank_def = registry::entity("Tank").expect("registry should include Tank");
        let factory_def =
            registry::entity("VehicleFactory").expect("registry should include VehicleFactory");
        let sell_refund = structure_sell_refund(factory_def, &Health::new(factory_def.health));
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            let human = economies.get_mut(Team::Human);
            human.ore = 20 - tank_def.cost.ore;
            human.crystal = 20 - tank_def.cost.crystal;
        }
        app.world_mut()
            .resource_mut::<BuildQueue>()
            .0
            .push(BuildJob {
                team: Team::Human,
                action: BuildAction::Train("Tank"),
                producer_entity: factory,
                producer_id: "VehicleFactory",
                timer: tank_def.build_seconds,
                origin: Vec3::ZERO,
            });

        app.update();

        let result = command_result(&app);
        assert!(result.attempted && result.handled);
        assert!(
            app.world().get_entity(factory).is_err(),
            "sold structure should leave the world"
        );
        assert!(
            app.world().resource::<BuildQueue>().0.is_empty(),
            "selling should cancel queued production owned by the structure"
        );
        let human = app.world().resource::<Economies>().get(Team::Human);
        assert_eq!(human.ore, 20 + sell_refund.0);
        assert_eq!(human.crystal, 20 + sell_refund.1);

        let half_health = Health {
            current: factory_def.health * 0.5,
            max: factory_def.health,
        };
        let damaged_refund = structure_sell_refund(factory_def, &half_health);
        assert!(damaged_refund.0 < sell_refund.0);
        if factory_def.cost.crystal > 0 {
            assert!(damaged_refund.1 < sell_refund.1);
        } else {
            assert_eq!(damaged_refund.1, 0);
        }
    }

    #[test]
    fn manual_structure_repair_spends_upfront_and_restores_full_hp_like_godot() {
        let mut app = manual_repair_test_app();
        let command_center =
            spawn_test_structure(&mut app, "CommandCenter", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(command_center).insert(Selected);
        let def = registry::entity("CommandCenter").expect("registry should include CommandCenter");
        set_health_current(&mut app, command_center, def.health - 4.0);
        let repair_cost = structure_repair_cost(
            def,
            app.world()
                .entity(command_center)
                .get::<Health>()
                .expect("test structure should have health"),
        );
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            let human = economies.get_mut(Team::Human);
            human.ore = 20;
            human.crystal = 20;
        }

        app.update();

        let result = command_result(&app);
        assert!(result.attempted && result.handled);
        {
            let human = app.world().resource::<Economies>().get(Team::Human);
            assert_eq!(human.ore, 20 - repair_cost.ore);
            assert_eq!(human.crystal, 20 - repair_cost.crystal);
        }
        assert!(current_health(&app, command_center) > def.health - 4.0);
        assert!(current_health(&app, command_center) <= def.health);
        assert!(
            app.world()
                .entity(command_center)
                .get::<ManualStructureRepair>()
                .is_some(),
            "repair should stay active until all missing hitpoints are restored"
        );

        app.update();

        assert_eq!(current_health(&app, command_center), def.health);
        assert!(
            app.world()
                .entity(command_center)
                .get::<ManualStructureRepair>()
                .is_none()
        );
    }

