    #[test]
    fn repair_pad_respects_power_and_construction_state_like_godot() {
        let mut app = aura_test_app();
        app.world_mut()
            .resource_mut::<Economies>()
            .get_mut(Team::Human)
            .power_used = 10;
        let worker = spawn_test_unit(&mut app, "Worker", Team::Human, Vec3::new(1.0, 0.0, 0.0));
        set_health_current(&mut app, worker, 1.0);
        spawn_aura_structure(
            &mut app,
            "RepairPad",
            Team::Human,
            Vec3::new(0.0, 0.0, 0.0),
            None,
        );

        run_aura_frames(&mut app);
        assert_eq!(
            current_health(&app, worker),
            1.0,
            "repair pad should stay offline while the base is low power"
        );

        app.world_mut()
            .resource_mut::<Economies>()
            .get_mut(Team::Human)
            .power_capacity = 20;
        let unfinished_worker =
            spawn_test_unit(&mut app, "Worker", Team::Human, Vec3::new(6.0, 0.0, 0.0));
        set_health_current(&mut app, unfinished_worker, 1.0);
        let unfinished_pad = spawn_aura_structure(
            &mut app,
            "RepairPad",
            Team::Human,
            Vec3::new(6.0, 0.0, 1.0),
            Some(UnderConstruction {
                remaining: 1.0,
                total: 1.0,
                cost: registry::Cost { ore: 0, crystal: 0 },
                free_harvester_origin: None,
            }),
        );

        run_aura_frames(&mut app);
        assert_eq!(
            current_health(&app, unfinished_worker),
            1.0,
            "repair pad should not repair before construction completes"
        );

        app.world_mut()
            .entity_mut(unfinished_pad)
            .remove::<UnderConstruction>();
        run_aura_frames(&mut app);
        assert!(
            current_health(&app, unfinished_worker) > 1.5,
            "repair pad should start repairing after construction completes"
        );
    }

