    #[test]
    fn repair_order_clears_unfinished_structure_targets_like_godot() {
        let mut app = repair_order_test_app();
        let target = spawn_test_structure(&mut app, "PowerReactor", Team::Human, Vec3::ZERO);
        let target_def = registry::entity("PowerReactor").expect("registry should include reactor");
        set_health_current(&mut app, target, target_def.health - 4.0);
        app.world_mut()
            .entity_mut(target)
            .insert(UnderConstruction {
                remaining: 4.0,
                total: 8.0,
                cost: registry::Cost { ore: 5, crystal: 0 },
                free_harvester_origin: None,
            });
        let engineer = spawn_test_unit(
            &mut app,
            "EngineerDrone",
            Team::Human,
            Vec3::new(0.5, 0.0, 0.0),
        );
        let target_position = unit_position(&app, target);
        app.world_mut().entity_mut(engineer).insert((
            RepairOrder { target },
            MoveOrder {
                target: target_position,
            },
        ));
        let damaged_health = current_health(&app, target);

        app.update();

        let engineer_ref = app.world().entity(engineer);
        assert!(
            engineer_ref.get::<RepairOrder>().is_none(),
            "Godot repair target validation rejects unfinished structures"
        );
        assert!(
            engineer_ref.get::<MoveOrder>().is_none(),
            "clearing invalid repair should also clear movement toward that target"
        );
        assert_eq!(
            current_health(&app, target),
            damaged_health,
            "unfinished structures should not receive active repair order healing"
        );
    }

