    #[test]
    fn neutral_income_timer_advances_without_payment_like_godot() {
        let mut income = IncomeSource {
            ore: 1,
            crystal: 0,
            interval: 6.0,
            remaining: 1.0,
        };

        assert_eq!(advance_income_source(&mut income, 1.25, false), (0, 0));
        assert!((income.remaining - 5.75).abs() < f32::EPSILON);

        assert_eq!(advance_income_source(&mut income, 5.5, true), (0, 0));
        assert!((income.remaining - 0.25).abs() < f32::EPSILON);

        assert_eq!(advance_income_source(&mut income, 0.3, true), (1, 0));
        assert!((income.remaining - 5.95).abs() < 0.0001);
    }

    #[test]
    fn ai_resource_collectors_choose_resource_or_dropoff_like_godot() {
        let mut app = ai_resource_collection_test_app();
        let dropoff = spawn_test_structure(&mut app, "CommandCenter", Team::Demon, Vec3::ZERO);
        let resource =
            spawn_test_resource_node(&mut app, ResourceKind::Ore, 12, Vec3::new(4.0, 0.0, 0.0));
        let empty_harvester = spawn_test_unit(
            &mut app,
            "OreHarvester",
            Team::Demon,
            Vec3::new(1.0, 0.0, 0.0),
        );
        let full_harvester = spawn_test_unit(
            &mut app,
            "OreHarvester",
            Team::Demon,
            Vec3::new(2.0, 0.0, 0.0),
        );
        insert_test_resource_cargo(&mut app, empty_harvester, "OreHarvester");
        insert_test_resource_cargo(&mut app, full_harvester, "OreHarvester");
        {
            let mut full_entity = app.world_mut().entity_mut(full_harvester);
            let mut cargo = full_entity
                .get_mut::<ResourceCargo>()
                .expect("ore harvester should have cargo");
            cargo.ore = cargo.capacity;
        }

        app.update();

        let empty_order = *app
            .world()
            .entity(empty_harvester)
            .get::<HarvestOrder>()
            .expect("empty AI harvester should receive a resource order");
        assert_eq!(empty_order.resource, Some(resource));
        assert!(matches!(empty_order.state, HarvestState::MovingToResource));

        let full_order = *app
            .world()
            .entity(full_harvester)
            .get::<HarvestOrder>()
            .expect("full AI harvester should receive a dropoff order");
        assert!(matches!(full_order.state, HarvestState::MovingToDropoff));
        assert!(
            app.world().entity(dropoff).get::<Structure>().is_some(),
            "test dropoff should remain a valid constructed structure"
        );
    }

