    #[test]
    fn hold_position_command_matches_godot_waiting_and_guard_area_resume() {
        let mut app = combat_test_app();
        let tank = spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::ZERO);
        app.world_mut()
            .entity_mut(tank)
            .insert((Selected, HoldPosition { enabled: true }));
        let enemy = spawn_combat_target(&mut app, Team::Demon, Vec3::new(2.0, 0.0, 0.0));
        let enemy_before = current_health(&app, enemy);

        app.update();
        app.update();

        assert_eq!(
            current_health(&app, enemy),
            enemy_before,
            "holding Godot combat units should wait without auto-acquiring visible enemies"
        );
        assert!(
            app.world().entity(tank).get::<AttackOrder>().is_none(),
            "hold position should keep the tank in waiting-for-targets instead of chasing"
        );

        app.init_resource::<TestCommandResult>()
            .add_systems(Update, run_test_guard_area_command);
        app.update();
        app.update();

        let result = command_result(&app);
        assert!(result.attempted && result.handled);
        assert!(
            !app.world()
                .entity(tank)
                .get::<HoldPosition>()
                .expect("tank should keep hold position state")
                .enabled,
            "Godot guard-area command should clear hold-position stance"
        );
        assert!(
            current_health(&app, enemy) < enemy_before,
            "guard area should restore automatic target acquisition"
        );
        assert!(
            app.world().entity(tank).get::<AttackOrder>().is_some(),
            "guarding units should acquire the nearby enemy after hold is cleared"
        );
    }

