    #[test]
    fn hold_position_disable_preserves_orders_like_godot() {
        let mut app = hold_position_test_app();
        let tank = spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::ZERO);
        let move_target = Vec3::new(4.0, 0.0, 0.0);
        let queued_target = Vec3::new(8.0, 0.0, 0.0);
        app.world_mut().entity_mut(tank).insert((
            Selected,
            HoldPosition { enabled: true },
            MoveOrder {
                target: move_target,
            },
            OrderQueue {
                orders: VecDeque::from([UnitQueuedOrder::AttackMove(queued_target)]),
            },
        ));

        app.update();

        let result = command_result(&app);
        assert!(result.attempted && result.handled);
        let tank_ref = app.world().entity(tank);
        assert!(
            !tank_ref
                .get::<HoldPosition>()
                .expect("tank should keep hold position state")
                .enabled
        );
        assert_eq!(
            tank_ref.get::<MoveOrder>().map(|order| order.target),
            Some(move_target),
            "Godot setting hold_position=false does not clear the current action"
        );
        match tank_ref
            .get::<OrderQueue>()
            .and_then(|queue| queue.orders.front())
        {
            Some(UnitQueuedOrder::AttackMove(target)) => assert_eq!(*target, queued_target),
            _ => panic!("Godot setting hold_position=false preserves queued actions"),
        }
    }

