    #[test]
    fn force_move_enemy_target_matches_godot_alt_right_click() {
        let tank = test_unit("Tank");
        let enemy = test_entity(90);
        let choices = OrderTargetChoices {
            supply_crate_position: None,
            resource_target: None,
            resource_dropoff_target: None,
            enemy_target: Some(enemy),
            repair_target: None,
            construct_target: None,
            garrison_target: None,
            follow_target: None,
        };
        let base_context = UnitOrderContext {
            force_move: false,
            enemy_target_capturable: false,
            attack_move: false,
            patrol: false,
            origin: Vec3::ZERO,
            point: Vec3::new(3.0, 0.0, 0.0),
            offset: Vec3::new(0.8, 0.0, -0.4),
        };

        let normal_order = desired_order_for_selected_unit(&tank, choices, base_context);
        assert!(
            matches!(normal_order, Some(UnitQueuedOrder::Attack(target)) if target == enemy),
            "normal Godot right-click on an enemy target should attack"
        );

        let force_order = desired_order_for_selected_unit(
            &tank,
            choices,
            UnitOrderContext {
                force_move: true,
                ..base_context
            },
        );
        assert!(
            matches!(
                force_order,
                Some(UnitQueuedOrder::ForceFollow { target, offset })
                    if target == enemy && offset == base_context.offset
            ),
            "Alt right-click should force movement to enemy targets instead of attacking"
        );

        let engineer = test_unit("EngineerDrone");
        let capture_order = desired_order_for_selected_unit(
            &engineer,
            choices,
            UnitOrderContext {
                enemy_target_capturable: true,
                ..base_context
            },
        );
        assert!(
            matches!(capture_order, Some(UnitQueuedOrder::Capture(target)) if target == enemy),
            "capture-capable units should prefer capture for capturable enemy targets"
        );

        let tank_order = desired_order_for_selected_unit(
            &tank,
            choices,
            UnitOrderContext {
                enemy_target_capturable: true,
                ..base_context
            },
        );
        assert!(
            matches!(tank_order, Some(UnitQueuedOrder::Attack(target)) if target == enemy),
            "non-capturing combat units should fall back to attacking capturable enemy targets"
        );
    }

