    #[test]
    fn default_menu_factory_rally_point_sends_new_tanks_to_target() {
        let mut app = stateful_match_flow_test_app(MatchSetupSettings::default());
        app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(
            Duration::from_secs_f32(1.0),
        ));
        app.update();

        press_key(&mut app, KeyCode::Enter, 3);

        assert_eq!(app_screen(&app), AppScreen::InMatch);
        let (factory, _, factory_position, constructed) =
            structure_snapshots_by_id(&mut app, "VehicleFactory")
                .into_iter()
                .find(|(_, team, _, constructed)| *team == Team::Human && *constructed)
                .expect(
                    "default playable skirmish should spawn a constructed player VehicleFactory",
                );
        assert!(constructed);
        attach_test_window_to_main_camera(&mut app, factory_position);
        click_selection_at_world(&mut app, factory_position, false);
        assert!(
            app.world().entity(factory).get::<Selected>().is_some(),
            "left-clicking the visible VehicleFactory should select it before setting a rally point"
        );
        app.update();

        let (rally_button, _, _) =
            enabled_command_slot_for_action(&mut app, BuildAction::SetRallyPoint);
        click_command_button(&mut app, rally_button);
        assert!(
            app.world().resource::<CommandMode>().rally_point,
            "clicking the production structure rally command should arm rally targeting"
        );

        let rally_target = factory_position + Vec3::new(10.0, 0.0, -4.0);
        attach_test_window_to_main_camera(&mut app, rally_target);
        right_click_order_at_world(&mut app, rally_target);
        let rally_point = *app
            .world()
            .entity(factory)
            .get::<RallyPoint>()
            .expect("VehicleFactory should carry RallyPoint");
        assert!(
            rally_point
                .target
                .is_some_and(|target| xz_distance(target, rally_target) < 0.05),
            "right-clicking a terrain target in rally mode should set the factory rally point"
        );
        assert_eq!(rally_point.target_unit, None);

        let tanks_before = unit_count_by_id(&mut app, Team::Human, "Tank");
        let (tank_button, _, _) =
            enabled_command_slot_for_action(&mut app, BuildAction::Train("Tank"));
        click_command_button(&mut app, tank_button);
        for _ in 0..120 {
            app.update();
            if unit_count_by_id(&mut app, Team::Human, "Tank") > tanks_before {
                break;
            }
        }

        let world = app.world_mut();
        let mut tanks = world.query::<(Entity, &Team, &Unit, &Transform, Option<&MoveOrder>)>();
        let rallying_tanks = tanks
            .iter(world)
            .filter(|(_, team, unit, _, move_order)| {
                **team == Team::Human
                    && unit.id == "Tank"
                    && move_order
                        .is_some_and(|order| xz_distance(order.target, rally_target) < 0.05)
            })
            .map(|(entity, _, _, transform, _)| (entity, transform.translation))
            .collect::<Vec<_>>();
        assert!(
            !rallying_tanks.is_empty(),
            "a Tank produced after setting a factory rally point should receive MoveOrder toward the rally target"
        );
    }

    #[test]
    fn default_menu_right_click_tank_button_cancels_latest_queued_tank_and_refunds() {
        let mut app = stateful_match_flow_test_app(MatchSetupSettings::default());
        app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(
            Duration::from_secs_f32(1.0),
        ));
        app.update();

        press_key(&mut app, KeyCode::Enter, 3);

        assert_eq!(app_screen(&app), AppScreen::InMatch);
        let (factory, _, _, constructed) = structure_snapshots_by_id(&mut app, "VehicleFactory")
            .into_iter()
            .find(|(_, team, _, constructed)| *team == Team::Human && *constructed)
            .expect("default playable skirmish should spawn a constructed player VehicleFactory");
        assert!(constructed);
        let tank_def = registry::entity("Tank").expect("registry should include Tank");

        mouse_select_entities(
            &mut app,
            &[factory],
            "left-clicking the default VehicleFactory should select it before queuing Tanks",
        );
        app.update();

        let (tank_button, _, _) =
            enabled_command_slot_for_action(&mut app, BuildAction::Train("Tank"));
        let economy_before = app.world().resource::<Economies>().get(Team::Human).clone();
        click_command_button(&mut app, tank_button);
        click_command_button(&mut app, tank_button);

        {
            let queue = app.world().resource::<BuildQueue>();
            let tank_jobs = queue
                .0
                .iter()
                .filter(|job| {
                    job.team == Team::Human
                        && job.producer_entity == factory
                        && matches!(job.action, BuildAction::Train("Tank"))
                })
                .count();
            assert_eq!(
                tank_jobs, 2,
                "left-clicking the default Tank button twice should queue two Tank jobs"
            );
        }
        let economy_after_queue = app.world().resource::<Economies>().get(Team::Human);
        assert_eq!(
            economy_after_queue.ore,
            economy_before.ore - tank_def.cost.ore * 2
        );
        assert_eq!(
            economy_after_queue.crystal,
            economy_before.crystal - tank_def.cost.crystal * 2
        );

        right_click_command_button(&mut app, tank_button);

        {
            let queue = app.world().resource::<BuildQueue>();
            let tank_jobs = queue
                .0
                .iter()
                .filter(|job| {
                    job.team == Team::Human
                        && job.producer_entity == factory
                        && matches!(job.action, BuildAction::Train("Tank"))
                })
                .collect::<Vec<_>>();
            assert_eq!(
                tank_jobs.len(),
                1,
                "right-clicking the Tank button should cancel exactly one matching queued Tank"
            );
            assert!(
                tank_jobs[0].timer < tank_def.build_seconds,
                "right-click cancellation should keep the older in-progress Tank job and remove the newest matching Tank job"
            );
        }
        let economy_after_cancel = app.world().resource::<Economies>().get(Team::Human);
        assert_eq!(
            economy_after_cancel.ore,
            economy_before.ore - tank_def.cost.ore
        );
        assert_eq!(
            economy_after_cancel.crystal,
            economy_before.crystal - tank_def.cost.crystal
        );
    }

    #[test]
    fn default_menu_command_center_rally_to_friendly_unit_sends_new_workers_to_follow() {
        let mut app = stateful_match_flow_test_app(MatchSetupSettings::default());
        app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(
            Duration::from_secs_f32(1.0),
        ));
        app.update();

        press_key(&mut app, KeyCode::Enter, 3);

        assert_eq!(app_screen(&app), AppScreen::InMatch);
        let (command_center, _, command_center_position, constructed) =
            structure_snapshots_by_id(&mut app, "CommandCenter")
                .into_iter()
                .find(|(_, team, _, constructed)| *team == Team::Human && *constructed)
                .expect(
                    "default playable skirmish should spawn a constructed player CommandCenter",
                );
        assert!(constructed);
        let rally_target = first_unit_by_id(&mut app, Team::Human, "Worker")
            .expect("default playable skirmish should spawn a player Worker");
        let rally_target_position = unit_position(&app, rally_target);
        app.world_mut()
            .entity_mut(rally_target)
            .insert((VisibilityState { visible: true }, Visibility::Visible));

        attach_test_window_to_main_camera(&mut app, command_center_position);
        click_selection_at_world(&mut app, command_center_position, false);
        assert!(
            app.world()
                .entity(command_center)
                .get::<Selected>()
                .is_some(),
            "left-clicking the visible CommandCenter should select it before setting a friendly-unit rally point"
        );
        app.update();
        assert!(
            !app.world().resource::<CommandMode>().rally_point,
            "plain right-click friendly-unit rally should not require arming explicit rally mode"
        );

        attach_test_window_to_main_camera(&mut app, rally_target_position);
        right_click_order_at_world(&mut app, rally_target_position);
        let rally_point = *app
            .world()
            .entity(command_center)
            .get::<RallyPoint>()
            .expect("CommandCenter should carry RallyPoint");
        assert_eq!(
            rally_point.target_unit,
            Some(rally_target),
            "plain right-clicking a friendly unit with a selected CommandCenter should track that unit"
        );
        assert!(
            rally_point
                .target
                .is_some_and(|target| xz_distance(target, rally_target_position) < 0.05),
            "tracked friendly rally target should store the current target position"
        );

        let workers_before = unit_entities_by_id(&mut app, Team::Human, "Worker");
        let (worker_button, _, _) =
            enabled_command_slot_for_action(&mut app, BuildAction::Train("Worker"));
        click_command_button(&mut app, worker_button);
        for _ in 0..120 {
            app.update();
            if unit_entities_by_id(&mut app, Team::Human, "Worker").len() > workers_before.len() {
                break;
            }
        }
        let produced_worker = unit_entities_by_id(&mut app, Team::Human, "Worker")
            .into_iter()
            .find(|entity| !workers_before.contains(entity))
            .expect("default CommandCenter should produce a new Worker from its command button");

        assert!(
            app.world()
                .entity(produced_worker)
                .get::<FollowOrder>()
                .is_some_and(|order| order.target == rally_target && !order.allow_enemy),
            "a Worker produced after setting a friendly-unit rally point should follow that unit"
        );
        let produced_worker_position = unit_position(&app, produced_worker);
        let rally_target_position = unit_position(&app, rally_target);
        let produced_worker_radius = app
            .world()
            .entity(produced_worker)
            .get::<Selectable>()
            .expect("produced Worker should be selectable")
            .radius;
        let rally_target_radius = app
            .world()
            .entity(rally_target)
            .get::<Selectable>()
            .expect("friendly rally target should be selectable")
            .radius;
        if let Some(move_order) = app.world().entity(produced_worker).get::<MoveOrder>() {
            let expected_follow_move = unit_contact_move_target_position(
                produced_worker_position,
                produced_worker_radius,
                rally_target_position,
                rally_target_radius,
            );
            assert!(
                xz_distance(move_order.target, expected_follow_move) < 0.05,
                "friendly-unit rally MoveOrder should be the follow contact point, not a stale terrain target"
            );
        }
    }

    #[test]
    fn default_menu_command_center_resource_rally_sends_new_workers_to_harvest() {
        let mut app = stateful_match_flow_test_app(MatchSetupSettings::default());
        app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(
            Duration::from_secs_f32(1.0),
        ));
        app.update();

        press_key(&mut app, KeyCode::Enter, 3);
        for _ in 0..3 {
            app.update();
        }

        assert_eq!(app_screen(&app), AppScreen::InMatch);
        let (command_center, _, command_center_position, constructed) =
            structure_snapshots_by_id(&mut app, "CommandCenter")
                .into_iter()
                .find(|(_, team, _, constructed)| *team == Team::Human && *constructed)
                .expect(
                    "default playable skirmish should spawn a constructed player CommandCenter",
                );
        assert!(constructed);
        let (resource, _, resource_amount_before, resource_position, resource_visible) =
            runtime_resource_node_snapshots(&mut app)
                .into_iter()
                .filter(|(_, kind, amount, _, visible)| {
                    *kind == ResourceKind::Ore && *amount > 0 && *visible
                })
                .min_by(|(_, _, _, lhs, _), (_, _, _, rhs, _)| {
                    xz_distance(*lhs, command_center_position)
                        .partial_cmp(&xz_distance(*rhs, command_center_position))
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
                .expect("default player start should reveal at least one nearby ore node");
        assert!(
            resource_visible,
            "default player start should reveal the resource rally target"
        );

        attach_test_window_to_main_camera(&mut app, command_center_position);
        click_selection_at_world(&mut app, command_center_position, false);
        assert!(
            app.world()
                .entity(command_center)
                .get::<Selected>()
                .is_some(),
            "left-clicking the visible CommandCenter should select it before setting a resource rally point"
        );
        app.update();
        assert!(
            !app.world().resource::<CommandMode>().rally_point,
            "plain right-click resource rally should not require arming explicit rally mode"
        );

        attach_test_window_to_main_camera(&mut app, resource_position);
        right_click_order_at_world(&mut app, resource_position);
        let rally_point = *app
            .world()
            .entity(command_center)
            .get::<RallyPoint>()
            .expect("CommandCenter should carry RallyPoint");
        assert_eq!(
            rally_point.target_unit,
            Some(resource),
            "plain right-clicking a visible ore node with a selected CommandCenter should track that resource"
        );
        assert!(
            rally_point
                .target
                .is_some_and(|target| xz_distance(target, resource_position) < 0.05),
            "tracked resource rally target should store the current resource position"
        );

        let workers_before = unit_entities_by_id(&mut app, Team::Human, "Worker");
        let (worker_button, _, _) =
            enabled_command_slot_for_action(&mut app, BuildAction::Train("Worker"));
        click_command_button(&mut app, worker_button);
        for _ in 0..120 {
            app.update();
            if unit_entities_by_id(&mut app, Team::Human, "Worker").len() > workers_before.len() {
                break;
            }
        }
        let produced_worker = unit_entities_by_id(&mut app, Team::Human, "Worker")
            .into_iter()
            .find(|entity| !workers_before.contains(entity))
            .expect("default CommandCenter should produce a new Worker from its command button");
        assert!(
            app.world()
                .entity(produced_worker)
                .get::<HarvestOrder>()
                .is_some_and(|order| order.resource == Some(resource)),
            "a Worker produced after setting a resource rally point should harvest that resource"
        );

        let ore_after_spawn = app.world().resource::<Economies>().get(Team::Human).ore;
        for _ in 0..160 {
            app.update();
            let ore_now = app.world().resource::<Economies>().get(Team::Human).ore;
            let resource_now = app
                .world()
                .get::<ResourceNode>(resource)
                .map_or(0, |resource| resource.amount);
            if ore_now > ore_after_spawn && resource_now < resource_amount_before {
                break;
            }
        }
        let ore_after_harvest = app.world().resource::<Economies>().get(Team::Human).ore;
        let resource_after_harvest = app
            .world()
            .get::<ResourceNode>(resource)
            .map_or(0, |resource| resource.amount);
        assert!(
            resource_after_harvest < resource_amount_before,
            "resource-rallied Worker should mine the target ore node"
        );
        assert!(
            ore_after_harvest > ore_after_spawn,
            "resource-rallied Worker should deliver mined ore back to the player economy"
        );
    }

    #[test]
    fn default_menu_tank_attack_move_acquires_visible_enemy() {
        let mut app = stateful_match_flow_test_app(MatchSetupSettings::default());
        app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(
            Duration::from_secs_f32(1.0),
        ));
        app.update();

        press_key(&mut app, KeyCode::Enter, 3);

        assert_eq!(app_screen(&app), AppScreen::InMatch);
        let (factory, _, factory_position, constructed) =
            structure_snapshots_by_id(&mut app, "VehicleFactory")
                .into_iter()
                .find(|(_, team, _, constructed)| *team == Team::Human && *constructed)
                .expect(
                    "default playable skirmish should spawn a constructed player VehicleFactory",
                );
        assert!(constructed);

        attach_test_window_to_main_camera(&mut app, factory_position);
        click_selection_at_world(&mut app, factory_position, false);
        assert!(
            app.world().entity(factory).get::<Selected>().is_some(),
            "left-clicking the visible VehicleFactory should select it before training an attack-move Tank"
        );
        app.update();

        let tanks_before = unit_entities_by_id(&mut app, Team::Human, "Tank");
        let (tank_button, _, _) =
            enabled_command_slot_for_action(&mut app, BuildAction::Train("Tank"));
        click_command_button(&mut app, tank_button);
        for _ in 0..120 {
            app.update();
            if unit_entities_by_id(&mut app, Team::Human, "Tank").len() > tanks_before.len() {
                break;
            }
        }
        let tank = unit_entities_by_id(&mut app, Team::Human, "Tank")
            .into_iter()
            .find(|entity| !tanks_before.contains(entity))
            .expect("default VehicleFactory should produce a new Tank from its command button");
        let tank_position = unit_position(&app, tank);

        attach_test_window_to_main_camera(&mut app, tank_position);
        click_selection_at_world(&mut app, tank_position, false);
        assert!(
            app.world().entity(tank).get::<Selected>().is_some(),
            "left-clicking the produced Tank should select it before attack-move"
        );
        app.update();
        let (attack_move_button, _, _) =
            enabled_command_slot_for_action(&mut app, BuildAction::AttackMove);
        click_command_button(&mut app, attack_move_button);
        assert!(
            app.world().resource::<CommandMode>().attack_move,
            "clicking the Tank attack-move command should arm terrain targeting"
        );

        let destination = tank_position + Vec3::new(12.0, 0.0, -3.0);
        attach_test_window_to_main_camera(&mut app, destination);
        right_click_order_at_world(&mut app, destination);
        assert!(
            app.world()
                .entity(tank)
                .get::<AttackMoveOrder>()
                .is_some_and(|order| xz_distance(order.destination, destination) < 0.05),
            "right-clicking terrain in attack-move mode should assign an AttackMoveOrder"
        );
        assert!(
            !app.world().resource::<CommandMode>().attack_move,
            "issuing the terrain attack-move command should leave targeting mode"
        );

        let enemy_position = tank_position + Vec3::new(4.0, 0.0, 0.0);
        let enemy = spawn_test_unit(&mut app, "Tank", Team::Demon, enemy_position);
        app.world_mut()
            .entity_mut(enemy)
            .insert((VisibilityState { visible: true }, Visibility::Visible));

        for _ in 0..8 {
            app.update();
            if app
                .world()
                .entity(tank)
                .get::<AttackOrder>()
                .is_some_and(|order| order.target == enemy)
            {
                break;
            }
        }

        assert!(
            app.world()
                .entity(tank)
                .get::<AttackOrder>()
                .is_some_and(|order| order.target == enemy),
            "a Tank on attack-move should acquire a newly visible enemy inside sight"
        );
        assert!(
            app.world().entity(tank).get::<MoveOrder>().is_none(),
            "movement should pause while the attack-move target is being engaged"
        );
    }

