    #[test]
    fn default_menu_skirmish_can_produce_tank_and_finish_visible_enemy_match() {
        let mut app = stateful_match_flow_test_app(MatchSetupSettings::default());
        app.insert_resource(bevy::time::TimeUpdateStrategy::ManualDuration(
            Duration::from_secs_f32(1.0),
        ));
        app.update();

        press_key(&mut app, KeyCode::Enter, 3);

        assert_eq!(app_screen(&app), AppScreen::InMatch);
        assert_eq!(
            app.world().resource::<MatchSetupSettings>().startup_loadout,
            StartupLoadoutMode::PlaytestExpanded,
            "default cargo run match should start in the playable production loadout"
        );
        assert_eq!(
            app.world()
                .resource::<AiDifficultySettings>()
                .difficulty(Team::Demon),
            AiDifficulty::Easy,
            "default cargo run match should use an active Easy AI opponent"
        );
        let (factory, _, _, _) = structure_snapshots_by_id(&mut app, "VehicleFactory")
            .into_iter()
            .find(|(_, team, _, constructed)| *team == Team::Human && *constructed)
            .expect("default playable skirmish should spawn a constructed player VehicleFactory");
        assert!(
            structure_snapshots_by_id(&mut app, "CommandCenter")
                .into_iter()
                .any(|(_, team, _, constructed)| team == Team::Demon && constructed),
            "default playable skirmish should spawn a constructed enemy anchor"
        );

        mouse_select_entities(
            &mut app,
            &[factory],
            "left-clicking the default VehicleFactory should select it before queuing the attack group",
        );
        app.update();

        let target_tank_count = PRODUCTION_QUEUE_LIMIT + 1;
        let (tank_button, tank_slot_index, _) =
            enabled_command_slot_for_action(&mut app, BuildAction::Train("Tank"));
        for batch in 0..2 {
            let expected_total = if batch == 0 {
                PRODUCTION_QUEUE_LIMIT
            } else {
                target_tank_count
            };
            let mut queue_attempts = 0;
            while queue_attempts < 120 {
                let human_tank_jobs = {
                    let queue = app.world().resource::<BuildQueue>();
                    queue
                        .0
                        .iter()
                        .filter(|job| {
                            job.team == Team::Human
                                && job.producer_entity == factory
                                && matches!(job.action, BuildAction::Train("Tank"))
                        })
                        .count()
                };
                if unit_count_by_id(&mut app, Team::Human, "Tank") + human_tank_jobs
                    >= expected_total
                {
                    break;
                }
                queue_attempts += 1;
                app.world_mut()
                    .entity_mut(tank_button)
                    .insert(Interaction::Pressed);
                app.world_mut()
                    .resource_mut::<ButtonInput<MouseButton>>()
                    .press(MouseButton::Left);
                app.update();
                {
                    let mut mouse = app.world_mut().resource_mut::<ButtonInput<MouseButton>>();
                    mouse.release(MouseButton::Left);
                    mouse.clear();
                }
                app.world_mut()
                    .entity_mut(tank_button)
                    .insert(Interaction::None);
                app.update();
                for _ in 0..8 {
                    app.update();
                }
            }
            let human_tank_jobs = {
                let queue = app.world().resource::<BuildQueue>();
                queue
                    .0
                    .iter()
                    .filter(|job| {
                        job.team == Team::Human
                            && job.producer_entity == factory
                            && matches!(job.action, BuildAction::Train("Tank"))
                    })
                    .count()
            };
            let human_tanks_started =
                unit_count_by_id(&mut app, Team::Human, "Tank") + human_tank_jobs;
            let human_economy = app.world().resource::<Economies>().get(Team::Human);
            assert!(
                human_tanks_started >= expected_total,
                "clicking the default VehicleFactory Tank button should eventually start {expected_total} Tank jobs after mining funds the queue; started={human_tanks_started} queued={human_tank_jobs} ore={} crystal={} power={}/{} attempts={queue_attempts}",
                human_economy.ore,
                human_economy.crystal,
                human_economy.power_used,
                human_economy.power_capacity
            );
            for _ in 0..220 {
                app.update();
                if unit_count_by_id(&mut app, Team::Human, "Tank") >= expected_total {
                    break;
                }
            }
        }

        let human_tanks = unit_count_by_id(&mut app, Team::Human, "Tank");
        let queue_status = {
            let queue = app.world().resource::<BuildQueue>();
            queue
                .0
                .iter()
                .map(|job| {
                    format!(
                        "{:?}:{:.2}:{}",
                        job.team,
                        job.timer,
                        build_target_product(job.action)
                    )
                })
                .collect::<Vec<_>>()
                .join(",")
        };
        let (human_power_used, human_power_capacity, human_ore, human_crystal) = {
            let human_economy = app.world().resource::<Economies>().get(Team::Human);
            (
                human_economy.power_used,
                human_economy.power_capacity,
                human_economy.ore,
                human_economy.crystal,
            )
        };
        let match_phase = app.world().resource::<MatchState>().phase;
        let human_anchors = anchor_targets_by_team(&mut app, Team::Human).len();
        let demon_anchors = anchor_targets_by_team(&mut app, Team::Demon).len();
        assert!(
            human_tanks >= target_tank_count,
            "default menu skirmish should produce a {target_tank_count}-Tank attack group from command slot {tank_slot_index} under Easy AI pressure; got {human_tanks}; phase={match_phase:?}; anchors human={human_anchors} demon={demon_anchors}; queue=[{queue_status}] power={}/{} ore={} crystal={}",
            human_power_used,
            human_power_capacity,
            human_ore,
            human_crystal
        );
        for _ in 0..24 {
            if app.world().resource::<MatchState>().phase != MatchPhase::Running {
                break;
            }
            let Some((target, target_position)) = anchor_targets_by_team(&mut app, Team::Demon)
                .into_iter()
                .next()
            else {
                break;
            };
            let attackers = alive_weapon_units_by_team(&mut app, Team::Human);
            assert!(
                !attackers.is_empty(),
                "default skirmish should keep at least one player attack unit alive"
            );
            let selected_attackers = drag_select_some_entities(
                &mut app,
                &attackers,
                "drag-selecting produced player attack units should select an attack group",
            );
            app.world_mut()
                .entity_mut(target)
                .insert((VisibilityState { visible: true }, Visibility::Visible));
            attach_test_window_to_main_camera(&mut app, target_position);

            right_click_order_at_world(&mut app, target_position);

            let ordered_attackers = attackers
                .iter()
                .filter(|entity| {
                    app.world()
                        .get_entity(**entity)
                        .is_ok_and(|entity_ref| entity_ref.get::<AttackOrder>().is_some())
                })
                .count();
            if app.world().get_entity(target).is_ok() {
                let order_summary = order_summary_for_entities(&app, &attackers, target);
                assert!(
                    ordered_attackers > 0,
                    "right-clicking near a visible enemy anchor in the default match should issue AttackOrder from a mouse-selected group; selected={selected_attackers}; orders={order_summary}"
                );
            }
            for _ in 0..220 {
                app.update();
                if app.world().get_entity(target).is_err()
                    || app.world().resource::<MatchState>().phase != MatchPhase::Running
                {
                    break;
                }
            }
        }
        for _ in 0..8 {
            app.update();
            if app.world().resource::<MatchState>().phase == MatchPhase::HumanVictory {
                break;
            }
        }

        assert!(
            anchor_targets_by_team(&mut app, Team::Demon).is_empty(),
            "produced Tank group should be able to destroy all default enemy anchors"
        );
        assert_eq!(
            app.world().resource::<MatchState>().phase,
            MatchPhase::HumanVictory,
            "destroying the default enemy anchor should finish the match as player victory"
        );
    }

    #[test]
    fn selected_vehicle_factory_hotkey_queues_and_spawns_tank_through_panel() {
        let mut app = playable_production_shortcut_test_app();
        let tank_def = registry::entity("Tank").expect("registry should include Tank");
        let factory_origin = Vec3::new(0.0, 0.0, 0.0);
        spawn_test_structure(
            &mut app,
            "CommandCenter",
            Team::Human,
            Vec3::new(-4.0, 0.0, 0.0),
        );
        let factory = spawn_test_structure(&mut app, "VehicleFactory", Team::Human, factory_origin);
        app.world_mut().entity_mut(factory).insert(Selected);

        app.update();

        let (_, tank_slot_index, tank_hotkey) =
            enabled_command_slot_for_action(&mut app, BuildAction::Train("Tank"));
        let before = app.world().resource::<Economies>().get(Team::Human).clone();

        app.world_mut()
            .resource_mut::<ButtonInput<KeyCode>>()
            .press(tank_hotkey.key_code);
        app.update();

        {
            let queue = app.world().resource::<BuildQueue>();
            assert_eq!(queue.0.len(), 1);
            assert_eq!(queue.0[0].team, Team::Human);
            assert!(matches!(queue.0[0].action, BuildAction::Train("Tank")));
            assert_eq!(queue.0[0].producer_entity, factory);
        }
        let after_reservation = app.world().resource::<Economies>().get(Team::Human);
        assert_eq!(after_reservation.ore, before.ore - tank_def.cost.ore);
        assert_eq!(
            after_reservation.crystal,
            before.crystal - tank_def.cost.crystal
        );

        {
            let mut keyboard = app.world_mut().resource_mut::<ButtonInput<KeyCode>>();
            keyboard.release(tank_hotkey.key_code);
            keyboard.clear();
        }
        for _ in 0..(tank_def.build_seconds.ceil() as usize + 2) {
            app.update();
        }

        assert!(
            app.world().resource::<BuildQueue>().0.is_empty(),
            "queued Tank from slot {tank_slot_index} should complete production"
        );
        assert_eq!(
            unit_count_by_id(&mut app, Team::Human, "Tank"),
            1,
            "player-facing VehicleFactory command should spawn a playable Tank"
        );
    }

