    #[test]
    fn double_click_unit_selects_visible_owned_same_type_and_replaces_shift_selection_like_godot() {
        let mut app = selection_click_test_app(VisiblePlayer::per_player(Team::Human));
        let target = spawn_group_hotkey_unit(&mut app, "Tank", Team::Human, Vec3::ZERO, false);
        let same_type_visible = spawn_group_hotkey_unit(
            &mut app,
            "Tank",
            Team::Human,
            Vec3::new(2.0, 0.0, 0.0),
            false,
        );
        let previous_selection = spawn_group_hotkey_unit(
            &mut app,
            "Worker",
            Team::Human,
            Vec3::new(-2.0, 0.0, 0.0),
            true,
        );
        let enemy_same_type = spawn_group_hotkey_unit(
            &mut app,
            "Tank",
            Team::Demon,
            Vec3::new(0.0, 0.0, 2.0),
            false,
        );
        let hidden_same_type = spawn_group_hotkey_unit(
            &mut app,
            "Tank",
            Team::Human,
            Vec3::new(3.0, 0.0, 0.0),
            false,
        );
        app.world_mut()
            .entity_mut(hidden_same_type)
            .insert((VisibilityState { visible: false }, Visibility::Hidden));
        let offscreen_same_type = spawn_group_hotkey_unit(
            &mut app,
            "Tank",
            Team::Human,
            Vec3::new(50.0, 0.0, 0.0),
            false,
        );

        click_selection_at_world(&mut app, Vec3::ZERO, true);

        assert!(
            app.world()
                .entity(previous_selection)
                .get::<Selected>()
                .is_some(),
            "first Shift click should still be additive before the second click becomes a double-click"
        );
        assert!(
            app.world().entity(target).get::<Selected>().is_some(),
            "target should be selected after first click, selected={:?}, drag={:?}, double={:?}",
            selected_unit_debug(&mut app),
            app.world().resource::<SelectionDragState>(),
            app.world().resource::<DoubleClickState>()
        );
        {
            let double_click = app.world().resource::<DoubleClickState>();
            assert_eq!(double_click.last_unit, Some(target));
            assert_eq!(double_click.last_unit_type, Some("Tank"));
        }

        click_selection_at_world(&mut app, Vec3::ZERO, true);

        assert!(
            app.world().entity(target).get::<Selected>().is_some(),
            "target should remain selected after double-click, selected={:?}, drag={:?}, double={:?}",
            selected_unit_debug(&mut app),
            app.world().resource::<SelectionDragState>(),
            app.world().resource::<DoubleClickState>()
        );
        assert!(
            app.world()
                .entity(same_type_visible)
                .get::<Selected>()
                .is_some(),
            "double-click should select visible owned units of the same type"
        );
        assert!(
            app.world()
                .entity(previous_selection)
                .get::<Selected>()
                .is_none(),
            "Godot double-click selection replaces the previous selection even if Shift is held"
        );
        assert!(
            app.world()
                .entity(enemy_same_type)
                .get::<Selected>()
                .is_none()
        );
        assert!(
            app.world()
                .entity(hidden_same_type)
                .get::<Selected>()
                .is_none()
        );
        assert!(
            app.world()
                .entity(offscreen_same_type)
                .get::<Selected>()
                .is_none()
        );
    }

