    #[test]
    fn selection_drag_interrupt_only_applies_to_active_world_drags() {
        let window_size = Vec2::new(1280.0, 720.0);
        let active_world_drag = SelectionDragState {
            active: true,
            dragging: true,
            start: Vec2::new(100.0, 100.0),
            started_in_hud: false,
        };
        let hud_drag = SelectionDragState {
            started_in_hud: true,
            ..active_world_drag
        };
        let inactive_drag = SelectionDragState {
            active: false,
            ..active_world_drag
        };

        assert!(selection_drag_should_interrupt(
            &active_world_drag,
            Vec2::new(1.0, 320.0),
            window_size
        ));
        assert!(!selection_drag_should_interrupt(
            &hud_drag,
            Vec2::new(1.0, 320.0),
            window_size
        ));
        assert!(!selection_drag_should_interrupt(
            &inactive_drag,
            Vec2::new(1.0, 320.0),
            window_size
        ));
        assert!(!selection_drag_should_interrupt(
            &active_world_drag,
            Vec2::new(64.0, 320.0),
            window_size
        ));
    }

