    #[derive(Resource)]
    struct ProceduralModelUnderTest(ProceduralEntityModel);

    fn spawn_procedural_model_under_test(
        mut commands: Commands,
        model: Res<ProceduralModelUnderTest>,
    ) {
        let root = commands.spawn_empty().id();
        spawn_procedural_entity_model(&mut commands, root, model.0);
    }

    fn spawned_procedural_mesh_part_count(model: ProceduralEntityModel) -> usize {
        let mut app = App::new();
        app.add_plugins(MinimalPlugins)
            .init_resource::<Assets<Mesh>>()
            .init_resource::<Assets<StandardMaterial>>()
            .insert_resource(ProceduralModelUnderTest(model))
            .add_systems(Update, spawn_procedural_model_under_test);

        app.update();

        let world = app.world_mut();
        let mut mesh_q = world.query::<&Mesh3d>();
        mesh_q.iter(world).count()
    }

    #[test]
    fn procedural_only_godot_render_scenes_use_bevy_mesh_models() {
        for (id, model) in [
            ("LandMine", ProceduralEntityModel::LandMine),
            (
                "TeslaFenceSegment",
                ProceduralEntityModel::TeslaFenceSegment,
            ),
        ] {
            let def = registry::entity(id).expect("procedural-only entity should exist");
            assert!(
                def.render_parts.is_empty(),
                "{id} should still reflect the Godot procedural-only source scene"
            );
            assert_eq!(ProceduralEntityModel::for_entity_id(id), Some(model));
            assert_eq!(
                spawned_procedural_mesh_part_count(model),
                model.part_count(),
                "{id} should spawn a Bevy mesh child for every Godot procedural part"
            );
        }
    }

