    #[test]
    fn production_structure_hotkey_candidates_require_constructed_alive_match() {
        let barracks = Structure { id: "Barracks" };
        let tank = Structure { id: "Tank" };
        let alive = Health::new(20.0);
        let dead = Health {
            current: 0.0,
            max: 20.0,
        };
        let visible = VisibilityState { visible: true };
        let hidden = VisibilityState { visible: false };
        let under_construction = UnderConstruction {
            remaining: 2.0,
            total: 4.0,
            cost: registry::Cost::default(),
            free_harvester_origin: None,
        };

        assert!(is_production_structure_hotkey_candidate(
            &barracks,
            &alive,
            &visible,
            None,
            &["Barracks"]
        ));
        assert!(!is_production_structure_hotkey_candidate(
            &barracks,
            &dead,
            &visible,
            None,
            &["Barracks"]
        ));
        assert!(!is_production_structure_hotkey_candidate(
            &barracks,
            &alive,
            &hidden,
            None,
            &["Barracks"]
        ));
        assert!(!is_production_structure_hotkey_candidate(
            &barracks,
            &alive,
            &visible,
            Some(&under_construction),
            &["Barracks"]
        ));
        assert!(!is_production_structure_hotkey_candidate(
            &tank,
            &alive,
            &visible,
            None,
            &["Barracks"]
        ));
    }

