    #[test]
    fn rally_point_clamps_near_edge_terrain_targets_like_godot() {
        let original_unit = test_entity(7);
        let original_target = Vec3::new(18.0, 0.0, 12.0);
        let mut rally_point = RallyPoint {
            target: Some(original_target),
            target_unit: Some(original_unit),
        };

        assert!(!apply_rally_point_command(
            &mut rally_point,
            Vec3::new(
                -MAP_HALF_EXTENT - TERRAIN_TARGET_MAP_MARGIN_M - 0.5,
                0.0,
                -MAP_HALF_EXTENT,
            ),
            None,
        ));
        assert_eq!(rally_point.target, Some(original_target));
        assert_eq!(rally_point.target_unit, Some(original_unit));

        assert!(apply_rally_point_command(
            &mut rally_point,
            Vec3::new(-MAP_HALF_EXTENT - 1.0, 0.0, MAP_HALF_EXTENT + 1.0),
            None,
        ));
        assert_eq!(
            rally_point.target,
            Some(Vec3::new(-MAP_HALF_EXTENT, 0.0, MAP_HALF_EXTENT))
        );
        assert_eq!(rally_point.target_unit, None);

        let terrain_target = Vec3::new(8.0, 0.0, -6.0);
        assert!(apply_rally_point_command(
            &mut rally_point,
            terrain_target,
            None,
        ));
        assert_eq!(rally_point.target, Some(terrain_target));
        assert_eq!(rally_point.target_unit, None);

        let friendly_unit = test_entity(9);
        let friendly_position = Vec3::new(-4.0, 0.0, 5.0);
        assert!(apply_rally_point_command(
            &mut rally_point,
            Vec3::new(-MAP_HALF_EXTENT - 1.0, 0.0, 0.0),
            Some((friendly_unit, friendly_position)),
        ));
        assert_eq!(rally_point.target, Some(friendly_position));
        assert_eq!(rally_point.target_unit, Some(friendly_unit));
    }

    #[test]
    fn rally_point_tracks_and_clears_unit_targets_like_godot() {
        let friendly_unit = test_entity(12);
        let updated_position = Vec3::new(4.0, 0.0, -5.0);
        let mut rally_point = RallyPoint {
            target: Some(Vec3::ZERO),
            target_unit: Some(friendly_unit),
        };

        assert!(refresh_rally_point_target(
            &mut rally_point,
            Some((updated_position, true)),
        ));
        assert_eq!(rally_point.target, Some(updated_position));
        assert_eq!(rally_point.target_unit, Some(friendly_unit));

        assert!(refresh_rally_point_target(&mut rally_point, None));
        assert_eq!(rally_point.target, None);
        assert_eq!(rally_point.target_unit, None);

        rally_point = RallyPoint {
            target: Some(updated_position),
            target_unit: Some(friendly_unit),
        };
        assert!(refresh_rally_point_target(
            &mut rally_point,
            Some((updated_position, false)),
        ));
        assert_eq!(rally_point.target, None);
        assert_eq!(rally_point.target_unit, None);

        let terrain_target = Vec3::new(-2.0, 0.0, 9.0);
        rally_point = RallyPoint {
            target: Some(terrain_target),
            target_unit: None,
        };
        assert!(!refresh_rally_point_target(&mut rally_point, None));
        assert_eq!(rally_point.target, Some(terrain_target));
        assert_eq!(rally_point.target_unit, None);
    }

