    #[test]
    fn rally_target_accepts_owned_units_and_resources_like_godot() {
        let mut app = App::new();
        app.add_plugins(MinimalPlugins)
            .insert_resource(RallyTargetProbe {
                point: Vec3::ZERO,
                team: Team::Human,
                result: None,
            })
            .add_systems(Update, run_rally_target_probe);

        let friendly_unit =
            spawn_test_unit(&mut app, "Worker", Team::Human, Vec3::new(2.0, 0.0, 0.0));
        app.world_mut()
            .entity_mut(friendly_unit)
            .insert(VisibilityState { visible: true });
        let enemy_unit = spawn_test_unit(&mut app, "Worker", Team::Demon, Vec3::new(8.0, 0.0, 0.0));
        app.world_mut()
            .entity_mut(enemy_unit)
            .insert(VisibilityState { visible: true });
        let resource = app
            .world_mut()
            .spawn((
                Team::Neutral,
                Transform::from_translation(Vec3::new(-3.0, 0.0, 0.0)),
                Selectable { radius: 0.7 },
                VisibilityState { visible: true },
                ResourceNode {
                    kind: ResourceKind::Ore,
                    amount: 100,
                },
            ))
            .id();
        app.world_mut().spawn((
            Team::Neutral,
            Transform::from_translation(Vec3::new(-8.0, 0.0, 0.0)),
            Selectable { radius: 0.7 },
            VisibilityState { visible: true },
            SupplyCrate {
                effect: SupplyCrateEffect::Resources,
                pickup_radius: SUPPLY_CRATE_PICKUP_RADIUS,
                resource_ore: SUPPLY_CRATE_RESOURCE_ORE,
                resource_crystal: SUPPLY_CRATE_RESOURCE_CRYSTAL,
                repair_radius: SUPPLY_CRATE_REPAIR_RADIUS,
                repair_amount: SUPPLY_CRATE_REPAIR_AMOUNT,
            },
        ));

        app.world_mut().resource_mut::<RallyTargetProbe>().point = Vec3::new(2.0, 0.0, 0.0);
        app.update();
        assert_eq!(
            app.world().resource::<RallyTargetProbe>().result,
            Some((friendly_unit, Vec3::new(2.0, 0.0, 0.0)))
        );

        app.world_mut().resource_mut::<RallyTargetProbe>().point = Vec3::new(8.0, 0.0, 0.0);
        app.update();
        assert_eq!(app.world().resource::<RallyTargetProbe>().result, None);

        app.world_mut().resource_mut::<RallyTargetProbe>().point = Vec3::new(-3.0, 0.0, 0.0);
        app.update();
        assert_eq!(
            app.world().resource::<RallyTargetProbe>().result,
            Some((resource, Vec3::new(-3.0, 0.0, 0.0)))
        );

        app.world_mut().resource_mut::<RallyTargetProbe>().point = Vec3::new(-8.0, 0.0, 0.0);
        app.update();
        assert_eq!(app.world().resource::<RallyTargetProbe>().result, None);
    }

