    #[test]
    fn attack_order_target_validation_cleans_lost_or_invalid_targets_like_godot() {
        let relations = TeamRelations::default();
        let mut allied_relations = TeamRelations::default();
        allied_relations.set_allied(Team::Human, Team::Demon, true);
        let weapon = Weapon {
            range: 5.0,
            damage: 2.0,
            cooldown: 1.0,
            splash_radius: 0.0,
            splash_damage_multiplier: 0.0,
            structure_damage_multiplier: 1.0,
            cooldown_left: 0.0,
            can_attack_air: false,
            can_attack_ground: true,
        };
        let alive = Health::new(10.0);
        let dead = Health {
            current: 0.0,
            max: 10.0,
        };

        assert!(attack_order_target_valid(
            &Team::Human,
            &Team::Demon,
            MovementDomain::Terrain,
            &alive,
            &weapon,
            &relations
        ));
        assert!(!attack_order_target_valid(
            &Team::Human,
            &Team::Demon,
            MovementDomain::Terrain,
            &dead,
            &weapon,
            &relations
        ));
        assert!(!attack_order_target_valid(
            &Team::Human,
            &Team::Human,
            MovementDomain::Terrain,
            &alive,
            &weapon,
            &relations
        ));
        assert!(!attack_order_target_valid(
            &Team::Human,
            &Team::Demon,
            MovementDomain::Air,
            &alive,
            &weapon,
            &relations
        ));
        assert!(!attack_order_target_valid(
            &Team::Human,
            &Team::Demon,
            MovementDomain::Terrain,
            &alive,
            &weapon,
            &allied_relations
        ));
    }

