    #[test]
    fn target_loss_clears_unit_orders_like_godot_action_teardown() {
        let mut app = target_loss_order_test_app();

        let attack_target =
            spawn_test_unit(&mut app, "Tank", Team::Demon, Vec3::new(7.0, 0.0, -1.0));
        let attacker = spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(attacker).insert((
            AttackOrder {
                target: attack_target,
            },
            MoveOrder {
                target: Vec3::new(7.0, 0.0, -1.0),
            },
        ));

        let follow_target =
            spawn_test_unit(&mut app, "Worker", Team::Human, Vec3::new(8.0, 0.0, 0.0));
        let follower = spawn_test_unit(&mut app, "Worker", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(follower).insert((
            FollowOrder {
                target: follow_target,
                allow_enemy: false,
                offset: Vec3::ZERO,
            },
            MoveOrder {
                target: Vec3::new(8.0, 0.0, 0.0),
            },
        ));

        let repair_target =
            spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::new(9.0, 0.0, 1.0));
        let repairer = spawn_test_unit(&mut app, "EngineerDrone", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(repairer).insert((
            RepairOrder {
                target: repair_target,
            },
            MoveOrder {
                target: Vec3::new(9.0, 0.0, 1.0),
            },
        ));

        let capture_target = spawn_test_structure(
            &mut app,
            "PowerReactor",
            Team::Demon,
            Vec3::new(10.0, 0.0, 2.0),
        );
        let capturer = spawn_test_unit(&mut app, "EngineerDrone", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(capturer).insert((
            CaptureOrder {
                target: capture_target,
                elapsed: 0.0,
            },
            MoveOrder {
                target: Vec3::new(10.0, 0.0, 2.0),
            },
        ));

        let construct_target = spawn_test_structure(
            &mut app,
            "PowerReactor",
            Team::Human,
            Vec3::new(11.0, 0.0, 3.0),
        );
        app.world_mut()
            .entity_mut(construct_target)
            .insert(UnderConstruction {
                remaining: 4.0,
                total: 8.0,
                cost: registry::Cost { ore: 5, crystal: 3 },
                free_harvester_origin: None,
            });
        let constructor = spawn_test_unit(&mut app, "Worker", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(constructor).insert((
            ConstructOrder {
                target: construct_target,
            },
            MoveOrder {
                target: Vec3::new(11.0, 0.0, 3.0),
            },
        ));

        let garrison_target =
            spawn_test_tech_bunker(&mut app, Team::Human, Vec3::new(12.0, 0.0, 4.0));
        let infantry = spawn_test_unit(&mut app, "LightRifleInfantry", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(infantry).insert((
            GarrisonOrder {
                target: garrison_target,
            },
            MoveOrder {
                target: Vec3::new(12.0, 0.0, 4.0),
            },
        ));

        for target in [
            attack_target,
            follow_target,
            repair_target,
            capture_target,
            construct_target,
            garrison_target,
        ] {
            app.world_mut().entity_mut(target).despawn();
        }

        app.update();

        for (entity, label) in [
            (attacker, "attack"),
            (follower, "follow"),
            (repairer, "repair"),
            (capturer, "capture"),
            (constructor, "construct"),
            (infantry, "garrison"),
        ] {
            let entity_ref = app.world().entity(entity);
            assert!(
                entity_ref.get::<MoveOrder>().is_none(),
                "{label} should clear stale movement toward a lost target"
            );
        }
        assert!(app.world().entity(attacker).get::<AttackOrder>().is_none());
        assert!(app.world().entity(follower).get::<FollowOrder>().is_none());
        assert!(app.world().entity(repairer).get::<RepairOrder>().is_none());
        assert!(app.world().entity(capturer).get::<CaptureOrder>().is_none());
        assert!(
            app.world()
                .entity(constructor)
                .get::<ConstructOrder>()
                .is_none()
        );
        assert!(
            app.world()
                .entity(infantry)
                .get::<GarrisonOrder>()
                .is_none()
        );
    }

