    #[test]
    fn attack_move_and_patrol_mode_helpers_enable_exclusive_target_modes() {
        let mut command_mode = CommandMode {
            rally_point: true,
            pending_structure_placement: Some(PendingStructurePlacement::new("Barracks")),
            ..Default::default()
        };

        assert!(begin_attack_move_mode(&mut command_mode, true));
        assert!(command_mode.attack_move);
        assert!(!command_mode.patrol);
        assert!(!command_mode.rally_point);
        assert!(command_mode.support_power.is_none());
        assert!(command_mode.pending_structure_placement.is_none());

        assert!(begin_patrol_mode(&mut command_mode, true));
        assert!(!command_mode.attack_move);
        assert!(command_mode.patrol);

        assert!(!begin_attack_move_mode(&mut command_mode, false));
        assert!(command_mode.patrol);

        assert!(begin_rally_point_mode(&mut command_mode, true));
        assert!(!command_mode.attack_move);
        assert!(!command_mode.patrol);
        assert!(command_mode.rally_point);
    }

    #[test]
    fn keyboard_target_modes_clear_structure_placement_like_godot_targeting_modes() {
        let mut command_mode = CommandMode {
            rally_point: true,
            pending_structure_placement: Some(PendingStructurePlacement::new("Barracks")),
            ..Default::default()
        };

        assert!(toggle_attack_move_mode(&mut command_mode));
        assert!(command_mode.attack_move);
        assert!(!command_mode.patrol);
        assert!(!command_mode.rally_point);
        assert!(command_mode.support_power.is_none());
        assert!(command_mode.pending_structure_placement.is_none());

        assert!(!toggle_attack_move_mode(&mut command_mode));
        assert!(!command_mode.has_pending_interaction());

        command_mode.pending_structure_placement = Some(PendingStructurePlacement::new("Factory"));
        assert!(toggle_patrol_mode(&mut command_mode));
        assert!(!command_mode.attack_move);
        assert!(command_mode.patrol);
        assert!(!command_mode.rally_point);
        assert!(command_mode.support_power.is_none());
        assert!(command_mode.pending_structure_placement.is_none());

        command_mode.pending_structure_placement = Some(PendingStructurePlacement::new("Barracks"));
        assert!(toggle_support_power_mode(
            &mut command_mode,
            SupportPowerKind::Paradrop
        ));
        assert!(!command_mode.attack_move);
        assert!(!command_mode.patrol);
        assert!(!command_mode.rally_point);
        assert_eq!(command_mode.support_power, Some(SupportPowerKind::Paradrop));
        assert!(command_mode.pending_structure_placement.is_none());

        assert!(!toggle_support_power_mode(
            &mut command_mode,
            SupportPowerKind::Paradrop
        ));
        assert!(!command_mode.has_pending_interaction());
    }

