    #[test]
    fn camera_edge_pan_requires_mouse_motion_like_godot() {
        let window_size = Vec2::new(1280.0, 720.0);
        let left_edge_clear_of_hud = Some(Vec2::new(1.0, 200.0));
        let top_left = Some(Vec2::ZERO);

        assert_eq!(
            cursor_edge_pan_vector(left_edge_clear_of_hud, window_size, false, false),
            Vec2::ZERO,
            "Godot does not edge-scroll from an initialized cursor position until real mouse motion arrives"
        );
        assert_eq!(
            cursor_edge_pan_vector(left_edge_clear_of_hud, window_size, true, false),
            Vec2::new(-1.0, 0.0)
        );
        assert_eq!(
            cursor_edge_pan_vector(top_left, window_size, true, true),
            Vec2::ZERO,
            "cursor positions over HUD should not trigger edge panning"
        );
        assert_eq!(
            cursor_edge_pan_vector(None, window_size, true, false),
            Vec2::ZERO
        );
    }

    #[test]
    fn camera_edge_pan_overrides_keyboard_axis_like_godot() {
        let mut keyboard = ButtonInput::<KeyCode>::default();
        keyboard.press(KeyCode::KeyD);
        keyboard.press(KeyCode::KeyW);

        assert_eq!(
            camera_screen_pan_vector(
                &keyboard,
                Some(Vec2::new(1.0, 719.0)),
                Vec2::new(1280.0, 720.0),
                true,
                false,
            ),
            Vec2::new(-1.0, -1.0),
            "Godot edge panning assigns the edge axis instead of adding to keyboard movement"
        );
        assert_eq!(
            camera_screen_pan_vector(
                &keyboard,
                Some(Vec2::new(1.0, 719.0)),
                Vec2::new(1280.0, 720.0),
                false,
                false,
            ),
            Vec2::new(1.0, 1.0),
            "inactive edge panning should leave keyboard movement unchanged"
        );
    }

    #[test]
    fn camera_keyboard_rotation_waits_while_panning_like_godot() {
        assert_eq!(
            camera_arrow_rotation_from_key_states(false, true, false),
            1.0
        );
        assert_eq!(
            camera_arrow_rotation_from_key_states(true, false, false),
            -1.0
        );
        assert_eq!(
            camera_arrow_rotation_from_key_states(false, true, true),
            0.0,
            "Godot _physics_process handles movement first and skips arrow rotation when movement occurs"
        );
        assert_eq!(
            camera_arrow_rotation_from_key_states(true, true, false),
            0.0
        );
    }

    #[test]
    fn camera_pan_delta_uses_godot_vertical_speed_bias() {
        let distance = 10.0;
        let delta_seconds = 1.0;

        let horizontal = camera_pan_delta(0.0, distance, Vec2::X, delta_seconds);
        let vertical = camera_pan_delta(0.0, distance, Vec2::Y, delta_seconds);

        assert!((horizontal.length() - distance * CAMERA_PAN_SPEED_MULTIPLIER).abs() < 0.001);
        assert!(
            (vertical.length() - distance * CAMERA_PAN_SPEED_MULTIPLIER * 2.0).abs() < 0.001,
            "Godot IsometricCamera3D moves screen-y at double the screen-x rate"
        );
        assert!(
            (vertical.length() / horizontal.length() - 2.0).abs() < 0.001,
            "vertical camera panning should stay twice as fast as horizontal panning"
        );
    }

    #[test]
    fn camera_pan_delta_normalizes_diagonal_input_like_godot() {
        let distance = 10.0;
        let delta_seconds = 1.0;
        let diagonal = camera_pan_delta(0.0, distance, Vec2::new(1.0, 1.0), delta_seconds);
        let expected_x = distance * CAMERA_PAN_SPEED_MULTIPLIER / f32::sqrt(2.0);
        let expected_z = distance * CAMERA_PAN_SPEED_MULTIPLIER * 2.0 / f32::sqrt(2.0);

        assert!((diagonal.x - expected_x).abs() < 0.001);
        assert!((diagonal.z - expected_z).abs() < 0.001);
    }

    #[test]
    fn camera_bookmark_restores_focus_and_zoom() {
        let mut camera = RtsCamera {
            focus: Vec3::new(12.0, 0.0, 18.0),
            distance: 17.5,
            yaw: -0.5,
            pitch: -0.8,
            edge_pan_active: true,
        };
        let bookmark = CameraBookmark::capture(&camera);

        camera.focus = Vec3::new(-20.0, 0.0, -14.0);
        camera.distance = 34.0;
        camera.yaw = 0.1;
        camera.pitch = -1.0;
        bookmark.restore(&mut camera);

        assert_eq!(camera.focus, Vec3::new(12.0, 0.0, 18.0));
        assert_eq!(camera.distance, 17.5);
        assert_eq!(camera.yaw, -0.5);
        assert_eq!(camera.pitch, -0.8);
    }

    #[test]
    fn camera_bookmark_restore_safely_clamps_focus_and_zoom_like_godot() {
        let mut camera = RtsCamera {
            focus: Vec3::new(38.0, 0.0, -38.0),
            distance: 17.5,
            yaw: -0.5,
            pitch: -0.9,
            edge_pan_active: false,
        };
        let bookmark = CameraBookmark::capture(&camera);
        let bounds = MapBounds::from_size((20.0, 12.0));
        camera.focus = Vec3::ZERO;

        bookmark.restore_safely(&mut camera, bounds);

        assert_eq!(
            camera.focus,
            safe_camera_focus(Vec3::new(38.0, 0.0, -38.0), bounds),
            "Godot restores bookmarks through IsometricCamera3D.restore_view_state, which clamps to bounding planes"
        );
        assert!(
            (camera.distance - CAMERA_MAX_DISTANCE).abs() < 0.001,
            "Godot restore_view_state clamps camera size before restoring the view"
        );
        assert_eq!(camera.yaw, -0.5);
        assert_eq!(camera.pitch, -0.9);
    }

