    #[test]
    fn clickable_battle_log_entry_focuses_that_event_like_godot() {
        let mut app = battle_log_click_test_app();
        let initial_focus = Vec3::new(-3.0, 0.0, -3.0);
        let old_focus = Vec3::new(4.0, 0.0, 8.0);
        let new_focus = Vec3::new(12.0, 0.0, -6.0);
        app.insert_resource(RtsCamera::focused_on(initial_focus));
        {
            let mut battle_log = app.world_mut().resource_mut::<BattleLog>();
            push_battle_log(&mut battle_log, "单位遭到攻击", Some(old_focus));
            push_battle_log(&mut battle_log, "基地遭到攻击", Some(new_focus));
        }

        app.update();

        let old_entry_button = {
            let world = app.world_mut();
            let mut buttons = world.query::<(Entity, &BattleLogEntryButton)>();
            let buttons = buttons.iter(world).collect::<Vec<_>>();
            assert_eq!(
                buttons.len(),
                2,
                "focusable battle notifications should render as clickable entries"
            );
            buttons
                .into_iter()
                .find_map(|(entity, button)| (button.0 == 0).then_some(entity))
                .expect("old battle log entry should have its own clickable notification")
        };
        app.world_mut()
            .entity_mut(old_entry_button)
            .insert(Interaction::Pressed);
        app.world_mut()
            .resource_mut::<ButtonInput<MouseButton>>()
            .press(MouseButton::Left);

        app.update();

        assert_eq!(
            app.world().resource::<LatestBattleEvent>().focus,
            Some(new_focus),
            "latest battle event should still point at the newest focusable notification"
        );
        assert_eq!(
            app.world().resource::<RtsCamera>().focus,
            old_focus,
            "clicking an older notification should focus that notification's own event position"
        );
    }

    #[test]
    fn clickable_battle_log_entry_clamps_camera_focus_like_godot() {
        let mut app = battle_log_click_test_app();
        let bounds = MapBounds::from_size((22.0, 18.0));
        let old_focus = Vec3::new(-32.0, 0.0, 35.0);
        let new_focus = Vec3::new(0.0, 0.0, 0.0);
        app.insert_resource(bounds);
        app.insert_resource(RtsCamera::focused_on(Vec3::ZERO));
        {
            let mut battle_log = app.world_mut().resource_mut::<BattleLog>();
            push_battle_log(&mut battle_log, "单位遭到攻击", Some(old_focus));
            push_battle_log(&mut battle_log, "基地遭到攻击", Some(new_focus));
        }

        app.update();

        let old_entry_button = {
            let world = app.world_mut();
            let mut buttons = world.query::<(Entity, &BattleLogEntryButton)>();
            buttons
                .iter(world)
                .find_map(|(entity, button)| (button.0 == 0).then_some(entity))
                .expect("old battle log entry should render as a clickable notification")
        };
        app.world_mut()
            .entity_mut(old_entry_button)
            .insert(Interaction::Pressed);
        app.world_mut()
            .resource_mut::<ButtonInput<MouseButton>>()
            .press(MouseButton::Left);

        app.update();

        assert_eq!(
            app.world().resource::<RtsCamera>().focus,
            safe_camera_focus(old_focus, bounds),
            "clicking battle log entries should clamp camera focus through the same path as Godot"
        );
    }

