    #[test]
    fn minimap_battle_event_pings_clear_and_do_not_resurrect_when_radar_offline_like_godot() {
        let mut app = minimap_render_test_app();
        push_battle_log(
            &mut app.world_mut().resource_mut::<BattleLog>(),
            "单位遭到攻击",
            Some(Vec3::new(8.0, 0.0, 8.0)),
        );

        app.update();

        assert_eq!(
            minimap_ping_marker_count(&mut app),
            1,
            "online radar should draw active minimap battle-event pings"
        );

        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            let economy = economies.get_mut(Team::Human);
            economy.power_capacity = 0;
            economy.power_used = 1;
        }
        app.update();

        assert_eq!(
            minimap_ping_marker_count(&mut app),
            0,
            "low power should clear active minimap battle-event pings"
        );

        push_battle_log_with_kind(
            &mut app.world_mut().resource_mut::<BattleLog>(),
            "敌方超武发射",
            Some(Vec3::new(10.0, 0.0, 10.0)),
            BattleEventPingKind::EnemySuperweapon,
        );
        app.update();

        assert_eq!(
            minimap_ping_marker_count(&mut app),
            0,
            "offline radar should ignore new minimap battle-event pings"
        );

        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            let economy = economies.get_mut(Team::Human);
            economy.power_capacity = 2;
            economy.power_used = 1;
        }
        app.update();

        assert_eq!(
            minimap_ping_marker_count(&mut app),
            0,
            "restoring radar should not resurrect pings that were cleared or emitted offline"
        );
        assert!(
            app.world()
                .resource::<BattleLog>()
                .entries
                .iter()
                .any(|entry| entry.message == "敌方超武发射" && entry.focus.is_some()),
            "clearing minimap pings must not remove the underlying battle log focus event"
        );
    }

    #[test]
    fn minimap_battle_event_ping_expires_before_battle_log_entry_like_godot() {
        let mut app = minimap_render_test_app();
        let focus = Vec3::new(12.0, 0.0, -6.0);
        push_battle_log(
            &mut app.world_mut().resource_mut::<BattleLog>(),
            "基地遭到攻击",
            Some(focus),
        );

        app.update();

        assert_eq!(
            minimap_ping_marker_count(&mut app),
            1,
            "new battle events should create a visible minimap ping"
        );

        for _ in 0..3 {
            app.update();
        }

        assert_eq!(
            minimap_ping_marker_count(&mut app),
            0,
            "Godot minimap battle pings expire after their own four-second lifetime"
        );
        assert!(
            app.world()
                .resource::<BattleLog>()
                .entries
                .iter()
                .any(|entry| entry.message == "基地遭到攻击" && entry.focus == Some(focus)),
            "the longer-lived battle log entry should remain after the minimap ping expires"
        );
        assert_eq!(
            app.world().resource::<LatestBattleEvent>().focus,
            Some(focus),
            "expiring the minimap ping must not clear Space-to-latest-battle-event focus"
        );
    }

    #[test]
    fn minimap_world_projection_round_trips() {
        for world in [
            Vec3::ZERO,
            Vec3::new(-MAP_HALF_EXTENT, 0.0, -MAP_HALF_EXTENT),
            Vec3::new(MAP_HALF_EXTENT, 0.0, MAP_HALF_EXTENT),
            Vec3::new(7.25, 0.0, -11.5),
        ] {
            let local = minimap_local_position(world);
            let projected = minimap_world_position(local);
            assert!(
                xz_distance(world, projected) < 0.01,
                "world {world:?} should round-trip through minimap, got {projected:?}"
            );
        }
    }

    #[test]
    fn minimap_preserves_non_square_map_aspect_like_godot() {
        let wide_bounds = MapBounds::from_size((104.0, 54.0));
        let wide_rect = wide_bounds.minimap_content_rect();

        assert_eq!(wide_rect.left, 0.0);
        assert!((wide_rect.width - MINIMAP_SIZE_PX).abs() < 0.001);
        assert!((wide_rect.height - (MINIMAP_SIZE_PX * 54.0 / 104.0)).abs() < 0.001);
        assert!((wide_rect.top - ((MINIMAP_SIZE_PX - wide_rect.height) * 0.5)).abs() < 0.001);
        assert_eq!(
            minimap_local_position_in_bounds(Vec3::ZERO, wide_bounds),
            Vec2::splat(MINIMAP_SIZE_PX * 0.5),
            "centered Bevy map coordinates should stay centered in a letterboxed minimap"
        );
        assert_eq!(
            minimap_local_position_in_bounds(Vec3::new(-52.0, 0.0, 27.0), wide_bounds),
            Vec2::new(0.0, wide_rect.top),
            "north-west corner should use the top edge of the centered content rect"
        );
        assert_eq!(
            minimap_local_position_in_bounds(Vec3::new(52.0, 0.0, -27.0), wide_bounds),
            Vec2::new(MINIMAP_SIZE_PX, wide_rect.top + wide_rect.height),
            "south-east corner should use the bottom edge of the centered content rect"
        );
        assert!(
            minimap_world_position_from_local_in_bounds(Vec2::new(79.0, 4.0), wide_bounds)
                .is_none(),
            "clicks in vertical letterbox padding should not issue minimap commands"
        );

        let tall_bounds = MapBounds::from_size((50.0, 100.0));
        let tall_rect = tall_bounds.minimap_content_rect();
        assert_eq!(tall_rect.top, 0.0);
        assert!((tall_rect.left - ((MINIMAP_SIZE_PX - tall_rect.width) * 0.5)).abs() < 0.001);
        assert!(
            minimap_world_position_from_local_in_bounds(Vec2::new(4.0, 79.0), tall_bounds)
                .is_none(),
            "clicks in horizontal letterbox padding should not issue minimap commands"
        );
    }

    #[test]
    fn minimap_non_square_world_projection_round_trips_like_godot() {
        let bounds = MapBounds::from_size((104.0, 54.0));
        for world in [
            Vec3::ZERO,
            Vec3::new(-52.0, 0.0, -27.0),
            Vec3::new(52.0, 0.0, 27.0),
            Vec3::new(18.5, 0.0, -11.25),
        ] {
            let local = minimap_local_position_in_bounds(world, bounds);
            let projected = minimap_world_position_from_local_in_bounds(local, bounds)
                .expect("projected minimap local point should be inside the content rect");
            assert!(
                xz_distance(world, projected) < 0.01,
                "non-square world {world:?} should round-trip through minimap, got {projected:?}"
            );
        }
    }

