    #[test]
    fn minimap_right_click_queues_attack_move_like_godot_terrain_targeting() {
        let target = Vec3::new(6.0, 0.0, -4.0);
        let old_move_target = Vec3::new(-2.0, 0.0, 3.0);
        let mut app = minimap_input_test_app(target);
        let unit = spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(unit).insert((
            Selected,
            MoveOrder {
                target: old_move_target,
            },
        ));
        {
            let mut command_mode = app.world_mut().resource_mut::<CommandMode>();
            command_mode.attack_move = true;
        }
        app.world_mut()
            .resource_mut::<ButtonInput<KeyCode>>()
            .press(KeyCode::ShiftLeft);
        app.world_mut()
            .resource_mut::<ButtonInput<MouseButton>>()
            .press(MouseButton::Right);

        app.update();

        let entity = app.world().entity(unit);
        let move_order = entity
            .get::<MoveOrder>()
            .expect("queued minimap command should preserve the active order");
        assert_eq!(move_order.target, old_move_target);
        let queue = entity
            .get::<OrderQueue>()
            .expect("Shift minimap terrain targeting should queue the new order");
        assert_eq!(queue.orders.len(), 1);
        assert!(
            matches!(
                queue.orders.front(),
                Some(UnitQueuedOrder::AttackMove(destination))
                    if xz_distance(*destination, target) < 0.01
            ),
            "Godot minimap terrain targeting should respect attack-move mode"
        );
        let command_mode = app.world().resource::<CommandMode>();
        assert!(!command_mode.attack_move);
        assert!(!command_mode.patrol);
    }

