    #[test]
    fn scatter_targets_spread_units_away_from_pivot() {
        let left = Vec3::new(10.0, 0.0, 10.0);
        let right = Vec3::new(12.0, 0.0, 10.0);
        let targets = scatter_target_positions(&[left, right]);

        assert_eq!(targets.len(), 2);
        assert!(targets[0].x < left.x);
        assert!(targets[1].x > right.x);
        assert!(xz_distance(targets[0], targets[1]) > xz_distance(left, right));
    }

    #[test]
    fn scatter_targets_move_each_unit_outward_from_current_position_like_godot() {
        let near = Vec3::new(1.0, 0.0, 0.0);
        let far = Vec3::new(11.0, 0.0, 0.0);
        let targets = scatter_target_positions(&[near, far]);

        assert_eq!(targets.len(), 2);
        assert!(
            (xz_distance(near, targets[0]) - SCATTER_DISTANCE).abs() < 0.001,
            "Godot scatter moves each unit by the scatter distance from its current position"
        );
        assert!(
            (xz_distance(far, targets[1]) - SCATTER_DISTANCE).abs() < 0.001,
            "distant units should keep moving outward instead of snapping back toward the pivot"
        );
        assert!(targets[1].x > far.x);
    }

