    #[test]
    fn production_spawn_position_blocks_when_no_space_is_available() {
        let tank_def = registry::entity("Tank").expect("registry should include Tank");
        let factory_def =
            registry::entity("VehicleFactory").expect("registry should include VehicleFactory");
        let origin = Vec3::ZERO;
        let occupied = vec![(origin, factory_def.radius)];
        let spawn = find_production_spawn_position(
            origin,
            "VehicleFactory",
            tank_def.radius,
            3,
            &occupied,
            MapBounds::default(),
        )
        .expect("producer perimeter should have room for a tank");

        assert!(xz_distance(origin, spawn) > factory_def.radius + tank_def.radius);

        let blocked = vec![(origin, MAP_HALF_EXTENT * 3.0)];
        assert!(
            find_production_spawn_position(
                origin,
                "VehicleFactory",
                tank_def.radius,
                3,
                &blocked,
                MapBounds::default(),
            )
            .is_none()
        );
    }

