    #[test]
    fn cancel_queued_job_at_local_index_refunds_specific_queue_element() {
        let tank_def = registry::entity("Tank").expect("registry should include Tank");
        let worker_def = registry::entity("Worker").expect("registry should include Worker");
        let vehicle_factory_a = test_entity(1);
        let vehicle_factory_b = test_entity(2);
        let mut economies = Economies::default();
        let starting_ore = economies.human.ore;
        let starting_crystal = economies.human.crystal;
        let mut build_queue = BuildQueue::default();
        build_queue.0.push(BuildJob {
            team: Team::Human,
            action: BuildAction::Train("Tank"),
            producer_entity: vehicle_factory_a,
            producer_id: "VehicleFactory",
            timer: tank_def.build_seconds,
            origin: Vec3::ZERO,
        });
        build_queue.0.push(BuildJob {
            team: Team::Human,
            action: BuildAction::Train("Tank"),
            producer_entity: vehicle_factory_b,
            producer_id: "VehicleFactory",
            timer: tank_def.build_seconds,
            origin: Vec3::ZERO,
        });
        build_queue.0.push(BuildJob {
            team: Team::Human,
            action: BuildAction::Train("Worker"),
            producer_entity: vehicle_factory_a,
            producer_id: "VehicleFactory",
            timer: worker_def.build_seconds,
            origin: Vec3::ZERO,
        });

        assert!(cancel_queued_job_at_local_index(
            Team::Human,
            vehicle_factory_a,
            1,
            &mut build_queue,
            &mut economies,
        ));

        assert_eq!(build_queue.0.len(), 2);
        assert!(build_queue.0.iter().any(|job| {
            job.producer_entity == vehicle_factory_a && job.action == BuildAction::Train("Tank")
        }));
        assert!(build_queue.0.iter().any(|job| {
            job.producer_entity == vehicle_factory_b && job.action == BuildAction::Train("Tank")
        }));
        assert!(
            !build_queue
                .0
                .iter()
                .any(|job| job.action == BuildAction::Train("Worker"))
        );
        assert_eq!(economies.human.ore, starting_ore + worker_def.cost.ore);
        assert_eq!(
            economies.human.crystal,
            starting_crystal + worker_def.cost.crystal
        );
        assert!(!cancel_queued_job_at_local_index(
            Team::Human,
            vehicle_factory_a,
            1,
            &mut build_queue,
            &mut economies,
        ));
    }

