    #[test]
    fn queue_button_state_counts_matching_product_and_detects_full_queues() {
        let tank_def = registry::entity("Tank").expect("registry should include Tank");
        let worker_def = registry::entity("Worker").expect("registry should include Worker");
        let vehicle_factory_a = test_entity(1);
        let vehicle_factory_b = test_entity(2);
        let command_center = test_entity(3);
        let mut build_queue = BuildQueue::default();
        for _ in 0..PRODUCTION_QUEUE_LIMIT {
            build_queue.0.push(BuildJob {
                team: Team::Human,
                action: BuildAction::Train("Tank"),
                producer_entity: vehicle_factory_a,
                producer_id: "VehicleFactory",
                timer: tank_def.build_seconds,
                origin: Vec3::ZERO,
            });
        }
        build_queue.0.push(BuildJob {
            team: Team::Human,
            action: BuildAction::Train("Worker"),
            producer_entity: command_center,
            producer_id: "CommandCenter",
            timer: worker_def.build_seconds,
            origin: Vec3::ZERO,
        });

        let state = queue_button_state_for_product(
            Team::Human,
            "Tank",
            &[vehicle_factory_a, vehicle_factory_b],
            &build_queue,
        )
        .expect("producer list should produce a queue state");

        assert_eq!(state.count, PRODUCTION_QUEUE_LIMIT);
        assert!(!state.full);

        for _ in 0..PRODUCTION_QUEUE_LIMIT {
            build_queue.0.push(BuildJob {
                team: Team::Human,
                action: BuildAction::Train("Tank"),
                producer_entity: vehicle_factory_b,
                producer_id: "VehicleFactory",
                timer: tank_def.build_seconds,
                origin: Vec3::ZERO,
            });
        }
        let full_state = queue_button_state_for_product(
            Team::Human,
            "Tank",
            &[vehicle_factory_a, vehicle_factory_b],
            &build_queue,
        )
        .expect("producer list should produce a queue state");

        assert_eq!(full_state.count, PRODUCTION_QUEUE_LIMIT * 2);
        assert!(full_state.full);
    }

    #[test]
    fn cancel_jobs_for_producer_refunds_reserved_cost() {
        let mut economies = Economies::default();
        let tank_def = registry::entity("Tank").expect("registry should include Tank");
        let radar_def =
            registry::entity("RadarUplink").expect("registry should include RadarUplink");
        let vehicle_factory = test_entity(1);
        let command_center = test_entity(2);
        let starting_ore = economies.human.ore;
        let starting_crystal = economies.human.crystal;
        assert!(economies.get_mut(Team::Human).spend(tank_def.cost));
        assert!(economies.get_mut(Team::Human).spend(radar_def.cost));
        let after_reservation_ore = economies.human.ore;
        let after_reservation_crystal = economies.human.crystal;
        let mut build_queue = BuildQueue::default();
        build_queue.0.push(BuildJob {
            team: Team::Human,
            action: BuildAction::Train("Tank"),
            producer_entity: vehicle_factory,
            producer_id: "VehicleFactory",
            timer: tank_def.build_seconds,
            origin: Vec3::ZERO,
        });
        build_queue.0.push(BuildJob {
            team: Team::Human,
            action: BuildAction::Build("RadarUplink"),
            producer_entity: command_center,
            producer_id: "CommandCenter",
            timer: radar_def.build_seconds,
            origin: Vec3::ZERO,
        });

        cancel_jobs_for_producer(&mut build_queue, &mut economies, vehicle_factory);

        assert_eq!(build_queue.0.len(), 1);
        assert_eq!(build_queue.0[0].producer_id, "CommandCenter");
        assert_eq!(
            economies.human.ore,
            after_reservation_ore + tank_def.cost.ore
        );
        assert_eq!(
            economies.human.crystal,
            after_reservation_crystal + tank_def.cost.crystal
        );
        assert!(economies.human.ore < starting_ore);
        assert!(economies.human.crystal <= starting_crystal);
    }

    #[test]
    fn cancel_latest_queued_product_for_producers_refunds_newest_matching_job() {
        let mut economies = Economies::default();
        economies.human.ore = 10_000;
        economies.human.crystal = 10_000;
        let tank_def = registry::entity("Tank").expect("registry should include Tank");
        let vehicle_factory_a = test_entity(1);
        let vehicle_factory_b = test_entity(2);
        let starting_ore = economies.human.ore;
        let starting_crystal = economies.human.crystal;
        for _ in 0..3 {
            assert!(economies.get_mut(Team::Human).spend(tank_def.cost));
        }
        let mut build_queue = BuildQueue::default();
        build_queue.0.push(BuildJob {
            team: Team::Human,
            action: BuildAction::Train("Tank"),
            producer_entity: vehicle_factory_a,
            producer_id: "VehicleFactory",
            timer: tank_def.build_seconds,
            origin: Vec3::new(1.0, 0.0, 1.0),
        });
        build_queue.0.push(BuildJob {
            team: Team::Human,
            action: BuildAction::Train("Tank"),
            producer_entity: vehicle_factory_b,
            producer_id: "VehicleFactory",
            timer: tank_def.build_seconds,
            origin: Vec3::new(2.0, 0.0, 1.0),
        });
        build_queue.0.push(BuildJob {
            team: Team::Human,
            action: BuildAction::Train("Tank"),
            producer_entity: vehicle_factory_a,
            producer_id: "VehicleFactory",
            timer: tank_def.build_seconds * 0.5,
            origin: Vec3::new(3.0, 0.0, 1.0),
        });

        assert!(cancel_latest_queued_product_for_producers(
            Team::Human,
            "Tank",
            &[vehicle_factory_a],
            &mut build_queue,
            &mut economies,
        ));

        assert_eq!(build_queue.0.len(), 2);
        assert_eq!(build_queue.0[0].producer_entity, vehicle_factory_a);
        assert_eq!(build_queue.0[1].producer_entity, vehicle_factory_b);
        assert_eq!(economies.human.ore, starting_ore - tank_def.cost.ore * 2);
        assert_eq!(
            economies.human.crystal,
            starting_crystal - tank_def.cost.crystal * 2
        );
    }

