        let vehicle_factory_a = test_entity(1);
        let vehicle_factory_b = test_entity(2);
        let producers = [
            (
                vehicle_factory_a,
                "VehicleFactory",
                Vec3::new(1.0, 0.0, 1.0),
            ),
            (
                vehicle_factory_b,
                "VehicleFactory",
                Vec3::new(5.0, 0.0, 1.0),
            ),
        ];
        let mut build_queue = BuildQueue::default();

        let result = enqueue_build_jobs_for_producers(
            Team::Human,
            BuildAction::Train("Tank"),
            tank_def,
            &producers,
            false,
            &mut economies,
            &mut build_queue,
        );

        assert!(matches!(result, EnqueueBuildActionResult::Enqueued));
        assert_eq!(producer_build_queue_len(&build_queue, vehicle_factory_a), 1);
        assert_eq!(producer_build_queue_len(&build_queue, vehicle_factory_b), 1);
        assert_eq!(build_queue.0.len(), 2);
