    #[test]
    fn selection_info_runtime_updates_hp_rank_group_and_hides_like_godot() {
        fn current_selection_text(app: &mut App) -> String {
            let mut query = app
                .world_mut()
                .query_filtered::<&Text, With<SelectionText>>();
            query
                .single(app.world())
                .expect("selection text should be rendered")
                .0
                .clone()
        }

        let mut app = visible_player_hud_test_app(VisiblePlayer::per_player(Team::Human));
        app.world_mut().spawn((Text::new(""), StatsText));
        app.world_mut().spawn((Text::new(""), SelectionText));
        app.world_mut().spawn((Text::new(""), ProductionQueueText));

        let tank = spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(tank).insert(Selected);
        app.update();

        let text = current_selection_text(&mut app);
        assert!(
            text.contains("Tank"),
            "single selection should show unit name: {text}"
        );
        assert!(
            text.contains("HP 10/10"),
            "single selection should show current HP: {text}"
        );
        assert!(
            text.contains("ATK"),
            "single selection should show combat stats: {text}"
        );
        assert!(
            text.contains("军阶: 新兵"),
            "green single selection should show green rank text: {text}"
        );
        assert!(
            !text.contains("徽章"),
            "green single selection should not show a rank badge: {text}"
        );

        app.world_mut()
            .get_mut::<Health>(tank)
            .expect("tank should have health")
            .current = 7.0;
        app.world_mut()
            .get_mut::<Veterancy>(tank)
            .expect("tank should have veterancy")
            .rank = 1;
        app.update();

        let text = current_selection_text(&mut app);
        assert!(
            text.contains("HP 7/10"),
            "selection info should update when selected unit HP changes: {text}"
        );
        assert!(
            text.contains("军阶: 老兵") && text.contains("徽章 V"),
            "single promoted selection should show veteran rank and badge: {text}"
        );

        let worker = spawn_test_unit(&mut app, "Worker", Team::Human, Vec3::new(1.0, 0.0, 0.0));
        app.world_mut().entity_mut(worker).insert(Selected);
        app.world_mut().resource_mut::<UnitGroups>().slots[2] = vec![tank, worker];
        app.update();

        let text = current_selection_text(&mut app);
        assert!(
            text.contains("已选择 2"),
            "multi selection should show selected count: {text}"
        );
        assert!(
            text.contains("Tank x1") && text.contains("Worker x1"),
            "multi selection should summarize selected types: {text}"
        );
        assert!(
            text.contains("军阶: 老兵 x1"),
            "multi selection should summarize promoted ranks: {text}"
        );
        assert!(
            text.contains("编组 3"),
            "selection info should show an exact control group match: {text}"
        );

        app.world_mut().entity_mut(tank).remove::<Selected>();
        app.world_mut().entity_mut(worker).remove::<Selected>();
        app.update();

        let text = current_selection_text(&mut app);
        assert!(
            text.is_empty(),
            "selection info should hide when nothing is selected: {text}"
        );
    }

    #[test]
    fn player_color_palette_supports_large_distinct_rosters() {
        const MIN_CORE_DISTANCE: f32 = 0.22;
        const MIN_EXTENDED_DISTANCE: f32 = 0.18;
        const MIN_LUMINANCE: f32 = 0.20;
        const MAX_LUMINANCE: f32 = 0.82;
        const CORE_SLOTS: usize = 8;

        assert!(PLAYER_COLOR_PALETTE.len() >= 20);
        for (index, color) in PLAYER_COLOR_PALETTE.iter().enumerate() {
            let luminance = relative_luminance(*color);
            assert!(
                (MIN_LUMINANCE..=MAX_LUMINANCE).contains(&luminance),
                "player color {index} should stay readable: {luminance}"
            );
            for (other_index, other) in PLAYER_COLOR_PALETTE.iter().enumerate().skip(index + 1) {
                assert_ne!(color, other, "player colors should be unique");
                let minimum_distance = if index < CORE_SLOTS && other_index < CORE_SLOTS {
                    MIN_CORE_DISTANCE
                } else {
                    MIN_EXTENDED_DISTANCE
                };
                assert!(
                    color_distance(*color, *other) >= minimum_distance,
                    "player colors {index} and {other_index} should be distinct"
                );
            }
        }
    }

