    #[test]
    fn attack_order_waits_for_chase_move_to_finish_like_godot_auto_attacking() {
        let mut app = combat_test_app();
        let enemy = spawn_combat_target(&mut app, Team::Demon, Vec3::new(2.0, 0.0, 0.0));
        let tank = spawn_test_unit(&mut app, "Tank", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(tank).insert((
            AttackOrder { target: enemy },
            MoveOrder {
                target: Vec3::new(1.0, 0.0, 0.0),
            },
        ));
        let enemy_before = current_health(&app, enemy);

        app.update();

        assert_eq!(
            current_health(&app, enemy),
            enemy_before,
            "Godot AutoAttacking uses a movement sub-action first and only fires after it finishes"
        );

        app.world_mut().entity_mut(tank).remove::<MoveOrder>();
        app.update();

        assert!(
            current_health(&app, enemy) < enemy_before,
            "once the chase movement is finished, the explicit attack order should fire"
        );
    }

    #[test]
    fn low_power_powered_defense_holds_fire_and_resumes_like_godot() {
        let mut app = combat_test_app();
        let turret_def = registry::entity("AntiGroundTurret")
            .expect("registry should include anti-ground turret");
        let turret_weapon = turret_def
            .weapon
            .expect("anti-ground turret should define a weapon");
        let turret = spawn_test_structure(&mut app, "AntiGroundTurret", Team::Human, Vec3::ZERO);
        app.world_mut().entity_mut(turret).insert(Weapon::new(
            turret_weapon.range,
            turret_weapon.damage,
            turret_weapon.cooldown,
            turret_weapon.splash_radius,
            turret_weapon.splash_damage_multiplier,
            turret_weapon.structure_damage_multiplier,
            turret_weapon.can_attack_air,
            turret_weapon.can_attack_ground,
        ));
        let target = spawn_combat_target(&mut app, Team::Demon, Vec3::new(4.0, 0.0, 0.0));
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            economies.human.power_used = -turret_def.power_delta;
            economies.human.power_capacity = 0;
        }

        app.update();

        assert_eq!(
            current_health(&app, target),
            10.0,
            "powered Godot defenses should not fire while their owner is low power"
        );
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            economies.human.power_capacity = -turret_def.power_delta;
        }

        app.update();

        assert!(
            current_health(&app, target) < 10.0,
            "powered Godot defenses should resume firing after power is restored"
        );
    }

