    #[test]
    fn production_queue_carries_same_frame_overflow_to_next_job_like_godot() {
        let mut app = production_queue_test_app();
        let origin = Vec3::new(-6.0, 0.0, -6.0);
        let barracks = spawn_test_structure(&mut app, "Barracks", Team::Human, origin);
        app.world_mut().entity_mut(barracks).insert(RallyPoint {
            target: None,
            target_unit: None,
        });
        let infantry_def =
            registry::entity("LightRifleInfantry").expect("registry should include infantry");
        {
            let mut build_queue = app.world_mut().resource_mut::<BuildQueue>();
            build_queue.0.push(BuildJob {
                team: Team::Human,
                action: BuildAction::Train("LightRifleInfantry"),
                producer_entity: barracks,
                producer_id: "Barracks",
                timer: 0.25,
                origin,
            });
            build_queue.0.push(BuildJob {
                team: Team::Human,
                action: BuildAction::Train("LightRifleInfantry"),
                producer_entity: barracks,
                producer_id: "Barracks",
                timer: 0.25,
                origin,
            });
        }

        app.update();

        assert!(
            app.world().resource::<BuildQueue>().0.is_empty(),
            "Godot production queue carries leftover frame delta into the next item"
        );
        let spawned_positions = {
            let world = app.world_mut();
            let mut units = world.query::<(&Team, &Unit, &Transform)>();
            units
                .iter(world)
                .filter_map(|(team, unit, transform)| {
                    (*team == Team::Human && unit.id == "LightRifleInfantry")
                        .then_some(transform.translation)
                })
                .collect::<Vec<_>>()
        };
        assert_eq!(spawned_positions.len(), 2);
        assert!(
            xz_distance(spawned_positions[0], spawned_positions[1])
                > infantry_def.radius * 2.0 + 0.05,
            "same-frame production should reserve the first spawn point before placing the second"
        );
    }

    #[test]
    fn low_power_production_progresses_slowly_then_resumes_full_speed_like_godot() {
        let mut app = production_queue_test_app();
        let barracks = spawn_test_structure(
            &mut app,
            "Barracks",
            Team::Human,
            Vec3::new(-6.0, 0.0, -6.0),
        );
        app.world_mut().entity_mut(barracks).insert(RallyPoint {
            target: None,
            target_unit: None,
        });
        let initial_timer = 1.5;
        app.world_mut()
            .resource_mut::<BuildQueue>()
            .0
            .push(BuildJob {
                team: Team::Human,
                action: BuildAction::Train("LightRifleInfantry"),
                producer_entity: barracks,
                producer_id: "Barracks",
                timer: initial_timer,
                origin: Vec3::new(-6.0, 0.0, -6.0),
            });
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            economies.human.power_used = 10;
            economies.human.power_capacity = 0;
        }

        app.update();

        let low_power_timer = app.world().resource::<BuildQueue>().0[0].timer;
        assert!(
            (low_power_timer - (initial_timer - LOW_POWER_PRODUCTION_SPEED_MULTIPLIER)).abs()
                < 0.001,
            "low-power Godot production should advance at the configured speed penalty"
        );
        {
            let mut economies = app.world_mut().resource_mut::<Economies>();
            economies.human.power_capacity = 10;
        }

        app.update();

        assert!(
            app.world().resource::<BuildQueue>().0.is_empty(),
            "restored power should let the queued unit finish at full production speed"
        );
    }

    #[test]
    fn siege_artillery_splash_damage_matches_godot_projectile_rules() {
        let mut app = combat_test_app();
        let artillery_def = registry::entity("SiegeArtilleryVehicle")
            .expect("registry should include SiegeArtilleryVehicle");
        let artillery_weapon = artillery_def
            .weapon
            .expect("SiegeArtilleryVehicle should define a weapon");
        assert!(artillery_weapon.splash_radius > 0.0);

        let primary = spawn_combat_target(&mut app, Team::Demon, Vec3::new(4.0, 0.0, 0.0));
        let nearby = spawn_combat_target(&mut app, Team::Demon, Vec3::new(5.0, 0.0, 0.0));
        let far = spawn_combat_target(&mut app, Team::Demon, Vec3::new(7.0, 0.0, 0.0));
        let friendly = spawn_combat_target(&mut app, Team::Human, Vec3::new(4.8, 0.0, 0.0));
        let artillery = app
            .world_mut()
            .spawn((
                Team::Human,
                Transform::from_translation(Vec3::ZERO),
                test_unit("SiegeArtilleryVehicle"),
                VisionRadius(artillery_def.sight_range),
                Weapon::new(
                    artillery_weapon.range,
                    artillery_weapon.damage,
                    artillery_weapon.cooldown,
                    artillery_weapon.splash_radius,
                    artillery_weapon.splash_damage_multiplier,
                    artillery_weapon.structure_damage_multiplier,
                    artillery_weapon.can_attack_air,
                    artillery_weapon.can_attack_ground,
                ),
                AttackOrder { target: primary },
            ))
            .id();

        app.update();

        assert_eq!(
            current_health(&app, primary),
            10.0 - artillery_weapon.damage,
            "primary target should take full direct damage"
        );
        assert_eq!(
            current_health(&app, nearby),
            10.0 - artillery_weapon.damage * artillery_weapon.splash_damage_multiplier,
            "nearby enemy should take splash damage"
        );
        assert_eq!(
            current_health(&app, far),
            10.0,
            "enemy outside splash radius should not be damaged"
        );
        assert_eq!(
            current_health(&app, friendly),
            10.0,
            "friendly units should not take splash damage"
        );
        assert!(app.world().entity(artillery).get::<AttackOrder>().is_some());
    }

